import subprocess, time, os, sys, urllib.request, urllib.error, socket
def free_port():
    import socket
    s=socket.socket(); s.bind(('127.0.0.1',0)); p=s.getsockname()[1]; s.close(); return p

class Server:
    def __init__(self, args, cwd="/workspace", env=None):
        self.port=free_port()
        self.args=["/workspace/executable","-p",str(self.port),"-i","127.0.0.1"]+args
        e=dict(os.environ)
        if env: e.update(env)
        self.proc=subprocess.Popen(self.args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, cwd=cwd, env=e, text=True)
        self.base=f"http://127.0.0.1:{self.port}"
        for i in range(100):
            if self.proc.poll() is not None:
                break
            try:
                urllib.request.urlopen(self.base+"/", timeout=0.5)
                break
            except Exception:
                time.sleep(0.05)
    def get(self, path, headers=None, method="GET", data=None):
        req=urllib.request.Request(self.base+path, headers=headers or {}, method=method, data=data)
        try:
            with urllib.request.urlopen(req, timeout=2) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()
        except Exception as e:
            return None, {}, str(e).encode()
    def stop(self):
        self.proc.terminate()
        try: out,_=self.proc.communicate(timeout=2)
        except: self.proc.kill(); out,_=self.proc.communicate()
        return out
