import subprocess, time, os, urllib.request, urllib.error, socket
def free_port():
    s=socket.socket(); s.bind(('127.0.0.1',0)); p=s.getsockname()[1]; s.close(); return p
class Server:
    def __init__(self,args,ready="/"):
        self.port=free_port(); self.base=f"http://127.0.0.1:{self.port}"
        self.proc=subprocess.Popen(["/workspace/executable","-p",str(self.port),"-i","127.0.0.1"]+args,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,cwd="/workspace")
        for i in range(100):
            if self.proc.poll() is not None: break
            try: urllib.request.urlopen(self.base+ready,timeout=.5); break
            except urllib.error.HTTPError: break
            except Exception: time.sleep(.05)
    def get(self,path,headers=None,method="GET",data=None):
        req=urllib.request.Request(self.base+path,headers=headers or {},method=method,data=data)
        try:
            with urllib.request.urlopen(req,timeout=2) as r: return r.status,dict(r.headers),r.read()
        except urllib.error.HTTPError as e: return e.code,dict(e.headers),e.read()
        except Exception as e: return None,{},str(e).encode()
    def stop(self):
        self.proc.terminate()
        try: out,_=self.proc.communicate(timeout=2)
        except: self.proc.kill(); out,_=self.proc.communicate()
        return out
