type clapExit struct {
	code int
}

func (e clapExit) Error() string { return fmt.Sprintf("exit %d", e.code) }

type parser struct {
	bin       string
	cfg       *Config
	present   map[string]bool
	cliCounts map[string]int
	usedOrder []string
	pathSeen  bool
}

func binaryName() string {
	if len(os.Args) == 0 || os.Args[0] == "" {
		return "miniserve"
	}
	a := os.Args[0]
	base := filepath.Base(a)
	if base == "." || base == "/" || base == "" {
		return a
	}
	return base
}

func renderHelp(raw, bin string) string {
	return strings.Replace(raw, "Usage: executable", "Usage: "+bin, 1)
}

func (p *parser) failMsg(msg string) clapExit {
	fmt.Fprint(os.Stderr, msg)
	return clapExit{2}
}
func (p *parser) genericUsage() string {
	return "Usage: " + p.bin + " [OPTIONS] [PATH]"
}
func (p *parser) smartUsage(before []string, includeID string, pathSeenOverride *bool) string {
	parts := []string{"Usage:", p.bin}
	seen := map[string]bool{}
	add := func(id string) {
		if id == "" || seen[id] {
			return
		}
		seen[id] = true
		parts = append(parts, specByID[id].fragment())
	}
	for _, id := range before {
		add(id)
	}
	add(includeID)
	pathSeen := p.pathSeen
	if pathSeenOverride != nil {
		pathSeen = *pathSeenOverride
	}
	if pathSeen {
		parts = append(parts, "<PATH>")
	} else {
		parts = append(parts, "[PATH]")
	}
	// If no option fragments, this would look odd; callers choose generic
	return strings.Join(parts, " ")
}
func possibleLine(vals []string) string {
	if len(vals) == 0 {
		return ""
	}
	return "\n  [possible values: " + strings.Join(vals, ", ") + "]"
}

func (p *parser) errInvalidValue(spec *argSpec, val, reason string) clapExit {
	msg := fmt.Sprintf("error: invalid value '%s' for '%s'", val, spec.fragment())
	if reason != "" {
		msg += ": " + reason
	}
	if len(spec.possible) > 0 {
		msg += possibleLine(spec.possible)
		// similar value tip (only for enum specs)
		if sim := suggest(val, spec.possible, false); sim != "" && reason == "" {
			msg += fmt.Sprintf("\n\n  tip: a similar value exists: '%s'", sim)
		}
	}
	msg += "\n\nFor more information, try '--help'.\n"
	return p.failMsg(msg)
}
func (p *parser) errMissingValue(spec *argSpec) clapExit {
	msg := fmt.Sprintf("error: a value is required for '%s' but none was supplied", spec.fragment())
	msg += possibleLine(spec.possible)
	msg += "\n\nFor more information, try '--help'.\n"
	return p.failMsg(msg)
}
func (p *parser) errMultiple(spec *argSpec) clapExit {
	msg := fmt.Sprintf("error: the argument '%s' cannot be used multiple times\n\n%s\n\nFor more information, try '--help'.\n", spec.fragment(), p.genericUsage())
	return p.failMsg(msg)
}
func (p *parser) errUnexpectedValue(spec *argSpec, val string, before []string) clapExit {
	usage := p.smartUsage(before, spec.id, nil)
	msg := fmt.Sprintf("error: unexpected value '%s' for '--%s' found; no more were expected\n\n%s\n\nFor more information, try '--help'.\n", val, spec.long, usage)
	return p.failMsg(msg)
}
func (p *parser) errUnexpected(argDisplay string, before []string) clapExit {
	// suggestion only for long args with a valid-looking name
	var suggestion *argSpec
	var tip string
	usage := ""
	if strings.HasPrefix(argDisplay, "--") && !strings.HasPrefix(argDisplay, "---") {
		name := strings.TrimPrefix(argDisplay, "--")
		if name != "" {
			if cand := suggestSpec(name); cand != nil {
				suggestion = cand
			}
		}
	}
	if suggestion != nil {
		tip = fmt.Sprintf("\n\n  tip: a similar argument exists: '--%s'", suggestion.long)
		usage = p.smartUsage(before, suggestion.id, nil)
	} else {
		// tip to pass as value for unknown options (not for positional extras)
		if strings.HasPrefix(argDisplay, "-") {
			tip = fmt.Sprintf("\n\n  tip: to pass '%s' as a value, use '-- %s'", argDisplay, argDisplay)
		}
		usage = p.genericUsage()
	}
	msg := fmt.Sprintf("error: unexpected argument '%s' found%s\n\n%s\n\nFor more information, try '--help'.\n", argDisplay, tip, usage)
	return p.failMsg(msg)
}

func suggest(name string, candidates []string, reverse bool) string {
	best := 0.70
	bestName := ""
	// iterate
	idxs := make([]int, len(candidates))
	for i := range candidates {
		if reverse {
			idxs[i] = len(candidates) - 1 - i
		} else {
			idxs[i] = i
		}
	}
	for _, idx := range idxs {
		cand := candidates[idx]
		conf := jaro(name, cand)
		if conf > best {
			best = conf
			bestName = cand
		}
	}
	return bestName
}
func suggestSpec(name string) *argSpec {
	cands := make([]string, len(argSpecs))
	for i, s := range argSpecs {
		cands[i] = s.long
	}
	bestName := suggest(name, cands, true)
	if bestName == "" {
		return nil
	}
	return specByLong[bestName]
}

// jaro similarity (strsim-compatible enough)
func jaro(aStr, bStr string) float64 {
	a := []rune(aStr)
	b := []rune(bStr)
	if len(a) == 0 && len(b) == 0 {
		return 1
	}
	if len(a) == 0 || len(b) == 0 {
		return 0
	}
	if len(a) == 1 && len(b) == 1 {
		if a[0] == b[0] {
			return 1
		}
		return 0
	}
	maxLen := len(a)
	if len(b) > maxLen {
		maxLen = len(b)
	}
	searchRange := maxLen/2 - 1
	if searchRange < 0 {
		searchRange = 0
	}
	bConsumed := make([]bool, len(b))
	matches := 0.0
	transpositions := 0.0
	bMatchIdx := 0
	for i := 0; i < len(a); i++ {
		start := i - searchRange
		if start < 0 {
			start = 0
		}
		end := i + searchRange + 1
		if end > len(b) {
			end = len(b)
		}
		for j := start; j < end; j++ {
			if bConsumed[j] {
				continue
			}
			if a[i] != b[j] {
				continue
			}
			bConsumed[j] = true
			matches++
			if j < bMatchIdx {
				transpositions++
			} else {
				bMatchIdx = j
				// count transpositions in a simplified way below instead
			}
			break
		}
	}
	// Proper transposition count: re-walk matched sequences
	if matches == 0 {
		return 0
	}
	// Collect matched chars in order from a and b using standard matching again
	// (reuse consumed flags from above to build b matched sequence)
	var bMatched []rune
	for j := 0; j < len(b); j++ {
		if bConsumed[j] {
			bMatched = append(bMatched, b[j])
		}
	}
	// a matched sequence: those a chars that matched (recompute flags)
	aMatchedFlags := make([]bool, len(a))
	bCons2 := make([]bool, len(b))
	for i := 0; i < len(a); i++ {
		start := i - searchRange
		if start < 0 {
			start = 0
		}
		end := i + searchRange + 1
		if end > len(b) {
			end = len(b)
		}
		for j := start; j < end; j++ {
			if bCons2[j] || a[i] != b[j] {
				continue
			}
			bCons2[j] = true
			aMatchedFlags[i] = true
			break
		}
	}
	var aMatched []rune
	for i := 0; i < len(a); i++ {
		if aMatchedFlags[i] {
			aMatched = append(aMatched, a[i])
		}
	}
	transpositions = 0
	for i := 0; i < len(aMatched) && i < len(bMatched); i++ {
		if aMatched[i] != bMatched[i] {
			transpositions++
		}
	}
	transpositions /= 2
	return ((matches / float64(len(a))) + (matches / float64(len(b))) + ((matches - transpositions) / matches)) / 3.0
}

func (p *parser) markUsed(id string) {
	if !p.present[id] {
		// usedOrder only for first occurrence (dedup)
		found := false
		for _, x := range p.usedOrder {
			if x == id {
				found = true
			}
		}
		if !found {
			p.usedOrder = append(p.usedOrder, id)
		}
	}
	p.present[id] = true
}

func parseAuthValue(s string) (AuthEntry, string) {
	parts := strings.SplitN(s, ":", 3)
	if len(parts) < 2 {
		return AuthEntry{}, "Invalid format for credentials string. Expected username:password, username:sha256:hash or username:sha512:hash"
	}
	if len(parts) == 2 {
		return AuthEntry{Username: parts[0], Plain: parts[1]}, ""
	}
	// len 3: decode hash first
	hashBytes, err := hex.DecodeString(parts[2])
	if err != nil {
		return AuthEntry{}, "Invalid format for password hash. Expected hex code"
	}
	if parts[1] != "sha256" && parts[1] != "sha512" {
		return AuthEntry{}, fmt.Sprintf("%s is not a valid hashing method. Expected sha256 or sha512", parts[1])
	}
	return AuthEntry{Username: parts[0], Method: parts[1], Hash: hashBytes}, ""
}

func parseHeaderValue(s string) (CustomHeader, string, bool) {
	// returns header, errReason, okIgnore (empty string accepted & ignored)
	if s == "" {
		return CustomHeader{}, "", true
	}
	idx := strings.Index(s, ":")
	if idx < 0 {
		return CustomHeader{}, "invalid header name", false
	}
	name := s[:idx]
	value := strings.Trim(s[idx+1:], " \t\r\n")
	// Validate header name tokens (RFC7230 token)
	if name == "" {
		return CustomHeader{}, "invalid header name", false
	}
	for _, r := range name {
		if !isTokenChar(r) {
			return CustomHeader{}, "invalid header name", false
		}
	}
	// newline inside value -> too many headers (httparse-like)
	if strings.ContainsAny(value, "\r\n") {
		return CustomHeader{}, "too many headers", false
	}
	// Also if original contains a newline anywhere else (after trim we removed trailing only)
	if strings.ContainsAny(s, "\r") {
		return CustomHeader{}, "too many headers", false
	}
	// Check raw string for embedded newline not at end
	if i := strings.Index(s, "\n"); i >= 0 && i != len(s)-1 {
		return CustomHeader{}, "too many headers", false
	}
	return CustomHeader{Name: name, Value: value}, "", false
}
func isTokenChar(r rune) bool {
	if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' {
		return true
	}
	switch r {
	case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
		return true
	}
	return false
}

func rustIntParseError(s string, signed bool) string {
	if s == "" {
		return "cannot parse integer from empty string"
	}
	return "invalid digit found in string"
}

// assign validates and stores a value; bool specs use value "true"
func (p *parser) assign(spec *argSpec, val string, isCLI bool) error {
	// multiple check for CLI (env reassign not called if cli present)
	if isCLI {
		p.cliCounts[spec.id]++
		if p.cliCounts[spec.id] > 1 && spec.kind != kindMulti && spec.kind != kindOptional {
			return p.errMultiple(spec)
		}
	}
	cfg := p.cfg
	isStringOpt := map[string]bool{
		"route_prefix": true, "title": true, "raw_media_type": true, "file_external_url": true,
	}
	isPathOpt := map[string]bool{
		"temp_directory": true, "index": true, "auth_file": true, "upload_files": true, "rm_files": true, "tls_cert": true, "tls_key": true,
	}
	// Empty value handling
	if val == "" {
		if spec.kind == kindBool {
			// env bool empty
			msg := fmt.Sprintf("error: a value is required for '%s' but none was supplied\n  [possible values: true, false]\n\nFor more information, try '--help'.\n", spec.fragment())
			return p.failMsg(msg)
		}
		if spec.kind == kindOptional || isPathOpt[spec.id] {
			return p.errMissingValue(spec)
		}
		if spec.id == "header" {
			// accepted & ignored, still marks present?
			p.markUsed(spec.id)
			return nil
		}
		if !isStringOpt[spec.id] {
			// fall through to type parsers which will report empty appropriately
			// enum: invalid value '' with possible values
			// numeric: cannot parse integer from empty string
		}
	}
	// validate by type
	switch spec.id {
	case "verbose", "spa", "pretty_urls", "random_route", "no_symlinks", "hidden", "qrcode", "directory_size", "mkdir", "enable_tar", "enable_tar_gz", "enable_zip", "compress", "dirs_first", "show_symlink_info", "hide_version", "hide_theme", "wget_footer", "print_manpage", "readme", "disable_indexing", "webdav", "help", "version":
		// val should be "true" or "false" (from env); CLI passes "true"
		if val != "true" && val != "false" {
			// invalid bool env value
			msg := fmt.Sprintf("error: invalid value '%s' for '%s'\n  [possible values: true, false]\n\nFor more information, try '--help'.\n", val, spec.fragment())
			return p.failMsg(msg)
		}
		b := val == "true"
		switch spec.id {
		case "verbose":
			cfg.Verbose = b
		case "spa":
			cfg.SPA = b
		case "pretty_urls":
			cfg.PrettyURLs = b
		case "random_route":
			cfg.RandomRoute = b
		case "no_symlinks":
			cfg.NoSymlinks = b
		case "hidden":
			cfg.Hidden = b
		case "qrcode":
			cfg.QRCode = b
		case "directory_size":
			cfg.DirectorySize = b
		case "mkdir":
			cfg.Mkdir = b
		case "enable_tar":
			cfg.EnableTar = b
		case "enable_tar_gz":
			cfg.EnableTarGz = b
		case "enable_zip":
			cfg.EnableZip = b
		case "compress":
			cfg.Compress = b
		case "dirs_first":
			cfg.DirsFirst = b
		case "show_symlink_info":
			cfg.SymlinkInfo = b
		case "hide_version":
			cfg.HideVersion = b
		case "hide_theme":
			cfg.HideTheme = b
		case "wget_footer":
			cfg.WgetFooter = b
		case "print_manpage":
			cfg.PrintManpage = b
		case "readme":
			cfg.Readme = b
		case "disable_indexing":
			cfg.DisableIndexing = b
		case "webdav":
			cfg.WebDAV = b
		}
	case "temp_directory":
		// validator: must exist and be a directory
		info, err := os.Stat(val)
		if err != nil || !info.IsDir() {
			reason := fmt.Sprintf("Upload temporary directory must exist and be a directory. Validate that path \"%s\" meets those requirements.", val)
			return p.errInvalidValue(spec, val, reason)
		}
		v := val
		cfg.TempDir = &v
	case "index":
		v := val
		cfg.Index = &v
	case "port":
		if val == "" {
			return p.errInvalidValue(spec, val, "cannot parse integer from empty string")
		}
		n, err := strconv.ParseInt(val, 10, 64)
		if err != nil {
			if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
				if strings.HasPrefix(val, "-") {
					return p.errInvalidValue(spec, val, "number too small to fit in target type")
				}
				return p.errInvalidValue(spec, val, "number too large to fit in target type")
			}
			return p.errInvalidValue(spec, val, "invalid digit found in string")
		}
		if n < 0 || n > 65535 {
			return p.errInvalidValue(spec, val, fmt.Sprintf("%d is not in 0..=65535", n))
		}
		cfg.Port = int(n)
	case "interfaces":
		ip := net.ParseIP(val)
		if ip == nil {
			return p.errInvalidValue(spec, val, "invalid IP address syntax")
		}
		cfg.Interfaces = append(cfg.Interfaces, val)
	case "auth":
		entry, reason := parseAuthValue(val)
		if reason != "" {
			return p.errInvalidValue(spec, val, reason)
		}
		cfg.Auth = append(cfg.Auth, entry)
	case "auth_file":
		v := val
		cfg.AuthFile = &v
	case "route_prefix":
		v := val
		cfg.RoutePrefixOpt = &v
	case "sorting_method", "sorting_order", "color_scheme", "color_scheme_dark", "on_duplicate", "size_display", "print_completions":
		// enum validate
		found := false
		for _, pv := range spec.possible {
			if pv == val {
				found = true
			}
		}
		if !found {
			return p.errInvalidValue(spec, val, "")
		}
		switch spec.id {
		case "sorting_method":
			cfg.SortMethod = val
		case "sorting_order":
			cfg.SortOrder = val
		case "color_scheme":
			cfg.ColorScheme = val
		case "color_scheme_dark":
			cfg.ColorSchemeDark = val
		case "on_duplicate":
			cfg.OnDuplicate = val
		case "size_display":
			cfg.SizeDisplay = val
		case "print_completions":
			v := val
			cfg.PrintShell = &v
		}
	case "media_type":
		found := false
		for _, pv := range spec.possible {
			if pv == val {
				found = true
			}
		}
		if !found {
			return p.errInvalidValue(spec, val, "")
		}
		cfg.MediaTypes = append(cfg.MediaTypes, val)
	case "upload_files":
		cfg.UploadProvided = true
		if val == "\x00NONE" {
			cfg.UploadDir = nil
		} else {
			v := val
			cfg.UploadDir = &v
		}
	case "rm_files":
		cfg.RMProvided = true
		if val == "\x00NONE" {
			cfg.RMDir = nil
		} else {
			v := val
			cfg.RMDir = &v
		}
	case "web_upload_concurrency":
		if val == "" {
			return p.errInvalidValue(spec, val, "cannot parse integer from empty string")
		}
		n, err := strconv.ParseUint(val, 10, 64)
		if err != nil {
			if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
				return p.errInvalidValue(spec, val, "number too large to fit in target type")
			}
			return p.errInvalidValue(spec, val, "invalid digit found in string")
		}
		cfg.WebConcurrency = strconv.FormatUint(n, 10)
	case "chmod":
		if val == "" {
			return p.errInvalidValue(spec, val, "cannot parse integer from empty string")
		}
		n, err := strconv.ParseUint(val, 8, 32)
		if err != nil {
			if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
				return p.errInvalidValue(spec, val, "number too large to fit in target type")
			}
			return p.errInvalidValue(spec, val, "invalid digit found in string")
		}
		v := uint32(n)
		cfg.Chmod = &v
	case "raw_media_type":
		v := val
		cfg.RawMediaType = &v
	case "title":
		v := val
		cfg.Title = &v
	case "header":
		h, reason, ignore := parseHeaderValue(val)
		if reason != "" {
			return p.errInvalidValue(spec, val, reason)
		}
		if !ignore {
			cfg.Headers = append(cfg.Headers, h)
		}
	case "tls_cert":
		v := val
		cfg.TLSCert = &v
	case "tls_key":
		v := val
		cfg.TLSKey = &v
	case "file_external_url":
		v := val
		cfg.FileExternalURL = &v
	}
	p.markUsed(spec.id)
	return nil
}

func isRecognizedOptionToken(tok string) bool {
	if tok == "--" {
		return true
	}
	if strings.HasPrefix(tok, "--") {
		name := tok[2:]
		if i := strings.Index(name, "="); i >= 0 {
			name = name[:i]
		}
		_, ok := specByLong[name]
		return ok
	}
	if strings.HasPrefix(tok, "-") && len(tok) >= 2 {
		r := []rune(tok)[1]
		_, ok := specByShort[r]
		return ok
	}
	return false
}

func parseArgs() (*Config, error) {
	bin := binaryName()
	cfg := &Config{
		BinName:         bin,
		Port:            8080,
		SortMethod:      "name",
		SortOrder:       "desc",
		ColorScheme:     "squirrel",
		ColorSchemeDark: "archlinux",
		WebConcurrency:  "0",
		OnDuplicate:     "error",
		SizeDisplay:     "human",
	}
	p := &parser{bin: bin, cfg: cfg, present: map[string]bool{}, cliCounts: map[string]int{}}
	args := os.Args[1:]
	afterDashDash := false
	// snapshot used order before each token for error usage
	for i := 0; i < len(args); i++ {
		tok := args[i]
		before := append([]string{}, p.usedOrder...)
		if afterDashDash {
			if err := p.addPositional(tok); err != nil {
				return nil, err
			}
			continue
		}
		if tok == "--" {
			afterDashDash = true
			continue
		}
		if strings.HasPrefix(tok, "--") {
			// long
			rest := tok[2:]
			name := rest
			eqVal := ""
			hasEq := false
			if idx := strings.Index(rest, "="); idx >= 0 {
				name = rest[:idx]
				eqVal = rest[idx+1:]
				hasEq = true
			}
			spec, ok := specByLong[name]
			if !ok {
				display := "--" + name
				// for ---bad, name begins with '-' -> display whole token
				if strings.HasPrefix(name, "-") || name == "" {
					display = tok
					if hasEq {
						display = tok[:strings.Index(tok, "=")]
					}
				}
				return nil, p.errUnexpected(display, before)
			}
			// help/version immediate (even if hasEq errors first)
			if spec.kind == kindBool {
				if hasEq {
					return nil, p.errUnexpectedValue(spec, eqVal, before)
				}
				if spec.id == "help" {
					fmt.Print(renderHelp(helpLongRaw, bin))
					return nil, clapExit{0}
				}
				if spec.id == "version" {
					fmt.Println("miniserve 0.32.0")
					return nil, clapExit{0}
				}
				if err := p.assign(spec, "true", true); err != nil {
					return nil, err
				}
				continue
			}
			if spec.kind == kindOptional {
				if hasEq {
					if eqVal == "" {
						return nil, p.errMissingValue(spec)
					}
					if err := p.assign(spec, eqVal, true); err != nil {
						return nil, err
					}
				} else {
					// consume next if not option-like
					if i+1 < len(args) && !isOptionLike(args[i+1]) {
						i++
						if err := p.assign(spec, args[i], true); err != nil {
							return nil, err
						}
					} else {
						if err := p.assign(spec, "\x00NONE", true); err != nil {
							return nil, err
						}
					}
				}
				continue
			}
			// value / multi
			if hasEq {
				if err := p.assign(spec, eqVal, true); err != nil {
					return nil, err
				}
			} else {
				if i+1 >= len(args) {
					return nil, p.errMissingValue(spec)
				}
				next := args[i+1]
				if isOptionLike(next) {
					if isRecognizedOptionToken(next) {
						return nil, p.errMissingValue(spec)
					}
					// unknown option-like: process as unexpected in next iteration by treating as error now
					// Clap reports unexpected for the next token.
					i++
					// fallthrough to unexpected handling by reprocessing token
					// Simplify: directly raise unexpected for next token
					return nil, p.unexpectedForToken(args[i], before)
				}
				i++
				if err := p.assign(spec, args[i], true); err != nil {
					return nil, err
				}
			}
			continue
		}
		if strings.HasPrefix(tok, "-") && tok != "-" {
			// short cluster
			runes := []rune(tok)
			// iterate chars after '-'
			consumedNext := false
			for pos := 1; pos < len(runes); pos++ {
				ch := runes[pos]
				spec, ok := specByShort[ch]
				if !ok {
					display := "-" + string(ch)
					return nil, p.errUnexpected(display, before)
				}
				if spec.kind == kindBool {
					// check for -h / -V short help (note -h is short help, distinct from long --help)
					if spec.id == "help" {
						fmt.Print(renderHelp(helpShortRaw, bin))
						return nil, clapExit{0}
					}
					if spec.id == "version" {
						fmt.Println("miniserve 0.32.0")
						return nil, clapExit{0}
					}
					if err := p.assign(spec, "true", true); err != nil {
						return nil, err
					}
					continue
				}
				// value or optional or multi: rest of cluster is value
				rest := string(runes[pos+1:])
				if rest != "" {
					val := rest
					if strings.HasPrefix(val, "=") {
						val = val[1:]
					}
					if spec.kind == kindOptional && val == "" {
						return nil, p.errMissingValue(spec)
					}
					if err := p.assign(spec, val, true); err != nil {
						return nil, err
					}
				} else {
					if spec.kind == kindOptional {
						if i+1 < len(args) && !isOptionLike(args[i+1]) {
							i++
							consumedNext = true
							if err := p.assign(spec, args[i], true); err != nil {
								return nil, err
							}
						} else {
							if err := p.assign(spec, "\x00NONE", true); err != nil {
								return nil, err
							}
						}
					} else {
						if i+1 >= len(args) {
							return nil, p.errMissingValue(spec)
						}
						next := args[i+1]
						if isOptionLike(next) {
							if isRecognizedOptionToken(next) {
								return nil, p.errMissingValue(spec)
							}
							return nil, p.unexpectedForToken(next, before)
						}
						i++
						consumedNext = true
						if err := p.assign(spec, args[i], true); err != nil {
							return nil, err
						}
					}
				}
				break // rest consumed as value
			}
			_ = consumedNext
			continue
		}
		// positional
		if err := p.addPositional(tok); err != nil {
			return nil, err
		}
	}
	// env handling
	if err := p.applyEnv(); err != nil {
		return nil, err
	}
	// conflicts
	if err := p.checkConflicts(); err != nil {
		return nil, err
	}
	// requires
	if err := p.checkRequires(); err != nil {
		return nil, err
	}
	// compute route prefix
	computeRoutePrefix(cfg)
	return cfg, nil
}

func isOptionLike(tok string) bool {
	return len(tok) > 1 && tok[0] == '-'
}
func (p *parser) unexpectedForToken(tok string, before []string) error {
	// determine display like clap would for this token as standalone
	if strings.HasPrefix(tok, "--") {
		name := tok[2:]
		if idx := strings.Index(name, "="); idx >= 0 {
			name = name[:idx]
		}
		display := "--" + name
		if strings.HasPrefix(name, "-") || name == "" {
			display = tok
			if idx := strings.Index(tok, "="); idx >= 0 {
				display = tok[:idx]
			}
		}
		return p.errUnexpected(display, before)
	}
	if strings.HasPrefix(tok, "-") && len([]rune(tok)) >= 2 {
		// if first short unknown, display -X ; else display whole?
		r := []rune(tok)[1]
		if _, ok := specByShort[r]; !ok {
			// For -1 style, display whole token (clap displayed '-1')
			if r >= '0' && r <= '9' {
				return p.errUnexpected(tok, before)
			}
			return p.errUnexpected("-"+string(r), before)
		}
	}
	return p.errUnexpected(tok, before)
}

func (p *parser) addPositional(tok string) error {
	if tok == "" {
		msg := "error: a value is required for '[PATH]' but none was supplied\n\nFor more information, try '--help'.\n"
		return p.failMsg(msg)
	}
	if p.pathSeen {
		return p.errUnexpected(tok, p.usedOrder)
	}
	p.pathSeen = true
	p.cfg.Path = tok
	p.cfg.PathProvided = true
	p.cfg.PathProvidedViaCLI = true
	return nil
}

func (p *parser) applyEnv() error {
	// Positional env first? Order doesn't matter much
	for _, spec := range argSpecs {
		if spec.env == "" {
			continue
		}
		val, ok := os.LookupEnv(spec.env)
		if !ok {
			continue
		}
		if p.present[spec.id] {
			continue // CLI wins
		}
		// bool empty handled in assign
		if spec.kind == kindOptional {
			if val == "" {
				return p.errMissingValue(spec)
			}
			if err := p.assign(spec, val, false); err != nil {
				return err
			}
			continue
		}
		if err := p.assign(spec, val, false); err != nil {
			return err
		}
	}
	// PATH env
	if !p.pathSeen {
		if val, ok := os.LookupEnv("MINISERVE_PATH"); ok {
			if val == "" {
				msg := "error: a value is required for '[PATH]' but none was supplied\n\nFor more information, try '--help'.\n"
				return p.failMsg(msg)
			}
			p.pathSeen = true
			p.cfg.Path = val
			p.cfg.PathProvided = true
		}
	}
	return nil
}

var conflicts = [][2]string{
	{"route_prefix", "random_route"},
	{"media_type", "raw_media_type"},
}

func (p *parser) checkConflicts() error {
	// choose conflict whose earlier-used arg appears first in usedOrder
	bestIdx := -1
	var best [2]string
	var bestFirst, bestSecond string
	for _, pair := range conflicts {
		a, b := pair[0], pair[1]
		if !p.present[a] || !p.present[b] {
			continue
		}
		ia := indexOf(p.usedOrder, a)
		ib := indexOf(p.usedOrder, b)
		firstIdx := ia
		first, second := a, b
		if ib < ia {
			firstIdx = ib
			first, second = b, a
		}
		if bestIdx == -1 || firstIdx < bestIdx {
			bestIdx = firstIdx
			best = pair
			bestFirst, bestSecond = first, second
		}
		_ = best
	}
	if bestIdx == -1 {
		return nil
	}
	// usage: usedOrder excluding second
	frags := []string{"Usage:", p.bin}
	for _, id := range p.usedOrder {
		if id == bestSecond {
			continue
		}
		frags = append(frags, specByID[id].fragment())
	}
	if p.pathSeen {
		frags = append(frags, "<PATH>")
	} else {
		frags = append(frags, "[PATH]")
	}
	msg := fmt.Sprintf("error: the argument '%s' cannot be used with '%s'\n\n%s\n\nFor more information, try '--help'.\n", specByID[bestFirst].fragment(), specByID[bestSecond].fragment(), strings.Join(frags, " "))
	return p.failMsg(msg)
}

func indexOf(s []string, v string) int {
	for i, x := range s {
		if x == v {
			return i
		}
	}
	return 1 << 30
}

type requirement struct {
	trigger string
	missing string
}

func (p *parser) checkRequires() error {
	var reqs []requirement
	add := func(trigger, missing string) {
		if p.present[trigger] && !p.present[missing] {
			for _, r := range reqs {
				if r.missing == missing {
					return
				}
			}
			reqs = append(reqs, requirement{trigger, missing})
		}
	}
	// In usedOrder order
	for _, id := range p.usedOrder {
		switch id {
		case "spa":
			add("spa", "index")
		case "tls_cert":
			add("tls_cert", "tls_key")
		case "tls_key":
			add("tls_key", "tls_cert")
		case "temp_directory", "chmod", "mkdir", "media_type", "raw_media_type":
			add(id, "upload_files")
		}
	}
	if len(reqs) == 0 {
		return nil
	}
	var sb strings.Builder
	sb.WriteString("error: the following required arguments were not provided:\n")
	for _, r := range reqs {
		fmt.Fprintf(&sb, "  %s\n", specByID[r.missing].fragment())
	}
	// Build usage: required chain first (DFS post-order per missing), then used not already included
	var ordered []string
	added := map[string]bool{}
	visiting := map[string]bool{}
	var dfs func(id string)
	dfs = func(id string) {
		if added[id] || visiting[id] {
			return
		}
		visiting[id] = true
		// outgoing requires edges of this arg itself
		var outs []string
		switch id {
		case "tls_cert":
			outs = []string{"tls_key"}
		case "tls_key":
			outs = []string{"tls_cert"}
		case "spa":
			outs = []string{"index"}
		case "temp_directory", "chmod", "mkdir", "media_type", "raw_media_type":
			outs = []string{"upload_files"}
		}
		for _, o := range outs {
			dfs(o)
		}
		visiting[id] = false
		if !added[id] {
			added[id] = true
			ordered = append(ordered, id)
		}
	}
	for _, r := range reqs {
		dfs(r.missing)
	}
	for _, id := range p.usedOrder {
		if !added[id] {
			added[id] = true
			ordered = append(ordered, id)
		}
	}
	frags := []string{"Usage:", p.bin}
	for _, id := range ordered {
		frags = append(frags, specByID[id].fragment())
	}
	if p.pathSeen {
		frags = append(frags, "<PATH>")
	} else {
		frags = append(frags, "[PATH]")
	}
	sb.WriteString("\n" + strings.Join(frags, " ") + "\n\nFor more information, try '--help'.\n")
	return p.failMsg(sb.String())
}

func computeRoutePrefix(cfg *Config) {
	if cfg.RandomRoute {
		cfg.RoutePrefix = "/" + randomHex6()
		return
	}
	if cfg.RoutePrefixOpt != nil {
		trimmed := strings.Trim(*cfg.RoutePrefixOpt, "/")
		cfg.RoutePrefix = "/" + trimmed
		return
	}
	cfg.RoutePrefix = ""
}

func completionsFor(shell string) string {
	switch shell {
	case "bash":
		return completionsBash
	case "elvish":
		return completionsElvish
	case "fish":
		return completionsFish
	case "powershell":
		return completionsPowershell
	case "zsh":
		return completionsZsh
	}
	return ""
}
