func (p *parser) smartUsage(before []string, includeID string, pathSeenOverride *bool) string {
	parts := []string{"Usage:", p.bin}
	seen := map[string]bool{}
	add := func(id string) {
		if id == "" || seen[id] {
			return
		}
		seen[id] = true
		parts = append(parts, specByID[id].fragment())
	}
	for _, id := range before {
		add(id)
	}
	add(includeID)
	pathSeen := p.pathSeen
	if pathSeenOverride != nil {
		pathSeen = *pathSeenOverride
	}
	if pathSeen {
		parts = append(parts, "<PATH>")
	} else {
		parts = append(parts, "[PATH]")
	}
	// If no option fragments, this would look odd; callers choose generic
	return strings.Join(parts, " ")
