	}
	if len(spec.possible) > 0 {
		msg += possibleLine(spec.possible)
		// similar value tip (only for enum specs)
		if sim := suggest(val, spec.possible, false); sim != "" && reason == "" {
			msg += fmt.Sprintf("\n\n  tip: a similar value exists: '%s'", sim)
		}
	}
	msg += "\n\nFor more information, try '--help'.\n"
	return p.failMsg(msg)
}
func (p *parser) errMissingValue(spec *argSpec) clapExit {
	msg := fmt.Sprintf("error: a value is required for '%s' but none was supplied", spec.fragment())
