	} else {
		// tip to pass as value for unknown options (not for positional extras)
		if strings.HasPrefix(argDisplay, "-") {
			tip = fmt.Sprintf("\n\n  tip: to pass '%s' as a value, use '-- %s'", argDisplay, argDisplay)
		}
		usage = p.genericUsage()
	}
	msg := fmt.Sprintf("error: unexpected argument '%s' found%s\n\n%s\n\nFor more information, try '--help'.\n", argDisplay, tip, usage)
	return p.failMsg(msg)
}

func suggest(name string, candidates []string, reverse bool) string {
	best := 0.70
	bestName := ""
	// iterate
	idxs := make([]int, len(candidates))
	for i := range candidates {
		if reverse {
			idxs[i] = len(candidates) - 1 - i
		} else {
			idxs[i] = i
		}
	}
	for _, idx := range idxs {
		cand := candidates[idx]
		conf := jaro(name, cand)
		if conf > best {
			best = conf
			bestName = cand
		}
	}
	return bestName
}
func suggestSpec(name string) *argSpec {
	cands := make([]string, len(argSpecs))
	for i, s := range argSpecs {
		cands[i] = s.long
	}
	bestName := suggest(name, cands, true)
	if bestName == "" {
		return nil
	}
	return specByLong[bestName]
}

// jaro similarity (strsim-compatible enough)
func jaro(aStr, bStr string) float64 {
	a := []rune(aStr)
	b := []rune(bStr)
	if len(a) == 0 && len(b) == 0 {
		return 1
	}
	if len(a) == 0 || len(b) == 0 {
		return 0
	}
	if len(a) == 1 && len(b) == 1 {
		if a[0] == b[0] {
			return 1
		}
		return 0
	}
	maxLen := len(a)
	if len(b) > maxLen {
		maxLen = len(b)
	}
	searchRange := maxLen/2 - 1
	if searchRange < 0 {
		searchRange = 0
	}
	bConsumed := make([]bool, len(b))
	matches := 0.0
	transpositions := 0.0
	bMatchIdx := 0
	for i := 0; i < len(a); i++ {
		start := i - searchRange
		if start < 0 {
			start = 0
		}
		end := i + searchRange + 1
		if end > len(b) {
			end = len(b)
		}
		for j := start; j < end; j++ {
			if bConsumed[j] {
				continue
			}
			if a[i] != b[j] {
				continue
			}
			bConsumed[j] = true
			matches++
			if j < bMatchIdx {
				transpositions++
			} else {
				bMatchIdx = j
				// count transpositions in a simplified way below instead
			}
			break
		}
	}
	// Proper transposition count: re-walk matched sequences
	if matches == 0 {
		return 0
	}
	// Collect matched chars in order from a and b using standard matching again
	// (reuse consumed flags from above to build b matched sequence)
	var bMatched []rune
	for j := 0; j < len(b); j++ {
		if bConsumed[j] {
			bMatched = append(bMatched, b[j])
		}
	}
	// a matched sequence: those a chars that matched (recompute flags)
	aMatchedFlags := make([]bool, len(a))
	bCons2 := make([]bool, len(b))
	for i := 0; i < len(a); i++ {
		start := i - searchRange
		if start < 0 {
			start = 0
		}
		end := i + searchRange + 1
		if end > len(b) {
			end = len(b)
		}
		for j := start; j < end; j++ {
			if bCons2[j] || a[i] != b[j] {
				continue
			}
			bCons2[j] = true
			aMatchedFlags[i] = true
			break
		}
	}
	var aMatched []rune
	for i := 0; i < len(a); i++ {
		if aMatchedFlags[i] {
			aMatched = append(aMatched, a[i])
		}
	}
	transpositions = 0
	for i := 0; i < len(aMatched) && i < len(bMatched); i++ {
		if aMatched[i] != bMatched[i] {
			transpositions++
		}
	}
	transpositions /= 2
	return ((matches / float64(len(a))) + (matches / float64(len(b))) + ((matches - transpositions) / matches)) / 3.0
}

func (p *parser) markUsed(id string) {
	if !p.present[id] {
		// usedOrder only for first occurrence (dedup)
		found := false
		for _, x := range p.usedOrder {
			if x == id {
				found = true
			}
		}
		if !found {
			p.usedOrder = append(p.usedOrder, id)
		}
	}
	p.present[id] = true
}

func parseAuthValue(s string) (AuthEntry, string) {
	parts := strings.SplitN(s, ":", 3)
	if len(parts) < 2 {
		return AuthEntry{}, "Invalid format for credentials string. Expected username:password, username:sha256:hash or username:sha512:hash"
	}
	if len(parts) == 2 {
		return AuthEntry{Username: parts[0], Plain: parts[1]}, ""
	}
	// len 3: decode hash first
	hashBytes, err := hex.DecodeString(parts[2])
	if err != nil {
		return AuthEntry{}, "Invalid format for password hash. Expected hex code"
	}
	if parts[1] != "sha256" && parts[1] != "sha512" {
		return AuthEntry{}, fmt.Sprintf("%s is not a valid hashing method. Expected sha256 or sha512", parts[1])
	}
	return AuthEntry{Username: parts[0], Method: parts[1], Hash: hashBytes}, ""
}

func parseHeaderValue(s string) (CustomHeader, string, bool) {
	// returns header, errReason, okIgnore (empty string accepted & ignored)
	if s == "" {
		return CustomHeader{}, "", true
	}
	idx := strings.Index(s, ":")
	if idx < 0 {
		return CustomHeader{}, "invalid header name", false
	}
	name := s[:idx]
	value := strings.Trim(s[idx+1:], " \t\r\n")
	// Validate header name tokens (RFC7230 token)
	if name == "" {
		return CustomHeader{}, "invalid header name", false
	}
	for _, r := range name {
		if !isTokenChar(r) {
			return CustomHeader{}, "invalid header name", false
		}
	}
	// newline inside value -> too many headers (httparse-like)
	if strings.ContainsAny(value, "\r\n") {
		return CustomHeader{}, "too many headers", false
	}
	// Also if original contains a newline anywhere else (after trim we removed trailing only)
	if strings.ContainsAny(s, "\r") {
		return CustomHeader{}, "too many headers", false
	}
	// Check raw string for embedded newline not at end
	if i := strings.Index(s, "\n"); i >= 0 && i != len(s)-1 {
		return CustomHeader{}, "too many headers", false
	}
	return CustomHeader{Name: name, Value: value}, "", false
}
func isTokenChar(r rune) bool {
	if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' {
		return true
	}
	switch r {
	case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
		return true
	}
	return false
}

func rustIntParseError(s string, signed bool) string {
	if s == "" {
		return "cannot parse integer from empty string"
	}
	return "invalid digit found in string"
}

// assign validates and stores a value; bool specs use value "true"
func (p *parser) assign(spec *argSpec, val string, isCLI bool) error {
