{"command":"cat > util.go <<'GO'
package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"syscall"
	"time"
	"unsafe"
)

func randomHex6() string {
	b := make([]byte, 3)
	if _, err := rand.Read(b); err != nil {
		// fallback time
		n := time.Now().UnixNano()
		b[0] = byte(n)
		b[1] = byte(n >> 8)
		b[2] = byte(n >> 16)
	}
	return hex.EncodeToString(b)
}

func isTTY(f *os.File) bool {
	var termios [64]byte
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, f.Fd(), uintptr(0x5401), uintptr(unsafe.Pointer(&termios[0])), 0, 0, 0)
	return errno == 0
}

// rust OS error string e.g. "No such file or directory (os error 2)"
func rustOSError(err error) string {
	if err == nil {
		return ""
	}
	errno := extractErrno(err)
	msg := errnoMessage(errno)
	if errno != 0 {
		return fmt.Sprintf("%s (os error %d)", msg, int(errno))
	}
	// fallback: use err text stripped of Go prefixes (best effort handled by callers)
