package main

import (
	"fmt"
	"os"
	"strings"
	"sync"
	"time"
)

var logMu sync.Mutex
var verboseLogging bool

func logLine(level, msg string) {
	if level == "INFO" && !verboseLogging {
		return
	}
	out := os.Stdout
	if level == "ERROR" {
		out = os.Stderr
	}
	ts := time.Now().Format("Mon, 02 Jan 2006 15:04:05 -0700")
	logMu.Lock()
	defer logMu.Unlock()
	if isTTY(out) {
		code := "34"
		if level == "WARN" {
			code = "33"
		} else if level == "ERROR" {
			code = "31"
		}
		fmt.Fprintf(out, "%s \x1b[%sm[%s] \x1b[39m%s\n", ts, code, level, msg)
	} else {
		fmt.Fprintf(out, "%s [%s] %s\n", ts, level, msg)
	}
}
func logInfo(msg string)  { logLine("INFO", msg) }
func logWarn(msg string)  { logLine("WARN", msg) }
func logError(msg string) { logLine("ERROR", msg) }
func logErrorChain(msg, cause string, hasCause bool) {
	logError(msg)
	if hasCause {
		logError("caused by: " + cause)
	}
}

// colored helpers for banner (colored crate style), only when stdout is tty
func colorBold(s string) string {
	if !isTTY(os.Stdout) {
		return s
	}
	return "\x1b[1m" + s + "\x1b[0m\x1b[39m\x1b[49m"
}
func colorBoldGreen(s string) string {
	if !isTTY(os.Stdout) {
		return s
	}
	return "\x1b[1m\x1b[32m" + s + "\x1b[0m\x1b[39m\x1b[49m"
}
func colorBoldYellow(s string) string {
	if !isTTY(os.Stdout) {
		return s
	}
	return "\x1b[1m\x1b[33m" + s + "\x1b[0m\x1b[39m\x1b[49m"
}

func joinComma(items []string) string { return strings.Join(items, ", ") }
