package main

import (
	"fmt"
	"net/http"
	"strings"
)

type appError struct {
	Status   int
	Msg      string
	Cause    string
	HasCause bool
	NoDetail bool // e.g. range/precondition: only status line in error div
	Log      bool
}

func (e *appError) detailText() string {
	if e.NoDetail {
		return ""
	}
	s := e.Msg
	if e.HasCause {
		s += "\ncaused by: " + e.Cause
	}
	return s
}

func statusText(code int) string {
	switch code {
	case 416:
		return "Range Not Satisfiable"
	default:
		return http.StatusText(code)
	}
}

// renderHTMLError writes the maud-style error page. Caller handles logging if e.Log
func (s *server) renderHTMLError(w http.ResponseWriter, r *http.Request, e *appError) {
	if e.Log {
		if e.NoDetail {
			// precondition/range errors were not logged by original
		} else {
			logErrorChain(e.Msg, e.Cause, e.HasCause)
		}
	}
	var b strings.Builder
	title := fmt.Sprintf("%d %s", e.Status, statusText(e.Status))
	b.WriteString(s.htmlHead(title, false))
	b.WriteString("<body><div class=\"error\">")
	fmt.Fprintf(&b, "<p>%s</p>", htmlEscape(title))
	if !e.NoDetail {
