{"command":"cat >> util.go <<'GO'

// ---- percent encoding for path segments (encodeURIComponent unreserved set) ----
func isUnreservedSeg(b byte) bool {
	if b >= 'A' && b <= 'Z' || b >= 'a' && b <= 'z' || b >= '0' && b <= '9' {
		return true
	}
	switch b {
	case '-', '_', '.', '!', '~', '*', '\'', '(', ')':
		return true
	}
	return false
}
func encodeSegment(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if isUnreservedSeg(c) {
			sb.WriteByte(c)
		} else {
			fmt.Fprintf(&sb, "%%%02X", c)
		}
	}
	return sb.String()
}

// Encode a slash-separated relative path (components already decoded), returning leading slash path without prefix.
func encodePathComponents(comps []string) string {
	if len(comps) == 0 {
		return "/"
	}
	parts := make([]string, len(comps))
	for i, c := range comps {
		parts[i] = encodeSegment(c)
	}
	return "/" + strings.Join(parts, "/")
}

// size formatting
func formatSize(size int64, display string) string {
	if display == "exact" {
		return fmt.Sprintf("%d B", size)
	}
	return formatSizeHuman(uint64(size))
}
func formatSizeHuman(size uint64) string {
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}
	units := []string{"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	val := float64(size)
	unit := "B"
	for _, u := range units {
		val /= 1024.0
		unit = u
		if val < 1024.0 {
			break
		}
	}
	return fmt.Sprintf("%.1f %s", val, unit)
}

// humanize duration akin to chrono-humanize (approximate thresholds)
func humanizeTime(t time.Time, now time.Time) string {
	diff := now.Sub(t)
	future := false
	if diff < 0 {
		future = true
		diff = -diff
	}
	secs := int64(diff.Seconds())
	var core string
	switch {
	case secs < 11:
		return "now"
	case secs < 50:
		core = fmt.Sprintf("%d seconds", secs)
	case secs < 90:
		core = "a minute"
	case secs < 45*60+30:
		// minutes (floor, but at 89-119 already above)
		m := (secs + 29) / 60 // approx: 90..119 use a minute handled; 119 -> 2
		if secs >= 90 && secs < 120 {
			m = 2
		}
		// Adjust to floor for >=120 generally except observed 119=2,180=3: round to nearestish
		// Use (secs+1)/60 floor-ish via integer division with 59? 149->2, 179->2, 180->3 matches (secs)/60 when secs>=120 except 119
		if secs >= 120 {
			m = secs / 60
			if m == 1 {
				m = 2
			}
		}
		if m == 1 {
			core = "a minute"
		} else {
			core = fmt.Sprintf("%d minutes", m)
		}
	case secs < 90*60:
		core = "an hour"
	case secs < 22*3600:
		h := secs / 3600
		// 1.5h observed "an hour", handled by <90min above; 2h=2
		if h == 1 {
			core = "an hour"
		} else {
			core = fmt.Sprintf("%d hours", h)
		}
	case secs < 36*3600:
		core = "a day"
	case secs < 6*86400+12*3600:
		d := secs / 86400
		if secs >= 36*3600 && secs < 48*3600 {
			d = 1
		}
		if d == 1 {
			core = "a day"
		} else {
			core = fmt.Sprintf("%d days", d)
		}
	case secs < 11*86400:
		core = "a week"
	case secs < 25*86400:
		w := secs / (7 * 86400)
		if secs >= 13*86400 && w < 2 {
			w = 2
		}
		// 13d -> 2 weeks, 14d->2
		core = fmt.Sprintf("%d weeks", w)
		if w == 1 {
			core = "a week"
		}
	case secs < 45*86400:
		core = "a month"
	case secs < 345*86400:
		mo := secs / (30 * 86400)
		if mo == 0 {
			mo = 1
		}
		if mo == 1 {
			core = "a month"
		} else {
			core = fmt.Sprintf("%d months", mo)
		}
	case secs < 548*86400:
		core = "a year"
	default:
		y := secs / (365 * 86400)
		if y == 1 {
			core = "a year"
		} else {
			core = fmt.Sprintf("%d years", y)
		}
	}
	if future {
		return "in " + core
	}
	return core + " ago"
}

// natural sort compare: compare strings splitting digit / non-digit chunks, like alphanumeric-sort crate compare_str
func naturalCompare(a, b string) int {
	ai, bi := 0, 0
	ar := []rune(a)
	br := []rune(b)
	for ai < len(ar) && bi < len(br) {
		ac, bc := ar[ai], br[bi]
		if isDigit(ac) && isDigit(bc) {
			// collect digit runs
			aj := ai
			for aj < len(ar) && isDigit(ar[aj]) {
				aj++
			}
			bj := bi
			for bj < len(br) && isDigit(br[bj]) {
				bj++
			}
			aNum := strings.TrimLeft(string(ar[ai:aj]), "0")
			bNum := strings.TrimLeft(string(br[bi:bj]), "0")
			if len(aNum) != len(bNum) {
				if len(aNum) < len(bNum) {
					return -1
				}
				return 1
			}
			if aNum != bNum {
				if aNum < bNum {
					return -1
				}
				return 1
			}
			// equal numeric value: more leading zeros? crate keeps continuing; if run lengths differ,
			// remember as tie-breaker? alphanumeric-sort: compares by stripped length then continues.
			ai, bi = aj, bj
			continue
		}
		if ac != bc {
			if ac < bc {
				return -1
			}
			return 1
		}
		ai++
		bi++
	}
	switch {
	case ai < len(ar):
		return 1
	case bi < len(br):
		return -1
	default:
		return 0
	}
}
func isDigit(r rune) bool { return r >= '0' && r <= '9' }

// unsorted directory read (directory order)
func readDirUnsorted(path string) ([]os.DirEntry, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return f.ReadDir(-1)
}
