func mimeForName(name string) string {
	ext := strings.ToLower(strings.TrimPrefix(filepath.Ext(name), "."))
	if m, ok := mimeByExt[ext]; ok {
		return m
	}
	// .tar.gz style: filepath.Ext returns .gz covered
	return "application/octet-stream"
}

// essence without parameters (for WebDAV getcontenttype)
func mimeEssenceForName(name string) string {
	m := mimeForName(name)
	if i := strings.Index(m, ";"); i >= 0 {
		return strings.TrimSpace(m[:i])
	}
	return m
}

func dispositionType(mime string) string {
	essence := mime
	if i := strings.Index(essence, ";"); i >= 0 {
		essence = strings.TrimSpace(essence[:i])
	}
	parts := strings.SplitN(essence, "/", 2)
	if len(parts) != 2 {
		return "attachment"
	}
	typ, sub := parts[0], parts[1]
	switch typ {
	case "text", "image", "audio", "video":
		return "inline"
	case "application":
		switch sub {
		case "javascript", "json", "wasm":
			return "inline"
		}
		return "attachment"
	case "font":
		return "attachment"
	default:
		// e.g. font/* handled; others as attachment
		return "attachment"
	}
}

func contentDisposition(mime, filename string) string {
	dt := dispositionType(mime)
	// Actix: quote filename escaping \ and "
	escaped := strings.NewReplacer("\\", "\\\\", "\"", "\\\"").Replace(filename)
	cd := dt + "; filename=\"" + escaped + "\""
	// non-ASCII: append filename* UTF-8
	needsExt := false
	for _, r := range filename {
		if r > 127 {
			needsExt = true
			break
		}
	}
	if needsExt {
		cd += "; filename*=UTF-8''" + encodeExtValue(filename)
	}
	return cd
}

// RFC5987 ext value encoding (attr-char set), matching Actix/http crate percent-encoding approx
func encodeExtValue(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if isAttrChar(c) {
			sb.WriteByte(c)
		} else {
			sb.WriteString("%")
			const hexd = "0123456789ABCDEF"
			sb.WriteByte(hexd[c>>4])
			sb.WriteByte(hexd[c&15])
		}
	}
	return sb.String()
}
func isAttrChar(b byte) bool {
	if b >= 'A' && b <= 'Z' || b >= 'a' && b <= 'z' || b >= '0' && b <= '9' {
		return true
	}
	switch b {
	case '!', '#', '$', '&', '+', '-', '.', '^', '_', '`', '|', '~':
		return true
	}
	return false
}
