// serveFile serves a filesystem file with Actix NamedFile-like semantics.
// displayName is basename used for content-disposition (may differ from fsPath base in some call sites? usually same).
func (s *server) serveFile(w http.ResponseWriter, r *http.Request, fsPath, displayName string) {
	f, err := os.Open(fsPath)
	if err != nil {
		s.routeNotFound(w, r, r.URL.EscapedPath())
		return
	}
	defer f.Close()
	info, err := f.Stat()
	if err != nil {
		s.routeNotFound(w, r, r.URL.EscapedPath())
		return
	}
	if displayName == "" {
		displayName = filepath.Base(fsPath)
	}
	mime := mimeForName(displayName)
	etag := etagFor(info)
	modTime := info.ModTime().UTC()
	// Base headers (Actix sets these even on 304/412/416)
	h := w.Header()
	h.Set("Content-Type", mime)
	h.Set("Content-Disposition", contentDisposition(mime, displayName))
	h.Set("Accept-Ranges", "bytes")
	h.Set("ETag", etag)
	h.Set("Last-Modified", modTime.Truncate(time.Second).Format(http.TimeFormat))
	size := info.Size()

	// Preconditions (Actix order):
	// If-Match / If-Unmodified-Since -> 412
	if v := r.Header.Get("If-Match"); v != "" {
		if !etagListMatch(v, etag, false) {
			h.Del("Content-Length")
			s.renderHTMLError(w, r, &appError{Status: 412, NoDetail: true})
			return
		}
	} else if v := r.Header.Get("If-Unmodified-Since"); v != "" {
		if t, ok := parseHTTPDate(v); ok {
			if modTime.Truncate(time.Second).After(t) {
				s.renderHTMLError(w, r, &appError{Status: 412, NoDetail: true})
				return
			}
		}
	}
	// If-None-Match / If-Modified-Since -> 304
	if v := r.Header.Get("If-None-Match"); v != "" {
		if etagListMatch(v, etag, true) {
			h.Del("Content-Length")
			w.WriteHeader(304)
			return
		}
	} else if v := r.Header.Get("If-Modified-Since"); v != "" {
		if t, ok := parseHTTPDate(v); ok {
			if !modTime.Truncate(time.Second).After(t) {
				h.Del("Content-Length")
				w.WriteHeader(304)
				return
			}
		}
	}

	// Range handling (ignore If-Range)
	rangeHdr := r.Header.Get("Range")
	if rangeHdr != "" {
		start, end, ok := parseSingleRange(rangeHdr, size)
		if !ok {
			h.Set("Content-Range", fmt.Sprintf("bytes */%d", size))
			s.renderHTMLError(w, r, &appError{Status: 416, NoDetail: true})
			return
		}
		length := end - start + 1
		h.Set("Content-Range", fmt.Sprintf("bytes %d-%d/%d", start, end, size))
		h.Set("Content-Encoding", "identity")
		h.Set("Content-Length", strconv.FormatInt(length, 10))
		status := 206
		if start == 0 && length == size {
			status = 200
			if size == 0 {
				// start 0 length 0 shouldn't happen because parse rejects
			}
		}
		w.WriteHeader(status)
		if r.Method == "HEAD" {
			return
		}
		if _, err := f.Seek(start, io.SeekStart); err == nil {
			_, _ = io.CopyN(w, f, length)
		}
		return
	}
	h.Set("Content-Length", strconv.FormatInt(size, 10))
	w.WriteHeader(200)
	if r.Method == "HEAD" {
		return
	}
	_, _ = io.Copy(w, f)
}

// parseSingleRange parses first range. Returns start,end inclusive.
func parseSingleRange(hdr string, size int64) (int64, int64, bool) {
	// Expect bytes=...
	eq := strings.Index(hdr, "=")
	if eq < 0 {
		return 0, 0, false
	}
	unit := strings.TrimSpace(hdr[:eq])
	if !strings.EqualFold(unit, "bytes") {
		return 0, 0, false
	}
	rest := strings.TrimSpace(hdr[eq+1:])
	if rest == "" {
		return 0, 0, false
	}
	// first range only
	if idx := strings.Index(rest, ","); idx >= 0 {
		rest = strings.TrimSpace(rest[:idx])
		if rest == "" {
			return 0, 0, false
		}
	}
	dash := strings.Index(rest, "-")
	if dash < 0 {
		return 0, 0, false
	}
	startStr := strings.TrimSpace(rest[:dash])
	endStr := strings.TrimSpace(rest[dash+1:])
	if startStr == "" {
		// suffix
		if endStr == "" {
			return 0, 0, false
		}
		n, err := strconv.ParseInt(endStr, 10, 64)
		if err != nil || n <= 0 {
			return 0, 0, false
		}
		if size == 0 {
			return 0, 0, false
		}
		if n > size {
			return 0, size - 1, true
		}
		return size - n, size - 1, true
	}
	start, err := strconv.ParseInt(startStr, 10, 64)
	if err != nil || start < 0 {
		return 0, 0, false
	}
	var end int64
	if endStr == "" {
		end = size - 1
	} else {
		end, err = strconv.ParseInt(endStr, 10, 64)
		if err != nil || end < 0 {
			return 0, 0, false
		}
		if end >= size {
			end = size - 1
		}
	}
	if size == 0 || start >= size || start > end {
		return 0, 0, false
	}
	return start, end, true
}
GO
"}

