type dirEntry struct {
	name          string
	fsPath        string
	isDir         bool
	isSymlink     bool
	symlinkTarget string
	size          int64
	hasSize       bool
	modTime       time.Time
}

type listingParams struct {
	Sort     *string
	Order    *string // normalized asc/desc
	Download *string
	Raw      bool
}

func parseListingParams(rawQuery string, logIt bool) listingParams {
	var out listingParams
	if rawQuery == "" {
		return out
	}
	seen := map[string]bool{}
	fail := func(cause string) listingParams {
		if logIt {
			logErrorChain("Failed to parse query parameters", "Query deserialize error: "+cause, true)
		}
		return listingParams{}
	}
	pairs := strings.Split(rawQuery, "&")
	for _, pair := range pairs {
		if pair == "" {
			continue
		}
		key, val, _ := strings.Cut(pair, "=")
		key = queryUnescapeLoose(key)
		val = queryUnescapeLoose(val)
		switch key {
		case "sort", "order", "download", "raw":
			if seen[key] {
				return fail(fmt.Sprintf("duplicate field `%s`", key))
			}
			seen[key] = true
			switch key {
			case "sort":
				switch val {
				case "name", "size", "date":
					v := val
					out.Sort = &v
				default:
					return fail(fmt.Sprintf("unknown variant `%s`, expected one of `name`, `size`, `date`", val))
				}
			case "order":
				switch val {
				case "asc", "Asc":
					v := "asc"
					out.Order = &v
				case "desc", "Desc":
					v := "desc"
					out.Order = &v
				default:
					return fail(fmt.Sprintf("unknown variant `%s`, expected one of `Asc`, `asc`, `Desc`, `desc`", val))
				}
			case "download":
				switch val {
				case "tar_gz", "tar", "zip":
					v := val
					out.Download = &v
				default:
					return fail(fmt.Sprintf("unknown variant `%s`, expected one of `tar_gz`, `tar`, `zip`", val))
				}
			case "raw":
				switch val {
				case "true":
					out.Raw = true
				case "false":
					out.Raw = false
				default:
					return fail("provided string was not `true` or `false`")
				}
			}
		default:
			continue
		}
	}
	return out
}

func sanitizePathStringToComponents(p string) []string {
	// Like Path components normalization used for allowed dirs / API paths:
	// ignore empty and ".", ".." pops, others kept (including leading dot names)
	var comps []string
	for _, seg := range strings.Split(p, "/") {
		if seg == "" || seg == "." {
			continue
		}
		if seg == ".." {
			if len(comps) > 0 {
				comps = comps[:len(comps)-1]
			}
			continue
		}
		comps = append(comps, seg)
	}
	return comps
}

func compsHasPrefix(comps, prefix []string) bool {
	if len(prefix) > len(comps) {
		return false
	}
	for i, p := range prefix {
		if comps[i] != p {
			return false
		}
	}
	return true
}
func (s *server) uploadAllowed(dirComps []string) bool {
	if !s.cfg.UploadProvided {
		return false
	}
	var allowed []string
	if s.cfg.UploadDir != nil {
		allowed = sanitizePathStringToComponents(*s.cfg.UploadDir)
	}
	return compsHasPrefix(dirComps, allowed)
}
func (s *server) rmAllowed(pathComps []string) bool {
	if !s.cfg.RMProvided {
		return false
	}
	var allowed []string
	if s.cfg.RMDir != nil {
		allowed = sanitizePathStringToComponents(*s.cfg.RMDir)
	}
	return compsHasPrefix(pathComps, allowed)
}

func sortEntries(entries []*dirEntry, method, order string, dirsFirst bool) {
	switch method {
	case "name":
		sort.SliceStable(entries, func(i, j int) bool {
			return naturalCompare(entries[i].name, entries[j].name) > 0
		})
	case "size":
		sort.SliceStable(entries, func(i, j int) bool {
			a, b := entries[i], entries[j]
			if a.hasSize != b.hasSize {
				return !a.hasSize && b.hasSize // None < Some
			}
			return a.size < b.size
		})
	case "date":
		sort.SliceStable(entries, func(i, j int) bool {
			return entries[i].modTime.Before(entries[j].modTime)
		})
	}
	if order == "desc" {
		for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
			entries[i], entries[j] = entries[j], entries[i]
		}
	}
	if dirsFirst {
		sort.SliceStable(entries, func(i, j int) bool {
			if entries[i].isDir == entries[j].isDir {
				return false
			}
			return entries[i].isDir
		})
	}
}

func (s *server) sortLink(params listingParams, col string, display string) string {
	labels := map[string]string{"name": "Name", "size": "Size", "date": "Last modification"}
	titleLabel := map[string]string{"name": "name", "size": "size", "date": "date"}
	active := params.Sort != nil && *params.Sort == col
	next := "asc"
	chev := "▾"
	class := ""
	if active {
		class = "active"
		if params.Order != nil && *params.Order == "asc" {
			next = "desc"
			chev = "▴"
		}
	}
	orderWord := "ascending"
	if next == "desc" {
		orderWord = "descending"
	}
	if display == "" {
		display = labels[col]
	}
	return fmt.Sprintf("<span class=\"%s\"><span class=\"chevron\">%s</span><a href=\"?sort=%s&amp;order=%s\" title=\"Sort by %s in %s order\">%s</a></span>", class, chev, col, next, titleLabel[col], orderWord, htmlEscape(display))
}

func (s *server) entryHref(dirComps []string, e *dirEntry, params listingParams) string {
	comps := append(append([]string{}, dirComps...), e.name)
	encoded := encodePathComponents(comps)
	if !e.isDir {
		if s.cfg.FileExternalURL != nil {
			base := strings.TrimRight(*s.cfg.FileExternalURL, "/")
			return base + encoded
		}
		return s.linkPrefix() + encoded
	}
	href := s.linkPrefix() + encoded + "/"
	if params.Raw {
		href += "?raw=true"
	} else if params.Sort != nil && params.Order != nil {
		href += fmt.Sprintf("?sort=%s&order=%s", *params.Sort, *params.Order)
	}
	return href
}

func (s *server) entryAnchor(dirComps []string, e *dirEntry, params listingParams) string {
	href := s.entryHref(dirComps, e, params)
	name := e.name
	slash := ""
	cls := "file"
	if e.isDir {
		slash = "/"
		cls = "directory"
	}
	if s.cfg.SymlinkInfo && e.isSymlink {
		target := e.symlinkTarget
		if e.isDir {
			target += "/"
		}
		return fmt.Sprintf("<a class=\"symlink\" href=\"%s\">%s%s<span class=\"symlink-symbol\"></span><a class=\"%s\">%s</a></a>", htmlEscape(href), htmlEscape(name), slash, cls, htmlEscape(target))
	}
	return fmt.Sprintf("<a class=\"%s\" href=\"%s\">%s%s</a>", cls, htmlEscape(href), htmlEscape(name), slash)
}

func (s *server) titleHost(r *http.Request) string {
	if s.cfg.Title != nil {
		return *s.cfg.Title
	}
	return r.Host
}
func (s *server) absURL(r *http.Request, dirComps []string) string {
	scheme := "http"
	if r.TLS != nil {
		scheme = "https"
	}
	path := s.linkPrefix() + encodePathComponents(dirComps)
	if !strings.HasSuffix(path, "/") {
		path += "/"
	}
	return scheme + "://" + r.Host + path
}

// serveDirectory handles listing/archive/readme for a directory.
// fsDir is the filesystem path, dirComps are relative components from serve root.
func (s *server) serveDirectory(w http.ResponseWriter, r *http.Request, fsDir string, dirComps []string) {
	params := parseListingParams(r.URL.RawQuery, true)
	// Archive / indexing handling happens in caller? Here: download check first (index already handled by caller)
	if s.cfg.DisableIndexing {
		s.renderHTMLError(w, r, &appError{Status: 404, Msg: "File not found."})
		return
	}
	if params.Download != nil {
		s.serveArchive(w, r, fsDir, dirComps, *params.Download)
		return
	}
	dirEntries, err := readDirUnsorted(fsDir)
	if err != nil {
		s.ioError(w, r, err)
		return
	}
	var entries []*dirEntry
	var readmeName, readmePath string
	for _, de := range dirEntries {
		name := de.Name()
		if !s.cfg.Hidden && strings.HasPrefix(name, ".") {
			continue
		}
		fsPath := filepath.Join(fsDir, name)
		lst, lerr := os.Lstat(fsPath)
		isSymlink := false
		if lerr == nil && lst.Mode()&os.ModeSymlink != 0 {
			isSymlink = true
		}
		if s.cfg.NoSymlinks && isSymlink {
			continue
		}
		info, serr := os.Stat(fsPath)
		if serr != nil {
			continue
		}
		if !info.IsDir() && !info.Mode().IsRegular() {
			continue
		}
		e := &dirEntry{name: name, fsPath: fsPath, isDir: info.IsDir(), isSymlink: isSymlink, modTime: info.ModTime()}
		if !info.IsDir() {
			e.size = info.Size()
			e.hasSize = true
		}
		if isSymlink && s.cfg.SymlinkInfo {
			if tgt, err := os.Readlink(fsPath); err == nil {
				e.symlinkTarget = tgt
			}
		}
		if s.cfg.Readme && !info.IsDir() {
			lower := strings.ToLower(name)
			if lower == "readme.md" || lower == "readme.txt" || lower == "readme" {
				readmeName = name
				readmePath = fsPath
			}
		}
		entries = append(entries, e)
	}
	// effective sorting
	method := s.cfg.SortMethod
	if params.Sort != nil {
		method = *params.Sort
	}
	order := s.cfg.SortOrder
	if params.Order != nil {
		order = *params.Order
	}
	sortEntries(entries, method, order, s.cfg.DirsFirst)

	var readmeHTML string
	var readmeErr *appError
	if s.cfg.Readme && readmePath != "" && !params.Raw {
		data, rerr := os.ReadFile(readmePath)
		if rerr != nil {
			readmeErr = ioAppError(rerr)
		} else if !utf8.Valid(data) {
			readmeErr = &appError{Status: 500, Msg: "stream did not contain valid UTF-8"}
		} else {
			content := string(data)
			var rendered string
			if strings.HasSuffix(strings.ToLower(readmeName), ".md") {
				rendered = renderMarkdown(content)
			} else {
				rendered = "<pre>" + content + "</pre>"
			}
			readmeHTML = fmt.Sprintf("<div id=\"readme\"><h3 id=\"readme-filename\">%s</h3><div id=\"readme-contents\">%s</div></div>", htmlEscape(readmeName), rendered)
		}
	}
	if readmeErr != nil {
		s.renderHTMLError(w, r, readmeErr)
		return
	}

	if params.Raw {
		body := s.renderRawListing(dirComps, entries)
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Content-Length", fmt.Sprintf("%d", len(body)))
		w.WriteHeader(200)
		if r.Method != "HEAD" {
			_, _ = w.Write([]byte(body))
		} else {
			_, _ = w.Write([]byte(body))
		}
		return
	}
	body := s.renderListing(r, dirComps, entries, params, readmeHTML)
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Content-Length", fmt.Sprintf("%d", len(body)))
	w.WriteHeader(200)
	if r.Method != "HEAD" {
		_, _ = w.Write([]byte(body))
	} else {
		_, _ = w.Write([]byte(body))
	}
}

func ioAppError(err error) *appError {
	errno := extractErrno(err)
	status := 500
	switch errno {
	case 13: // EACCES
		status = 403
	case 2:
		status = 404
	case 20:
		status = 400
	}
	return &appError{Status: status, Msg: rustOSError(err)}
}
func (s *server) ioError(w http.ResponseWriter, r *http.Request, err error) {
	s.renderHTMLError(w, r, ioAppError(err))
}

func (s *server) renderRawListing(dirComps []string, entries []*dirEntry) string {
	var b strings.Builder
	rawParams := listingParams{Raw: true}
	b.WriteString("<!DOCTYPE html><html><body><table><thead><th class=\"name\">Name</th><th class=\"size\">Size</th><th class=\"date\">Last modification</th></thead><tbody>")
	if len(dirComps) > 0 {
		b.WriteString("<tr><td colspan=\"3\"><p><a class=\"root\" href=\"../?raw=true\">..</a></p></td></tr>")
	}
	for _, e := range entries {
		cls := "entry-type-file"
		if e.isDir {
			cls = "entry-type-directory"
		}
		b.WriteString("<tr class=\"" + cls + "\"><td><p>")
		b.WriteString(s.entryAnchor(dirComps, e, rawParams))
		b.WriteString("</p></td><td class=\"size-cell\">")
		if e.hasSize {
			b.WriteString(htmlEscape(formatSize(e.size, s.cfg.SizeDisplay)))
		}
		b.WriteString("</td>")
		b.WriteString(s.dateCell(e))
		b.WriteString("</tr>")
	}
	b.WriteString("</tbody></table></body></html>")
	return b.String()
}
func (s *server) dateCell(e *dirEntry) string {
	mod := e.modTime.UTC().Format("2006-01-02 15:04:05 +00:00")
	hum := humanizeTime(e.modTime, time.Now())
	return fmt.Sprintf("<td class=\"date-cell\"><span>%s </span><span class=\"history\">%s</span></td>", htmlEscape(mod), htmlEscape(hum))
}

func (s *server) renderListing(r *http.Request, dirComps []string, entries []*dirEntry, params listingParams, readmeHTML string) string {
	hostTitle := s.titleHost(r)
	titleText := hostTitle
	if len(dirComps) > 0 {
		titleText += "/" + strings.Join(dirComps, "/")
	}
	var b strings.Builder
	b.WriteString(s.htmlHead(titleText, s.cfg.UploadProvided))
	b.WriteString("<body id=\"drop-container\">")
	// top toolbar group
	b.WriteString("<div class=\"toolbar_box_group\">")
	if s.cfg.UploadProvided {
		b.WriteString("<div class=\"drag-form\"><div class=\"form_title\"><h1>Drop your file here to upload it</h1></div></div>")
	}
	if s.cfg.Mkdir {
		b.WriteString("<div class=\"form\"><div class=\"form_title\"><h1>Create a new directory</h1></div></div>")
	}
	b.WriteString("</div>")
	// nav
	b.WriteString("<nav>")
	if s.cfg.QRCode {
		full := s.absURL(r, dirComps)
		fmt.Fprintf(&b, "<div><p>QR code</p><div class=\"qrcode\" id=\"qrcode\" title=\"%s\">%s</div></div>", htmlEscape(full), qrSVG(full))
	}
	if !s.cfg.HideTheme {
		b.WriteString(`<div><p>Change theme...</p><ul class="theme"><li data-theme="default"><a href="javascript:updateColorScheme(&quot;default&quot;)" title="Switch to Default (light/dark) theme">Default (light/dark)</a></li><li data-theme="squirrel"><a href="javascript:updateColorScheme(&quot;squirrel&quot;)" title="Switch to Squirrel (light) theme">Squirrel (light)</a></li><li data-theme="archlinux"><a href="javascript:updateColorScheme(&quot;archlinux&quot;)" title="Switch to Arch Linux (dark) theme">Arch Linux (dark)</a></li><li data-theme="zenburn"><a href="javascript:updateColorScheme(&quot;zenburn&quot;)" title="Switch to Zenburn (dark) theme">Zenburn (dark)</a></li><li data-theme="monokai"><a href="javascript:updateColorScheme(&quot;monokai&quot;)" title="Switch to Monokai (dark) theme">Monokai (dark)</a></li></ul></div>`)
	}
	b.WriteString("</nav>")
	b.WriteString("<div class=\"container\"><span id=\"top\"></span>")
	// h1
	b.WriteString(s.renderH1(hostTitle, dirComps, params))
	// toolbar
	b.WriteString("<div class=\"toolbar\">")
	if s.cfg.EnableTar || s.cfg.EnableTarGz || s.cfg.EnableZip {
		b.WriteString("<div class=\"download\">")
		if s.cfg.EnableTarGz {
			b.WriteString("<a href=\"?download=tar_gz\">Download .tar.gz</a>")
		}
		if s.cfg.EnableTar {
			b.WriteString("<a href=\"?download=tar\">Download .tar</a>")
		}
		if s.cfg.EnableZip {
			b.WriteString("<a href=\"?download=zip\">Download .zip</a>")
		}
		b.WriteString("</div>")
	}
	b.WriteString("<div class=\"toolbar_box_group\">")
	uploadHere := s.uploadAllowed(dirComps)
	if uploadHere {
		curPath := encodePathComponents(dirComps)
		acceptAttr := ""
		if s.cfg.RawMediaType != nil {
			acceptAttr = fmt.Sprintf(" accept=\"%s\"", htmlEscape(*s.cfg.RawMediaType))
		} else if len(s.cfg.MediaTypes) > 0 {
			parts := make([]string, len(s.cfg.MediaTypes))
			for i, m := range s.cfg.MediaTypes {
				parts[i] = m + "/*"
			}
			acceptAttr = fmt.Sprintf(" accept=\"%s\"", htmlEscape(strings.Join(parts, ",")))
		}
		fmt.Fprintf(&b, "<div class=\"toolbar_box\"><form id=\"file_submit\" action=\"%s/upload?path=%s\" method=\"POST\" enctype=\"multipart/form-data\"><p>Select a file to upload or drag it anywhere into the window</p><div><input id=\"file-input\"%s type=\"file\" name=\"file_to_upload\" required=\"\" multiple></input><button type=\"submit\">Upload file</button></div></form></div>", htmlEscape(s.linkPrefix()), htmlEscape(curPath), acceptAttr)
		if s.cfg.Mkdir {
			fmt.Fprintf(&b, "<div class=\"toolbar_box\"><form id=\"mkdir\" action=\"%s/upload?path=%s\" method=\"POST\" enctype=\"multipart/form-data\"><p>Specify a directory name to create</p><div class=\"toolbar_box\"><input type=\"text\" name=\"mkdir\" required=\"\" placeholder=\"Directory name\"></input><button type=\"submit\">Create directory</button></div></form></div>", htmlEscape(s.linkPrefix()), htmlEscape(curPath))
		}
	}
	b.WriteString("</div></div>")
	// table
	rmHere := s.rmAllowed(dirComps)
	b.WriteString("<table><thead>")
	fmt.Fprintf(&b, "<th class=\"name\">%s</th><th class=\"size\">%s</th><th class=\"date\">%s</th>", s.sortLink(params, "name", ""), s.sortLink(params, "size", ""), s.sortLink(params, "date", ""))
	if rmHere {
		b.WriteString("<th class=\"actions\"><span>Actions</span></th>")
	}
	b.WriteString("</thead><tbody>")
	if len(dirComps) > 0 {
		colspan := "3"
		if rmHere {
			colspan = "4"
		}
		suffix := ""
		if params.Sort != nil && params.Order != nil {
			suffix = fmt.Sprintf("?sort=%s&order=%s", *params.Sort, *params.Order)
		}
		fmt.Fprintf(&b, "<tr><td colspan=\"%s\"><p><span class=\"root-chevron\">◂</span><a class=\"root\" href=\"../%s\">Parent directory</a></p></td></tr>", colspan, htmlEscape(suffix))
	}
	for _, e := range entries {
		b.WriteString(s.renderEntryRow(dirComps, e, params, rmHere))
	}
	b.WriteString("</tbody></table>")
	if readmeHTML != "" {
		b.WriteString(readmeHTML)
	}
	b.WriteString("<a class=\"back\" href=\"#top\">⇪</a>")
	b.WriteString("<div class=\"footer\">")
	if s.cfg.WgetFooter {
		b.WriteString(s.wgetHTML(r, dirComps))
	}
	if !s.cfg.HideVersion {
		b.WriteString("<div class=\"version\"><a href=\"https://github.com/svenstaro/miniserve\">miniserve</a>/0.32.0</div>")
	}
	b.WriteString("</div></div>")
	b.WriteString(uploadAreaHTML)
	b.WriteString("</body></html>")
	return b.String()
}

func (s *server) renderH1(hostTitle string, dirComps []string, params listingParams) string {
	suffix := ""
	if params.Sort != nil && params.Order != nil {
		suffix = fmt.Sprintf("?sort=%s&order=%s", *params.Sort, *params.Order)
	}
	var b strings.Builder
	b.WriteString("<h1 class=\"title\" dir=\"ltr\">")
	if len(dirComps) == 0 {
		fmt.Fprintf(&b, "<span><bdi>%s</bdi></span>/", htmlEscape(hostTitle))
	} else {
		rootHref := s.linkPrefix() + "/" + suffix
		fmt.Fprintf(&b, "<a href=\"%s\"><bdi>%s</bdi></a>", htmlEscape(rootHref), htmlEscape(hostTitle))
		for i, c := range dirComps {
			b.WriteString("/")
			if i == len(dirComps)-1 {
				fmt.Fprintf(&b, "<span><bdi>%s</bdi></span>/", htmlEscape(c))
			} else {
				href := s.linkPrefix() + encodePathComponents(dirComps[:i+1]) + "/" + suffix
				fmt.Fprintf(&b, "<a href=\"%s\"><bdi>%s</bdi></a>", htmlEscape(href), htmlEscape(c))
			}
		}
	}
	b.WriteString("</h1>")
	return b.String()
}

func (s *server) renderEntryRow(dirComps []string, e *dirEntry, params listingParams, rmHere bool) string {
	var b strings.Builder
	hum := humanizeTime(e.modTime, time.Now())
	if e.isDir {
		b.WriteString("<tr class=\"entry-type-directory\"><td><p>")
		b.WriteString(s.entryAnchor(dirComps, e, params))
		b.WriteString("</p></td><td class=\"size-cell\"></td>")
		b.WriteString(s.dateCell(e))
	} else {
		b.WriteString("<tr class=\"entry-type-file\"><td><p>")
		b.WriteString(s.entryAnchor(dirComps, e, params))
		sizeStr := formatSize(e.size, s.cfg.SizeDisplay)
		if s.cfg.SizeDisplay == "exact" {
			fmt.Fprintf(&b, "<span class=\"mobile-info size\">%s</span>", htmlEscape(sizeStr))
		} else {
			fmt.Fprintf(&b, "<span class=\"mobile-info size\">%s</span>", s.sortLink(params, "size", sizeStr))
		}
		fmt.Fprintf(&b, "<span class=\"mobile-info history\">%s</span>", s.sortLink(params, "date", hum))
		b.WriteString("</p></td>")
		fmt.Fprintf(&b, "<td class=\"size-cell\">%s</td>", htmlEscape(sizeStr))
		b.WriteString(s.dateCell(e))
	}
	if rmHere {
		comps := append(append([]string{}, dirComps...), e.name)
		encoded := encodePathComponents(comps)
		action := fmt.Sprintf("%s/rm?path=%s%s", s.linkPrefix(), s.linkPrefix(), encoded)
		fmt.Fprintf(&b, "<td class=\"actions-cell\"><form class=\"rm_form\" action=\"%s\" method=\"POST\"><button type=\"submit\" title=\"Delete\">✗</button></form></td>", htmlEscape(action))
	}
	b.WriteString("</tr>")
	return b.String()
}

func (s *server) wgetHTML(r *http.Request, dirComps []string) string {
	full := s.absURL(r, dirComps)
	segCount := len(dirComps) + len(sanitizePathStringToComponents(s.cfg.RoutePrefix))
	cmd := "wget -rcnp -R 'index.html*' -nH"
	if segCount == 0 {
		cmd += fmt.Sprintf(" -P '%s'", r.Host)
	} else if segCount > 1 {
		cmd += fmt.Sprintf(" --cut-dirs=%d", segCount-1)
	}
	cmd += fmt.Sprintf(" '%s?raw=true'", full)
	return fmt.Sprintf("<div class=\"downloadDirectory\"><p>Download folder:</p><a class=\"cmd\" title=\"Click to copy!\" style=\"cursor: pointer;\" onclick=\"navigator.clipboard.writeText(&quot;%s&quot;)\">%s</a></div>", htmlEscape(cmd), htmlEscape(cmd))
}
