func (s *server) serveArchive(w http.ResponseWriter, r *http.Request, fsDir string, dirComps []string, kind string) {
	enabled := false
	var ct, ext string
	switch kind {
	case "tar":
		enabled, ct, ext = s.cfg.EnableTar, "application/tar", ".tar"
	case "tar_gz":
		enabled, ct, ext = s.cfg.EnableTarGz, "application/gzip", ".tar.gz"
	case "zip":
		enabled, ct, ext = s.cfg.EnableZip, "application/zip", ".zip"
	}
	if !enabled {
		s.renderHTMLError(w, r, &appError{Status: 403, Msg: "Archive creation is disabled."})
		return
	}
	base := ""
	if len(dirComps) == 0 {
		base = filepath.Base(s.serveCanonical)
		if base == "/" || base == "." || base == "" {
			base = "archive"
		}
	} else {
		base = dirComps[len(dirComps)-1]
	}
	w.Header().Set("Content-Type", ct)
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=\"%s%s\"", base, ext))
	w.Header().Set("Content-Transfer-Encoding", "binary")
	if kind == "zip" {
		data, err := s.buildZip(fsDir, base)
		if err != nil {
			// original surfaces errors during in-memory generation before headers in some cases; best effort
		}
		w.WriteHeader(200)
		flushResponse(w)
		if r.Method != "HEAD" {
			_, _ = w.Write(data)
		}
		return
	}
	w.WriteHeader(200)
	flushResponse(w)
	if r.Method == "HEAD" {
		return
	}
	var out io.Writer = w
	var gz *gzip.Writer
	if kind == "tar_gz" {
		gz = gzip.NewWriter(w)
		out = gz
	}
	tw := tar.NewWriter(out)
	s.writeTar(tw, fsDir, base)
	_ = tw.Close()
	if gz != nil {
		_ = gz.Close()
	}
