func flushResponse(w http.ResponseWriter) {
	if f, ok := w.(interface{ Flush() }); ok {
		f.Flush()
	}
}

type tarItem struct {
	fsPath string
	arc    string
}

func tarHeader(info os.FileInfo, name string, typeflag byte, linkname string, size int64) *tar.Header {
	h := &tar.Header{
		Name:     name,
		Mode:     int64(info.Mode().Perm()),
		Size:     size,
		ModTime:  info.ModTime().Truncate(time.Second),
		Typeflag: typeflag,
		Linkname: linkname,
		Format:   tar.FormatUSTAR,
	}
	if st, ok := info.Sys().(*syscall.Stat_t); ok && st != nil {
		h.Uid = int(st.Uid)
		h.Gid = int(st.Gid)
	}
	return h
}

func (s *server) writeTar(tw *tar.Writer, root string, base string) {
	stack := []tarItem{{fsPath: root, arc: base}}
	for len(stack) > 0 {
		n := len(stack) - 1
		item := stack[n]
		stack = stack[:n]
		lst, err := os.Lstat(item.fsPath)
		if err != nil {
			continue
		}
		isSymlink := lst.Mode()&os.ModeSymlink != 0
		if isSymlink && s.cfg.NoSymlinks {
			tgt, _ := os.Readlink(item.fsPath)
			h := tarHeader(lst, item.arc, tar.TypeSymlink, tgt, 0)
			h.Mode = 0777
			if err := tw.WriteHeader(h); err != nil {
				return
			}
			continue
		}
		info, err := os.Stat(item.fsPath)
		if err != nil {
			continue
		}
		if info.IsDir() {
			h := tarHeader(info, item.arc+"/", tar.TypeDir, "", 0)
			if err := tw.WriteHeader(h); err != nil {
				return
			}
			entries, err := readDirUnsorted(item.fsPath)
			if err != nil {
				continue
			}
			for _, e := range entries {
				stack = append(stack, tarItem{fsPath: filepath.Join(item.fsPath, e.Name()), arc: item.arc + "/" + e.Name()})
			}
			continue
		}
		if !info.Mode().IsRegular() {
			continue
		}
		h := tarHeader(info, item.arc, tar.TypeReg, "", info.Size())
		if err := tw.WriteHeader(h); err != nil {
			return
		}
		f, err := os.Open(item.fsPath)
		if err != nil {
			return
		}
		_, err = io.Copy(tw, f)
		f.Close()
		if err != nil {
			return
		}
	}
