func inodeKey(info os.FileInfo) string {
	if st, ok := info.Sys().(*syscall.Stat_t); ok && st != nil {
		return fmt.Sprintf("%d:%d", st.Dev, st.Ino)
	}
	return ""
}

func (s *server) buildZip(root string, base string) ([]byte, error) {
	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	rootInfo, err := os.Stat(root)
	if err != nil {
		return nil, err
	}
	type item struct {
		fsPath string
		arc    string
		isDir  bool
	}
	var items []item
	var walk func(fsPath string, comps []string, ancestors map[string]bool)
	walk = func(fsPath string, comps []string, ancestors map[string]bool) {
		entries, err := readDirUnsorted(fsPath)
		if err != nil {
			return
		}
		type dirTask struct {
			fsPath string
			comps  []string
			key    string
		}
		var dirs []dirTask
		for _, e := range entries {
			childPath := filepath.Join(fsPath, e.Name())
			info, err := os.Stat(childPath)
			if err != nil {
				continue
			}
			if !info.IsDir() && !info.Mode().IsRegular() {
				continue
			}
			childComps := append(append([]string{}, comps...), e.Name())
			arc := base + "/" + strings.Join(childComps, "/")
			if info.IsDir() {
				arc += "/"
			}
			items = append(items, item{childPath, arc, info.IsDir()})
			if info.IsDir() {
				dirs = append(dirs, dirTask{childPath, childComps, inodeKey(info)})
			}
		}
		for len(dirs) > 0 {
			n := len(dirs) - 1
			d := dirs[n]
			dirs = dirs[:n]
			if d.key != "" && ancestors[d.key] {
				continue
			}
			newAnc := map[string]bool{}
			for k, v := range ancestors {
				newAnc[k] = v
			}
			if d.key != "" {
				newAnc[d.key] = true
			}
			walk(d.fsPath, d.comps, newAnc)
		}
	}
	anc := map[string]bool{}
	if k := inodeKey(rootInfo); k != "" {
		anc[k] = true
	}
	walk(root, nil, anc)
	for _, it := range items {
		hdr := &zip.FileHeader{Name: it.arc, Method: zip.Store}
		if it.isDir {
			hdr.SetMode(os.ModeDir | 0755)
		} else {
			hdr.SetMode(0644)
		}
		wtr, err := zw.CreateHeader(hdr)
		if err != nil {
			continue
		}
		if !it.isDir {
			f, err := os.Open(it.fsPath)
			if err != nil {
				continue
			}
			_, _ = io.Copy(wtr, f)
			f.Close()
		}
	}
	if err := zw.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}
