package main

import (
	"crypto/sha256"
	"crypto/sha512"
	"crypto/subtle"
	"encoding/base64"
	"net/http"
	"strings"
	"unicode/utf8"
)

func parseBasicAuth(r *http.Request) (string, string, bool) {
	h := r.Header.Get("Authorization")
	if h == "" {
		return "", "", false
	}
	parts := strings.SplitN(h, " ", 2)
	if len(parts) != 2 || !strings.EqualFold(parts[0], "Basic") {
		return "", "", false
	}
	raw, err := base64.StdEncoding.DecodeString(strings.TrimSpace(parts[1]))
	if err != nil {
		// Actix may accept unpadded? try raw std
		raw, err = base64.RawStdEncoding.DecodeString(strings.TrimSpace(parts[1]))
		if err != nil {
			return "", "", false
		}
	}
	s := string(raw)
	if !utf8.ValidString(s) {
		return "", "", false
	}
	user, pass, ok := strings.Cut(s, ":")
	if !ok {
		return "", "", false
	}
	return user, pass, true
}

func (s *server) checkAuth(w http.ResponseWriter, r *http.Request) bool {
	if len(s.cfg.Auth) == 0 {
		return true
	}
	user, pass, ok := parseBasicAuth(r)
	if !ok {
		w.Header().Set("WWW-Authenticate", "Basic")
		w.Header().Set("Content-Length", "0")
		w.WriteHeader(401)
		return false
	}
	for _, e := range s.cfg.Auth {
		if e.Username != user {
			continue
		}
		if e.Method == "" {
			if subtle.ConstantTimeCompare([]byte(e.Plain), []byte(pass)) == 1 {
				return true
			}
		} else if e.Method == "sha256" {
			h := sha256.Sum256([]byte(pass))
			if subtle.ConstantTimeCompare(h[:], e.Hash) == 1 {
				return true
			}
		} else if e.Method == "sha512" {
			h := sha512.Sum512([]byte(pass))
			if subtle.ConstantTimeCompare(h[:], e.Hash) == 1 {
				return true
			}
		}
	}
	w.Header().Set("WWW-Authenticate", `Basic realm="miniserve"`)
	s.renderHTMLError(w, r, &appError{Status: 401, Msg: "Invalid credentials for HTTP authentication", Log: true})
	return false
}
GO
