// parsePathQuery extracts required `path` query parameter.
/// Returns value, *appError (no log).
func parsePathQuery(r *http.Request) (string, *appError) {
	raw := r.URL.RawQuery
	seen := false
	val := ""
	if raw != "" {
		for _, pair := range strings.Split(raw, "&") {
			if pair == "" {
				continue
			}
			k, v, _ := strings.Cut(pair, "=")
			k = queryUnescapeLoose(k)
			if k != "path" {
				continue
			}
			if seen {
				return "", &appError{Status: 400, Msg: "Query deserialize error: duplicate field `path`"}
			}
			seen = true
			val = queryUnescapeLoose(v)
		}
	}
	if !seen {
		return "", &appError{Status: 400, Msg: "Query deserialize error: missing field `path`"}
	}
	return val, nil
}
func queryUnescapeLoose(s string) string {
	// query component: + means space
	s = strings.ReplaceAll(s, "+", " ")
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '%' && i+2 < len(s) {
			hi, ok1 := hexVal(s[i+1])
			lo, ok2 := hexVal(s[i+2])
			if ok1 && ok2 {
				b.WriteByte(hi<<4 | lo)
				i += 2
				continue
			}
		}
		b.WriteByte(s[i])
	}
	return b.String()
}
func hexVal(c byte) (byte, bool) {
	switch {
	case c >= '0' && c <= '9':
		return c - '0', true
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10, true
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10, true
	}
	return 0, false
}

