func makeTempFile(dir string) (*os.File, string, error) {
	const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
	for i := 0; i < 100; i++ {
		b := make([]byte, 6)
		if _, err := rand.Read(b); err != nil {
			return nil, "", err
		}
		for j := range b {
			b[j] = letters[int(b[j])%len(letters)]
		}
		path := filepath.Join(dir, ".tmp"+string(b))
		f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
		if err == nil {
			return f, path, nil
		}
		if os.IsExist(err) {
			continue
		}
		return nil, "", err
	}
	return nil, "", fmt.Errorf("cannot create temp file")
