func moveFile(src, dst string) error {
	err := os.Rename(src, dst)
	if err == nil {
		return nil
	}
	if errno := extractErrno(err); errno == syscall.EXDEV {
		in, e := os.Open(src)
		if e != nil {
			return e
		}
		defer in.Close()
		out, e := os.OpenFile(dst, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0666)
		if e != nil {
			return e
		}
		if _, e := io.Copy(out, in); e != nil {
			out.Close()
			return e
		}
		if e := out.Close(); e != nil {
			return e
		}
		_ = os.Remove(src)
		return nil
	}
	return err
}
func fileModeFromRaw(raw uint32) os.FileMode {
	m := os.FileMode(raw & 0777)
	if raw&04000 != 0 {
		m |= os.ModeSetuid
	}
	if raw&02000 != 0 {
		m |= os.ModeSetgid
	}
	if raw&01000 != 0 {
		m |= os.ModeSticky
	}
	return m
}
func existsLstat(p string) bool {
	_, err := os.Lstat(p)
	return err == nil
