func (s *server) handleUpload(w http.ResponseWriter, r *http.Request) {
	rawPath, qerr := parsePathQuery(r)
	if qerr != nil {
		s.uploadFail(w, r, qerr)
		return
	}
	targetComps := sanitizePathStringToComponents(rawPath)
	targetFS := s.fsJoin(targetComps)
	if !s.uploadAllowed(targetComps) {
		s.uploadFail(w, r, &appError{Status: 403, Msg: "Upload not allowed to this directory", Log: true})
		return
	}
	info, err := os.Stat(targetFS)
	if err != nil {
		s.uploadFail(w, r, &appError{Status: 400, Msg: "Invalid HTTP request", Cause: "Invalid value for 'path' parameter", HasCause: true, Log: true})
		return
	}
	if !info.IsDir() {
		disp := targetFS
		if canon, e := filepath.EvalSymlinks(targetFS); e == nil {
			disp = canon
		}
		s.uploadFail(w, r, &appError{Status: 400, Msg: "Invalid path", Cause: fmt.Sprintf("cannot upload file to %s, since it's not a directory", disp), HasCause: true, Log: true})
		return
	}
	mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "multipart/form-data" || params["boundary"] == "" {
		s.uploadFail(w, r, &appError{Status: 400, Msg: "Failed to process multipart request", Cause: "ContentTypeIncompatible", HasCause: true, Log: true})
		return
	}
	mr := multipart.NewReader(r.Body, params["boundary"])
	for {
		part, err := mr.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			s.uploadFail(w, r, &appError{Status: 400, Msg: "Failed to process multipart request", Cause: "ContentTypeIncompatible", HasCause: true, Log: true})
			return
		}
		fieldName := part.FormName()
		if fieldName == "mkdir" {
			if s.handleMkdirPart(w, r, part, targetFS, rawPath) {
				return // error already rendered
			}
			continue
		}
		// file upload
		if s.handleFilePart(w, r, part, targetFS) {
			return
		}
	}
	redirect303(w, r)
}

// returns true if an error response was written
func (s *server) handleMkdirPart(w http.ResponseWriter, r *http.Request, part *multipart.Part, targetFS, rawPath string) bool {
	if !s.cfg.Mkdir {
		disp := permissionTargetDisplay(s.serveBase, rawPath)
		_, _ = io.Copy(io.Discard, part)
		s.uploadFail(w, r, &appError{Status: 403, Msg: fmt.Sprintf("Insufficient permissions to create file in %s", disp), Log: true})
		return true
	}
	data, err := io.ReadAll(part)
	if err != nil {
		s.uploadFail(w, r, &appError{Status: 400, Msg: "Failed to parse Failed to parse 'mkdir' path", Cause: "", HasCause: true, Log: true})
		return true
	}
	value := strings.TrimSpace(string(data))
	if value == "" {
		s.uploadFail(w, r, &appError{Status: 400, Msg: "Failed to parse Failed to parse 'mkdir' path", Cause: "", HasCause: true, Log: true})
		return true
	}
	segs := strings.Split(value, "/")
	for _, seg := range segs {
		if seg == ".." {
			s.uploadFail(w, r, &appError{Status: 400, Msg: "Invalid path", Cause: "Cannot use '..' in mkdir path", HasCause: true, Log: true})
			return true
		}
	}
	if !s.cfg.Hidden {
		for _, seg := range segs {
			if seg == "" || seg == "." {
				continue
			}
			if strings.HasPrefix(seg, ".") {
				s.uploadFail(w, r, &appError{Status: 400, Msg: "Invalid path", Cause: "Cannot use hidden paths in mkdir path", HasCause: true, Log: true})
				return true
			}
		}
	}
	mkdirFS := rustJoin(targetFS, value)
	if err := os.MkdirAll(mkdirFS, 0777); err != nil {
		// Check: if a file exists at target, original may surface io error; map loosely
		ae := ioAppError(err)
		// Upload errors are plain/HTML via uploadFail; but io error messages from original mkdir path unknown.
		s.uploadFail(w, r, &appError{Status: ae.Status, Msg: ae.Msg, Log: false})
		return true
	}
	return false
}

func permissionTargetDisplay(serveBase, rawPath string) string {
	base := strings.TrimSuffix(serveBase, "/")
	rest := strings.TrimPrefix(rawPath, "/")
	return base + "/" + rest
}

func rustJoin(base, p string) string {
	if filepath.IsAbs(p) {
		return filepath.Clean(p)
	}
	return filepath.Join(base, p)
}

func partFileName(part *multipart.Part) (string, bool) {
	cd := part.Header.Get("Content-Disposition")
	_, params, err := mime.ParseMediaType(cd)
	if err != nil {
		// fallback
		fn := part.FileName()
		if fn != "" {
			return fn, true
		}
		return "", false
	}
	fn, ok := params["filename"]
	return fn, ok
}

// returns true if error rendered
func (s *server) handleFilePart(w http.ResponseWriter, r *http.Request, part *multipart.Part, targetFS string) bool {
	fileName, has := partFileName(part)
	if !has {
		s.uploadFail(w, r, &appError{Status: 400, Msg: "Failed to parse HTTP header", Cause: "Failed to retrieve the name of the file to upload", HasCause: true, Log: true})
		return true
	}
	comps := sanitizeFilenameComponents(fileName)
	if !s.cfg.Hidden && len(comps) > 0 {
		for _, c := range comps {
			if strings.HasPrefix(c, ".") {
				s.uploadFail(w, r, &appError{Status: 400, Msg: "Invalid path", Cause: "Invalid file name to upload", HasCause: true, Log: true})
				return true
			}
		}
	}
	tempDir := os.TempDir()
	if s.cfg.TempDir != nil {
		tempDir = *s.cfg.TempDir
	}
	tmpFile, tmpPath, err := makeTempFile(tempDir)
	if err != nil {
		// Best effort
		s.uploadFail(w, r, &appError{Status: 500, Msg: rustOSError(err), Log: false})
		return true
	}
	hash256 := sha256.New()
	hash512 := sha512.New()
	mw := io.MultiWriter(tmpFile, hash256, hash512)
	if _, err := io.Copy(mw, part); err != nil {
		tmpFile.Close()
		os.Remove(tmpPath)
		s.uploadFail(w, r, &appError{Status: 400, Msg: "Failed to process multipart request", Cause: "ContentTypeIncompatible", HasCause: true, Log: true})
		return true
	}
	tmpFile.Close()

	// Hash validation
	funcHeader := r.Header.Get("X-File-Hash-Function")
	hashHeader := r.Header.Get("X-File-Hash")
	if funcHeader != "" {
		upper := strings.ToUpper(funcHeader)
		if upper != "SHA256" && upper != "SHA512" {
			os.Remove(tmpPath)
			s.uploadFail(w, r, &appError{Status: 400, Msg: "Invalid HTTP request", Cause: fmt.Sprintf("Invalid header value found for 'X-File-Hash-Function'. Supported values are SHA256 or SHA512. Found %s.", funcHeader), HasCause: true, Log: true})
			return true
		}
		if hashHeader != "" {
			var calc string
			if upper == "SHA256" {
				calc = fmt.Sprintf("%x", hash256.Sum(nil))
			} else {
				calc = fmt.Sprintf("%x", hash512.Sum(nil))
			}
			if calc != hashHeader {
				logWarn(fmt.Sprintf("The expected file hash %s did not match the calculated hash of %s. This can be caused if a file upload was aborted.", hashHeader, calc))
				os.Remove(tmpPath)
				s.uploadFail(w, r, &appError{Status: 400, Msg: "File hash that was provided did not match checksum of uploaded file", Log: true})
				return true
			}
		}
	}
	_ = hash(0) // keep hash import if unused elsewhere (hash.Hash referenced via vars)

	destFS := targetFS
	if len(comps) > 0 {
		destFS = filepath.Join(append([]string{targetFS}, comps...)...)
	}
	if existsLstat(destFS) {
		switch s.cfg.OnDuplicate {
		case "error":
			os.Remove(tmpPath)
			s.uploadFail(w, r, &appError{Status: 409, Msg: "File already exists, and the on_duplicate_files option is set to error out", Log: true})
			return true
		case "rename":
			destFS = renamedDest(destFS)
		case "overwrite":
		}
	}
	if err := moveFile(tmpPath, destFS); err != nil {
		os.Remove(tmpPath)
		s.uploadFail(w, r, &appError{Status: 500, Msg: fmt.Sprintf("Failed to move temporary file \"%s\" to \"%s\"", tmpPath, destFS), Cause: rustOSError(err), HasCause: true, Log: true})
		return true
	}
	// chmod
	if s.cfg.Chmod != nil {
		_ = os.Chmod(destFS, fileModeFromRaw(*s.cfg.Chmod))
	} else {
		perm := os.FileMode(0666 &^ startupUmask)
		_ = os.Chmod(destFS, perm)
	}
	return false
}

func renamedDest(dest string) string {
	dir := filepath.Dir(dest)
	name := filepath.Base(dest)
	stem, ext, hasExt := splitStemExt(name)
	for n := 1; ; n++ {
		var candidateName string
		if hasExt {
			candidateName = fmt.Sprintf("%s-%d.%s", stem, n, ext)
		} else {
			candidateName = fmt.Sprintf("%s-%d", name, n)
		}
		candidate := filepath.Join(dir, candidateName)
		if !existsLstat(candidate) {
			return candidate
		}
	}
}
func splitStemExt(name string) (string, string, bool) {
	idx := strings.LastIndex(name, ".")
	if idx <= 0 {
		return name, "", false
	}
	return name[:idx], name[idx+1:], true
}

func (s *server) handleRM(w http.ResponseWriter, r *http.Request) {
	rawPath, qerr := parsePathQuery(r)
	if qerr != nil {
		// RM errors are always HTML (even missing query)
		s.renderHTMLError(w, r, qerr)
		return
	}
	p := rawPath
	if s.cfg.RoutePrefix != "" {
		if p == s.cfg.RoutePrefix {
			p = ""
		} else if strings.HasPrefix(p, s.cfg.RoutePrefix+"/") {
			p = p[len(s.cfg.RoutePrefix):]
		}
	}
	comps := sanitizePathStringToComponents(p)
	if !s.rmAllowed(comps) {
		s.renderHTMLError(w, r, &appError{Status: 403, Msg: "Remove not allowed to this directory", Log: true})
		return
	}
	targetFS := s.fsJoin(comps)
	info, err := os.Stat(targetFS)
	if err != nil {
		// also check lstat for broken symlink? Original path validation canonicalizes and would fail.
		s.renderHTMLError(w, r, &appError{Status: 400, Msg: "Invalid HTTP request", Cause: "Invalid value for 'path' parameter", HasCause: true, Log: true})
		return
	}
	var rerr error
	if info.IsDir() {
		rerr = os.RemoveAll(targetFS)
	} else {
		rerr = os.Remove(targetFS)
	}
	if rerr != nil {
		s.renderHTMLError(w, r, ioAppError(rerr))
		return
	}
	redirect303(w, r)
}
