func redirect303(w http.ResponseWriter, r *http.Request) {
	loc := r.Referer()
	if loc == "" {
		loc = "/"
	}
	w.Header().Set("Location", loc)
	w.Header().Set("Content-Length", "0")
	w.WriteHeader(303)
