	}
	var hdr [3]byte
	hdr[0] = byte(headerVal)
	hdr[1] = byte(headerVal >> 8)
	hdr[2] = byte(headerVal >> 16)
	if _, err := z.w.Write(hdr[:]); err != nil {
		return err
	}
	if len(data) > 0 {
		if _, err := z.w.Write(data); err != nil {
			return err
		}
	}
	return nil
}
