package main

import (
	"bytes"
	"io"
)

// Brotli writer that buffers and emits a valid brotli stream using uncompressed meta-blocks.
// Implementation follows RFC 7932 bitstream format for the uncompressed case.
type brotliWriter struct {
	w      io.Writer
	buf    bytes.Buffer
	closed bool
}

func newBrotliWriter(w io.Writer) *brotliWriter { return &brotliWriter{w: w} }
func (b *brotliWriter) Write(p []byte) (int, error) { return b.buf.Write(p) }
func (b *brotliWriter) Flush() error { return nil }
func (b *brotliWriter) Close() error {
	if b.closed {
		return nil
	}
	b.closed = true
	data := b.buf.Bytes()
	enc := encodeBrotliUncompressed(data)
	_, err := b.w.Write(enc)
	return err
}

type bitWriter struct {
	buf   bytes.Buffer
	acc   uint32
	nbits int
}

func (bw *bitWriter) writeBits(value uint32, n int) {
	bw.acc |= (value & ((1 << n) - 1)) << bw.nbits
	bw.nbits += n
	for bw.nbits >= 8 {
		bw.buf.WriteByte(byte(bw.acc))
		bw.acc >>= 8
		bw.nbits -= 8
	}
}
func (bw *bitWriter) alignToByte() {
	if bw.nbits > 0 {
		bw.buf.WriteByte(byte(bw.acc))
		bw.acc = 0
		bw.nbits = 0
	}
}
func (bw *bitWriter) bytes() []byte {
	bw.alignToByte()
	return bw.buf.Bytes()
}

func encodeBrotliUncompressed(data []byte) []byte {
	bw := &bitWriter{}
	// WBITS: encode window size 22 -> first bit 1, next 3 bits value 5 (17+5)
	bw.writeBits(1, 1)
	bw.writeBits(5, 3)
	if len(data) == 0 {
		// Last empty meta-block: ISLAST=1, ISLASTEMPTY=1
		bw.writeBits(1, 1)
		bw.writeBits(1, 1)
		return bw.bytes()
	}
	// Split into meta-blocks of at most 65536 bytes (so MLEN fits in 16 bits / 4 nibbles)
	const chunk = 65536
	for offset := 0; offset < len(data); {
		n := chunk
		isLast := false
		if offset+n >= len(data) {
			n = len(data) - offset
			isLast = true
		}
		chunkData := data[offset : offset+n]
		if isLast {
			bw.writeBits(1, 1) // ISLAST
			bw.writeBits(0, 1) // ISLASTEMPTY = 0
		} else {
			bw.writeBits(0, 1) // ISLAST = 0
		}
		// MNIBBLES: 0 => 4 nibbles for MLEN-1
		bw.writeBits(0, 2)
		bw.writeBits(uint32(n-1), 16)
		if !isLast {
			// ISUNCOMPRESSED
			bw.writeBits(1, 1)
		} else {
			// For last block, after MLEN there is no "reserved" bit when?? RFC: if ISLAST=1 and ISLASTEMPTY=0,
			// encoding proceeds like non-last mid: a 1-bit field is present? Section 9.2:
			// If MLEN nibbles encoding... Actually meta-block header for both: after ISLASTEMPTY (if last),
			// 2 bits MNIBBLES, MLEN, then if not last-empty: 1 bit ISUNCOMPRESSED.
			bw.writeBits(1, 1) // ISUNCOMPRESSED
		}
		bw.alignToByte()
		bw.buf.Write(chunkData)
		offset += n
	}
	return bw.bytes()
}
