	return time.Unix(stx.Btime.Sec, int64(stx.Btime.Nsec))
}
func accessTime(info os.FileInfo) time.Time {
	if st, ok := info.Sys().(*syscall.Stat_t); ok && st != nil {
		return time.Unix(st.Atim.Sec, st.Atim.Nsec)
	}
	return info.ModTime()
}

func davProps(fsPath string, info os.FileInfo) []davProp {
	props := []davProp{}
	bt := birthTime(fsPath, info)
	props = append(props, davProp{"DAV:", "creationdate", bt.UTC().Format("2006-01-02T15:04:05Z"), false})
	if !info.IsDir() {
		props = append(props, davProp{"DAV:", "getcontentlength", fmt.Sprintf("%d", info.Size()), false})
		props = append(props, davProp{"DAV:", "getcontenttype", mimeEssenceForName(info.Name()), false})
	} else {
		props = append(props, davProp{"DAV:", "getcontenttype", "httpd/unix-directory", false})
	}
	props = append(props, davProp{"DAV:", "getetag", davEtag(info), false})
	props = append(props, davProp{"DAV:", "getlastmodified", info.ModTime().UTC().Truncate(time.Second).Format(http.TimeFormat), false})
	props = append(props, davProp{"DAV:", "lockdiscovery", "", false})
	// resourcetype
	if info.IsDir() {
		props = append(props, davProp{"DAV:", "resourcetype", "<D:collection></D:collection>", true})
	} else {
		props = append(props, davProp{"DAV:", "resourcetype", "", false})
	}
	props = append(props, davProp{"DAV:", "supportedlock", "", false})
	// sort by ns then local (?) all DAV props are alphabetical already except keep order above which is alphabetical
	sort.SliceStable(props, func(i, j int) bool { return props[i].local < props[j].local })
	return props
}
func davPropNameList(fsPath string, info os.FileInfo) []davProp {
	base := davProps(fsPath, info)
	names := make([]davProp, len(base))
	for i, p := range base {
		names[i] = davProp{p.ns, p.local, "", false}
	}
	names = append(names, davProp{"http://apache.org/dav/props/", "executable", "", false})
	names = append(names, davProp{"urn:schemas-microsoft-com:", "Win32LastAccessTime", "", false})
	return names
}
func propValueFor(fsPath string, info os.FileInfo, want davProp) (davProp, bool) {
	// special non-DAV props
	if want.ns == "http://apache.org/dav/props/" && want.local == "executable" {
		v := "F"
		if info.Mode().Perm()&0111 != 0 {
			v = "T"
		}
		if info.IsDir() {
			// dav-server may return F for dirs? keep based on exec bits
		}
		return davProp{want.ns, want.local, v, false}, true
	}
	if want.ns == "urn:schemas-microsoft-com:" && want.local == "Win32LastAccessTime" {
		// Format like "Mon, 11 Aug 2025 07:44:28 GMT" ? dav-server formats http date
		return davProp{want.ns, want.local, accessTime(info).UTC().Truncate(time.Second).Format(http.TimeFormat), false}, true
	}
	if want.ns != "DAV:" && want.ns != "" {
		return davProp{}, false
	}
	for _, p := range davProps(fsPath, info) {
		if p.local == want.local {
			return p, true
		}
	}
	return davProp{}, false
}

func nsPrefix(ns string) string {
	switch ns {
	case "DAV:":
		return "D"
	case "http://apache.org/dav/props/":
		return "A"
	case "urn:schemas-microsoft-com:":
		return "Z"
	default:
		return "ns0"
	}
}
func writePropXML(b *strings.Builder, p davProp) {
	pref := nsPrefix(p.ns)
	fmt.Fprintf(b, "<%s:%s>", pref, p.local)
	if p.raw {
		b.WriteString(p.value)
	} else {
		b.WriteString(xmlEscape(p.value))
	}
	fmt.Fprintf(b, "</%s:%s>", pref, p.local)
}

type propfindRequest struct {
	mode  string // allprop, propname, prop
	props []davProp
}

func parsePropfind(body []byte) (propfindRequest, error) {
	if len(strings.TrimSpace(string(body))) == 0 {
		return propfindRequest{mode: "allprop"}, nil
	}
	dec := xml.NewDecoder(strings.NewReader(string(body)))
	var req propfindRequest
	req.mode = ""
	depth := 0
	inProp := false
	sawRoot := false
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return req, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			depth++
			if depth == 1 {
				if t.Name.Local != "propfind" || t.Name.Space != "DAV:" {
					return req, fmt.Errorf("bad root")
				}
				sawRoot = true
				continue
			}
			if depth == 2 && t.Name.Space == "DAV:" {
				switch t.Name.Local {
				case "allprop":
					req.mode = "allprop"
				case "propname":
					req.mode = "propname"
				case "prop":
					req.mode = "prop"
					inProp = true
				case "include":
					// ignore, allprop already
					inProp = true
				}
				continue
			}
			if inProp && depth >= 3 {
				if req.mode == "" {
					req.mode = "prop"
				}
				// collect only direct children of prop/include (depth 3)
				if depth == 3 {
					req.props = append(req.props, davProp{ns: t.Name.Space, local: t.Name.Local})
				}
			}
		case xml.EndElement:
			if t.Name.Local == "prop" || t.Name.Local == "include" {
				if depth == 2 {
					inProp = false
				}
			}
			depth--
		}
	}
	if !sawRoot || req.mode == "" {
		return req, fmt.Errorf("no mode")
	}
	return req, nil
}

func (s *server) handleWebDAV(w http.ResponseWriter, r *http.Request, comps []string, fsPath string, displayPath string) {
	if r.Method == "OPTIONS" {
		// Determine allow based on existence/type
		info, err := os.Stat(fsPath)
		allow := "OPTIONS"
		if err == nil {
			if info.IsDir() {
				allow = "OPTIONS,PROPFIND"
			} else {
				allow = "HEAD,GET,OPTIONS,PROPFIND"
			}
		}
		w.Header().Set("Allow", allow)
		w.Header().Set("DAV", "1,2,3,sabredav-partialupdate")
		w.Header().Set("MS-Author-Via", "DAV")
		w.Header().Set("Content-Length", "0")
		w.WriteHeader(200)
		return
	}
	// PROPFIND
	depth := r.Header.Get("Depth")
	if depth != "0" && depth != "1" {
		w.Header().Set("Content-Type", "application/xml; charset=utf-8")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Pragma", "no-cache")
		w.Header().Set("Content-Length", fmt.Sprintf("%d", len(davFiniteDepthBody)))
		w.WriteHeader(403)
		_, _ = w.Write([]byte(davFiniteDepthBody))
		return
	}
	body, _ := io.ReadAll(r.Body)
	pf, err := parsePropfind(body)
	if err != nil {
		w.Header().Set("Content-Length", "0")
		w.WriteHeader(400)
		return
	}
	info, err := os.Stat(fsPath)
	if err != nil {
		w.Header().Set("Content-Length", "0")
		w.WriteHeader(404)
		return
	}
	// Canonical href for the target
	escapedPath := r.URL.EscapedPath()
	if info.IsDir() && !strings.HasSuffix(escapedPath, "/") {
		w.Header().Set("Content-Location", escapedPath+"/")
		escapedPath = escapedPath + "/"
	}
	type resource struct {
		href   string
		fsPath string
		info   os.FileInfo
	}
	resources := []resource{{href: escapedPath, fsPath: fsPath, info: info}}
	if depth == "1" && info.IsDir() {
		entries, err := readDirUnsorted(fsPath)
		if err == nil {
			for _, e := range entries {
				name := e.Name()
				if !s.cfg.Hidden && strings.HasPrefix(name, ".") {
					continue
				}
				childFS := filepath.Join(fsPath, name)
				lst, _ := os.Lstat(childFS)
				if s.cfg.NoSymlinks && lst != nil && lst.Mode()&os.ModeSymlink != 0 {
					continue
				}
				ci, err := os.Stat(childFS)
				if err != nil {
					continue
				}
				if !ci.IsDir() && !ci.Mode().IsRegular() {
					continue
				}
				href := strings.TrimSuffix(escapedPath, "/") + "/" + encodeSegment(name)
				if ci.IsDir() {
					href += "/"
				}
				resources = append(resources, resource{href, childFS, ci})
			}
		}
	}
	// Build XML, collecting used namespaces
	// Root element attrs depend on namespaces of props emitted (dav-server includes A/Z when propname)
	usedNS := map[string]bool{"DAV:": true}
	// Precompute per-resource props to emit
	type respData struct {
		href      string
		propstats []struct {
			props  []davProp
			status string
		}
	}
	var resps []respData
	for _, res := range resources {
		var found, notFound []davProp
		switch pf.mode {
		case "propname":
			found = davPropNameList(res.fsPath, res.info)
		case "allprop":
			found = davProps(res.fsPath, res.info)
			// include extra requested props if any (via include)
			for _, want := range pf.props {
				if pv, ok := propValueFor(res.fsPath, res.info, want); ok {
					already := false
					for _, f := range found {
						if f.ns == pv.ns && f.local == pv.local {
							already = true
						}
					}
					if !already {
						found = append(found, pv)
					}
				}
			}
		case "prop":
			for _, want := range pf.props {
				if want.ns == "" {
					want.ns = "DAV:"
				}
				if pv, ok := propValueFor(res.fsPath, res.info, want); ok {
					found = append(found, pv)
				} else {
					notFound = append(notFound, davProp{ns: want.ns, local: want.local})
				}
			}
		}
		for _, p := range found {
			usedNS[p.ns] = true
		}
		for _, p := range notFound {
			usedNS[p.ns] = true
		}
		rd := respData{href: res.href}
		if len(found) > 0 {
			rd.propstats = append(rd.propstats, struct {
				props  []davProp
				status string
			}{found, "HTTP/1.1 200 OK"})
		}
		if len(notFound) > 0 {
			rd.propstats = append(rd.propstats, struct {
				props  []davProp
				status string
			}{notFound, "HTTP/1.1 404 Not Found"})
		}
		if len(found) == 0 && len(notFound) == 0 {
			rd.propstats = append(rd.propstats, struct {
				props  []davProp
				status string
			}{nil, "HTTP/1.1 200 OK"})
		}
		resps = append(resps, rd)
	}
	var b strings.Builder
	// Namespace declarations sorted by prefix (A, D, Z order like original)
	type nsDecl struct{ pref, uri string }
	var decls []nsDecl
	for ns := range usedNS {
		if ns == "" {
			continue
		}
		decls = append(decls, nsDecl{nsPrefix(ns), ns})
	}
	sort.Slice(decls, func(i, j int) bool { return decls[i].pref < decls[j].pref })
	b.WriteString("<?xml version=\"1.0\" encoding=\"utf-8\"?><D:multistatus")
	for _, d := range decls {
		fmt.Fprintf(&b, " xmlns:%s=\"%s\"", d.pref, xmlEscape(d.uri))
	}
	b.WriteString(">")
	for _, rd := range resps {
		b.WriteString("<D:response>")
		fmt.Fprintf(&b, "<D:href>%s</D:href>", xmlEscape(rd.href))
		for _, ps := range rd.propstats {
			b.WriteString("<D:propstat><D:prop>")
			for _, p := range ps.props {
				writePropXML(&b, p)
			}
			fmt.Fprintf(&b, "</D:prop><D:status>%s</D:status></D:propstat>", ps.status)
		}
		b.WriteString("</D:response>")
	}
	b.WriteString("</D:multistatus>")
	out := b.String()
	w.Header().Set("Content-Type", "application/xml; charset=utf-8")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Pragma", "no-cache")
	w.WriteHeader(207)
	flushResponse(w)
	_, _ = w.Write([]byte(out))
}
GO
gofmt -w webdav.go markdown.go
rm markdown_stub.go
"}

actions.command:
cat > markdown.go <<'GO'
package main

import (
	"fmt"
	"regexp"
	"strings"
)

// A small CommonMark-ish renderer (pulldown-cmark defaults: no tables/strikethrough/tasklists, raw HTML omitted)
func renderMarkdownFull(input string) string {
	input = strings.ReplaceAll(input, "\r\n", "\n")
	input = strings.ReplaceAll(input, "\r", "\n")
	lines := strings.Split(input, "\n")
	var out strings.Builder
	i := 0
	for i < len(lines) {
		line := lines[i]
		if strings.TrimSpace(line) == "" {
			i++
			continue
		}
		// Fenced code
		if fence, lang, ok := parseFence(line); ok {
			i++
			var code []string
			for i < len(lines) {
				if isFenceClose(lines[i], fence) {
					i++
					break
				}
				code = append(code, lines[i])
				i++
			}
			content := strings.Join(code, "\n")
			if len(code) > 0 {
				content += "\n"
			}
			if lang != "" {
				fmt.Fprintf(&out, "<pre><code class=\"language-%s\">%s</code></pre>\n", htmlEscape(lang), htmlEscape(content))
			} else {
				fmt.Fprintf(&out, "<pre><code>%s</code></pre>\n", htmlEscape(content))
			}
			continue
		}
		// Raw HTML block: line starts with '<' that looks like tag/comment
		if isRawHTMLBlockStart(line) {
			for i < len(lines) && strings.TrimSpace(lines[i]) != "" {
				i++
			}
			out.WriteString("<!-- raw HTML omitted -->\n")
			continue
		}
		// ATX heading
		if lvl, text, ok := parseATX(line); ok {
			fmt.Fprintf(&out, "<h%d>%s</h%d>\n", lvl, renderInline(text), lvl)
			i++
			continue
		}
		// Thematic break
		if isThematicBreak(line) {
			out.WriteString("<hr />\n")
			i++
			continue
		}
		// Blockquote
		if strings.HasPrefix(strings.TrimLeft(line, " \t"), ">") {
			var qs []string
			for i < len(lines) {
				l := strings.TrimLeft(lines[i], " \t")
				if strings.HasPrefix(l, ">") {
					content := strings.TrimPrefix(l, ">")
					content = strings.TrimPrefix(content, " ")
					qs = append(qs, content)
					i++
					continue
				}
				// lazy continuation if non-empty and previous was quote para
				if strings.TrimSpace(l) != "" && len(qs) > 0 {
					qs = append(qs, l)
					i++
					continue
				}
				break
			}
			inner := renderMarkdownFull(strings.Join(qs, "\n"))
			out.WriteString("<blockquote>\n" + inner + "</blockquote>\n")
			continue
		}
		// Lists
		if isListItem(line) {
			html, n := parseList(lines, i)
			out.WriteString(html)
			i = n
			continue
		}
		// Indented code block (4 spaces / tab)
		if strings.HasPrefix(line, "    ") || strings.HasPrefix(line, "\t") {
			var code []string
			for i < len(lines) {
				l := lines[i]
				if strings.HasPrefix(l, "\t") {
					code = append(code, l[1:])
					i++
				} else if strings.HasPrefix(l, "    ") {
					code = append(code, l[4:])
					i++
				} else if strings.TrimSpace(l) == "" {
					// look ahead
					j := i + 1
					if j < len(lines) && (strings.HasPrefix(lines[j], "    ") || strings.HasPrefix(lines[j], "\t")) {
						code = append(code, "")
						i++
					} else {
						break
					}
				} else {
					break
				}
			}
			fmt.Fprintf(&out, "<pre><code>%s\n</code></pre>\n", htmlEscape(strings.Join(code, "\n")))
			continue
		}
		// Paragraph (collect until blank or block start; handle setext)
		start := i
		var para []string
		setext := 0
		for i < len(lines) {
			l := lines[i]
			if i > start {
				if lvl := setextLevel(l); lvl > 0 {
					setext = lvl
					i++
					break
				}
				if strings.TrimSpace(l) == "" {
					break
				}
				if _, _, ok := parseATX(l); ok {
					break
				}
				if isThematicBreak(l) {
					break
				}
				if _, _, ok := parseFence(l); ok {
					break
				}
				if isListItem(l) {
					break
				}
				if strings.HasPrefix(strings.TrimLeft(l, " \t"), ">") {
					break
				}
			}
			para = append(para, l)
			i++
		}
		text := strings.Join(para, "\n")
		if setext > 0 {
			fmt.Fprintf(&out, "<h%d>%s</h%d>\n", setext, renderInline(strings.TrimSpace(text)), setext)
		} else {
			fmt.Fprintf(&out, "<p>%s</p>\n", renderInline(text))
		}
	}
	return out.String()
}

func parseFence(line string) (string, string, bool) {
	t := strings.TrimLeft(line, " ")
	if len(line)-len(t) > 3 {
		return "", "", false
	}
	if strings.HasPrefix(t, "```") {
		n := 0
		for n < len(t) && t[n] == '`' {
			n++
		}
		lang := strings.TrimSpace(t[n:])
		if strings.Contains(lang, "`") {
			return "", "", false
		}
		// first word only
		if fields := strings.Fields(lang); len(fields) > 0 {
			lang = fields[0]
		}
		return strings.Repeat("`", n), lang, true
	}
	if strings.HasPrefix(t, "~~~") {
		n := 0
		for n < len(t) && t[n] == '~' {
			n++
		}
		lang := strings.TrimSpace(t[n:])
		if fields := strings.Fields(lang); len(fields) > 0 {
			lang = fields[0]
		} else {
			lang = ""
		}
		return strings.Repeat("~", n), lang, true
	}
	return "", "", false
}
func isFenceClose(line string, fence string) bool {
	t := strings.TrimSpace(line)
	if fence == "" {
		return false
	}
	ch := fence[0]
	if len(t) < len(fence) {
		return false
	}
	for i := 0; i < len(t); i++ {
		if t[i] != ch {
			return false
		}
	}
	return len(t) >= len(fence)
}
func parseATX(line string) (int, string, bool) {
	t := strings.TrimLeft(line, " ")
	if len(line)-len(t) > 3 {
		return 0, "", false
	}
	n := 0
	for n < len(t) && t[n] == '#' {
		n++
	}
	if n == 0 || n > 6 {
		return 0, "", false
	}
	rest := t[n:]
	if rest != "" && rest[0] != ' ' && rest[0] != '\t' {
		return 0, "", false
	}
	text := strings.TrimSpace(rest)
	// closing sequence
	text = regexp.MustCompile(`\s+#+\s*$`).ReplaceAllString(text, "")
	if strings.Trim(text, "#") == "" && strings.Contains(text, "#") {
		text = ""
	}
	return n, text, true
}
func setextLevel(line string) int {
	t := strings.TrimSpace(line)
	if t == "" {
		return 0
	}
	allEq := true
	allDash := true
	for _, c := range t {
		if c != '=' {
			allEq = false
		}
		if c != '-' {
			allDash = false
		}
	}
	if allEq {
		return 1
	}
	if allDash {
		return 2
	}
	return 0
}
func isThematicBreak(line string) bool {
	t := strings.TrimSpace(line)
	t = strings.ReplaceAll(strings.ReplaceAll(strings.ReplaceAll(t, " ", ""), "\t", ""), "", "")
	if len(t) < 3 {
		return false
	}
	ch := t[0]
	if ch != '-' && ch != '_' && ch != '*' {
		return false
	}
	for i := 1; i < len(t); i++ {
		if t[i] != ch {
			return false
		}
	}
	return true
}
func isRawHTMLBlockStart(line string) bool {
	t := strings.TrimLeft(line, " \t")
	if !strings.HasPrefix(t, "<") {
		return false
	}
	// comment, PI, CDATA, declaration, or tag name
	if strings.HasPrefix(t, "<!--") || strings.HasPrefix(t, "<?") || strings.HasPrefix(t, "<!") {
		return true
	}
	// <tag or </tag where tag looks like a block-ish tag or any tag followed by space/> or >
	// CommonMark HTML block type 6 has a list of tag names; type7 any complete tag on its own line.
	// Our simple test (script/div/p etc) will commonly be standalone raw html lines.
	return regexp.MustCompile(`^</?[A-Za-z][A-Za-z0-9-]*(\s|>|/>)`).MatchString(t)
}

var unorderedItemRe = regexp.MustCompile(`^(\s*)[-+*]\s+(.*)$`)
var orderedItemRe = regexp.MustCompile(`^(\s*)(\d+)([.)])\s+(.*)$`)

func isListItem(line string) bool {
	return unorderedItemRe.MatchString(line) || orderedItemRe.MatchString(line)
}

func parseList(lines []string, start int) (string, int) {
	ordered := orderedItemRe.MatchString(lines[start])
	startNum := 1
	if ordered {
		m := orderedItemRe.FindStringSubmatch(lines[start])
		fmt.Sscanf(m[2], "%d", &startNum)
	}
	baseIndent := leadingSpaces(lines[start])
	i := start
	type item struct {
		lines []string
	}
	var items []item
	var cur *item
	for i < len(lines) {
		line := lines[i]
		if strings.TrimSpace(line) == "" {
			// blank: peek next non-blank; if it's a list item at base indent continue, if indented continuation append blank
			j := i + 1
			for j < len(lines) && strings.TrimSpace(lines[j]) == "" {
				j++
			}
			if j < len(lines) && isListItem(lines[j]) && leadingSpaces(lines[j]) >= baseIndent && isSameListType(lines[j], ordered) {
				// loose list blank between items: pulldown will render <p> in items. We approximate as tight unless count>0.
				i++
				continue
			}
			if j < len(lines) && leadingSpaces(lines[j]) > baseIndent && cur != nil {
				cur.lines = append(cur.lines, "")
				i++
				continue
			}
			break
		}
		if isListItem(line) {
			ind := leadingSpaces(line)
			if ind < baseIndent {
				break
			}
			if ind == baseIndent && isSameListType(line, ordered) {
				text := listItemText(line)
				items = append(items, item{lines: []string{text}})
				cur = &items[len(items)-1]
				i++
				continue
			}
			// nested list handled by recursive render of item lines (indent retained minus 2?)
			if cur != nil && ind > baseIndent {
				cur.lines = append(cur.lines, line)
				i++
				continue
			}
			break
		}
		// continuation
		if cur != nil && leadingSpaces(line) >= baseIndent+2 {
			cur.lines = append(cur.lines, strings.TrimSpace(line))
			i++
			continue
		}
		if cur != nil && strings.TrimSpace(line) != "" {
			// lazy continuation
			cur.lines = append(cur.lines, strings.TrimSpace(line))
			i++
			continue
		}
		break
	}
	var b strings.Builder
	if ordered {
		if startNum != 1 {
			fmt.Fprintf(&b, "<ol start=\"%d\">\n", startNum)
		} else {
			b.WriteString("<ol>\n")
		}
	} else {
		b.WriteString("<ul>\n")
	}
	for _, it := range items {
		// If item contains a blank line (loose) or nested list lines, render as markdown blocks trimmed of <p> for single para tight case
		// Detect nested list: any line after first is list item
		hasNested := false
		for _, l := range it.lines[1:] {
			if isListItem(l) {
				hasNested = true
			}
		}
		if hasNested {
			// First line text + newline + nested rendered
			first := it.lines[0]
			rest := it.lines[1:]
			// dedent rest by min indent
			rest = dedentLines(rest)
			inner := renderMarkdownFull(strings.Join(rest, "\n"))
			// pulldown puts nested list inside li after text with newline
			fmt.Fprintf(&b, "<li>%s\n%s</li>\n", renderInline(first), inner)
		} else {
			text := strings.Join(it.lines, "\n")
			fmt.Fprintf(&b, "<li>%s</li>\n", renderInline(text))
		}
	}
	if ordered {
		b.WriteString("</ol>\n")
	} else {
		b.WriteString("</ul>\n")
	}
	return b.String(), i
}
func dedentLines(lines []string) []string {
	minInd := -1
	for _, l := range lines {
		if strings.TrimSpace(l) == "" {
			continue
		}
		ind := leadingSpaces(l)
		if minInd == -1 || ind < minInd {
			minInd = ind
		}
	}
	if minInd <= 0 {
		return lines
	}
	out := make([]string, len(lines))
	for i, l := range lines {
		if len(l) >= minInd {
			out[i] = l[minInd:]
		} else {
			out[i] = strings.TrimLeft(l, " ")
		}
	}
	return out
}
func isSameListType(line string, ordered bool) bool {
	if ordered {
		return orderedItemRe.MatchString(line)
	}
	return unorderedItemRe.MatchString(line)
}
func listItemText(line string) string {
	if m := unorderedItemRe.FindStringSubmatch(line); m != nil {
		return m[2]
	}
	if m := orderedItemRe.FindStringSubmatch(line); m != nil {
		return m[4]
	}
	return line
}
func leadingSpaces(s string) int {
	n := 0
	for _, c := range s {
		if c == ' ' {
			n++
		} else if c == '\t' {
			n += 4
		} else {
			break
		}
	}
	return n
}

// ---- Inline rendering ----
// Handles code spans, links/images, autolinks, emphasis/strong, raw HTML omission, escapes, line breaks.
func renderInline(s string) string {
	var out strings.Builder
	runes := []rune(s)
	i := 0
	for i < len(runes) {
		c := runes[i]
		// Backslash escape of ASCII punctuation
		if c == '\\' && i+1 < len(runes) && isASCIIPunct(runes[i+1]) {
			out.WriteString(htmlEscape(string(runes[i+1])))
			i += 2
			continue
		}
		// Code span
		if c == '`' {
			j := i
			for j < len(runes) && runes[j] == '`' {
				j++
			}
			ticks := j - i
			// find closing same ticks
			k := j
			found := -1
			for k < len(runes) {
				if runes[k] == '`' {
					m := k
					for m < len(runes) && runes[m] == '`' {
						m++
					}
					if m-k == ticks {
						found = k
						break
					}
					k = m
				} else {
					k++
				}
			}
			if found >= 0 {
				content := string(runes[j:found])
				// CommonMark: replace newlines with spaces; strip one leading/trailing space if both and not all spaces
				content = strings.ReplaceAll(content, "\n", " ")
				if len(content) >= 2 && content[0] == ' ' && content[len(content)-1] == ' ' && strings.TrimSpace(content) != "" {
					content = content[1 : len(content)-1]
				}
				out.WriteString("<code>")
				out.WriteString(htmlEscape(content))
				out.WriteString("</code>")
				i = found + ticks
				continue
			}
			out.WriteString(htmlEscape(string(runes[i:j])))
			i = j
			continue
		}
		// Image
		if c == '!' && i+1 < len(runes) && runes[i+1] == '[' {
			if alt, url, title, n, ok := parseLink(runes, i+1); ok {
				if title != "" {
					fmt.Fprintf(&out, "<img src=\"%s\" alt=\"%s\" title=\"%s\" />", htmlEscape(url), htmlEscape(altText(alt)), htmlEscape(title))
				} else {
					fmt.Fprintf(&out, "<img src=\"%s\" alt=\"%s\" />", htmlEscape(url), htmlEscape(altText(alt)))
				}
				i = n
				continue
			}
		}
		// Link
		if c == '[' {
			if text, url, title, n, ok := parseLink(runes, i); ok {
				if title != "" {
					fmt.Fprintf(&out, "<a href=\"%s\" title=\"%s\">%s</a>", htmlEscape(url), htmlEscape(title), renderInline(text))
				} else {
					fmt.Fprintf(&out, "<a href=\"%s\">%s</a>", htmlEscape(url), renderInline(text))
				}
				i = n
				continue
			}
		}
		// Autolink / raw HTML
		if c == '<' {
			// find >
			j := i + 1
			for j < len(runes) && runes[j] != '>' && runes[j] != '<' && runes[j] != '\n' {
				j++
			}
			if j < len(runes) && runes[j] == '>' {
				inside := string(runes[i+1 : j])
				if isAutolinkURL(inside) {
					fmt.Fprintf(&out, "<a href=\"%s\">%s</a>", htmlEscape(inside), htmlEscape(inside))
					i = j + 1
					continue
				}
				if isAutolinkEmail(inside) {
					fmt.Fprintf(&out, "<a href=\"mailto:%s\">%s</a>", htmlEscape(inside), htmlEscape(inside))
					i = j + 1
					continue
				}
				if isRawTag(inside) {
					out.WriteString("<!-- raw HTML omitted -->")
					i = j + 1
					continue
				}
			}
			// comment <!-- ... -->
			if strings.HasPrefix(string(runes[i:]), "<!--") {
				end := strings.Index(string(runes[i:]), "-->")
				if end >= 0 {
					out.WriteString("<!-- raw HTML omitted -->")
					i += len([]rune(string(runes[i:])[:end+3]))
					continue
				}
			}
			out.WriteString("&lt;")
			i++
			continue
		}
		// Emphasis / strong
		if c == '*' || c == '_' {
			// count delimiter run
			j := i
			for j < len(runes) && runes[j] == c {
				j++
			}
			runLen := j - i
			// try strong first if >=2
			applied := false
			if runLen >= 2 {
				if closing := findClosingDelim(runes, j, c, 2); closing >= 0 {
					inner := string(runes[i+2 : closing])
					if strings.TrimSpace(inner) != "" {
						out.WriteString("<strong>" + renderInline(inner) + "</strong>")
						i = closing + 2
						applied = true
					}
				}
			}
			if applied {
				continue
			}
			if runLen >= 1 {
				if closing := findClosingDelim(runes, i+1, c, 1); closing >= 0 {
					inner := string(runes[i+1 : closing])
					if strings.TrimSpace(inner) != "" && !strings.HasPrefix(inner, " ") {
						out.WriteString("<em>" + renderInline(inner) + "</em>")
						i = closing + 1
						continue
					}
				}
			}
			out.WriteString(htmlEscape(string(runes[i:j])))
			i = j
			continue
		}
		// Hard break: two spaces before newline, or backslash newline handled above as escaped punctuation? backslash before newline is not punct; CommonMark hard break
		if c == '\n' {
			out.WriteString("\n")
			i++
			continue
		}
		out.WriteString(htmlEscape(string(c)))
		i++
	}
	return out.String()
}
func findClosingDelim(runes []rune, start int, delim rune, need int) int {
	for k := start; k < len(runes); k++ {
		if runes[k] == delim {
			m := k
			for m < len(runes) && runes[m] == delim {
				m++
			}
			if m-k >= need {
				return k
			}
			k = m - 1
		}
		if runes[k] == '`' {
			// skip code span roughly
			k++
			for k < len(runes) && runes[k] != '`' {
				k++
			}
		}
	}
	return -1
}
func isASCIIPunct(r rune) bool {
	return strings.ContainsRune("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~", r)
}
func altText(s string) string {
	// strip inline markdown markers roughly (pulldown renders alt as plain text of inline content)
	s = regexp.MustCompile("[\\*\\_\\`]").ReplaceAllString(s, "")
	return s
}
func parseLink(runes []rune, start int) (text, url, title string, next int, ok bool) {
	// runes[start]=='['
	depth := 0
	i := start
	for i < len(runes) {
		if runes[i] == '[' {
			depth++
		} else if runes[i] == ']' {
			depth--
			if depth == 0 {
				break
			}
		} else if runes[i] == '\\' {
			i++
		}
		i++
	}
	if i >= len(runes) || runes[i] != ']' {
		return "", "", "", start, false
	}
	textRunes := runes[start+1 : i]
	j := i + 1
	if j >= len(runes) || runes[j] != '(' {
		return "", "", "", start, false
	}
	j++
	// skip whitespace
	for j < len(runes) && (runes[j] == ' ' || runes[j] == '\n' || runes[j] == '\t') {
		j++
	}
	// destination: <...> or bare until space or )
	if j < len(runes) && runes[j] == '<' {
		k := j + 1
		for k < len(runes) && runes[k] != '>' {
			k++
		}
		if k >= len(runes) {
			return "", "", "", start, false
		}
		url = string(runes[j+1 : k])
		j = k + 1
	} else {
		k := j
		parens := 0
		for k < len(runes) {
			if runes[k] == '(' {
				parens++
			} else if runes[k] == ')' {
				if parens == 0 {
					break
				}
				parens--
			} else if runes[k] == ' ' || runes[k] == '\n' || runes[k] == '\t' {
				break
			}
			k++
		}
		url = string(runes[j:k])
		j = k
	}
	// optional title
	for j < len(runes) && (runes[j] == ' ' || runes[j] == '\n' || runes[j] == '\t') {
		j++
	}
	if j < len(runes) && (runes[j] == '"' || runes[j] == '\'') {
		quote := runes[j]
		k := j + 1
		for k < len(runes) && runes[k] != quote {
			k++
		}
		if k >= len(runes) {
			return "", "", "", start, false
		}
		title = string(runes[j+1 : k])
		j = k + 1
		for j < len(runes) && (runes[j] == ' ' || runes[j] == '\n' || runes[j] == '\t') {
			j++
		}
	}
	if j >= len(runes) || runes[j] != ')' {
		return "", "", "", start, false
	}
	return string(textRunes), url, title, j + 1, true
}
func isAutolinkURL(s string) bool {
	return regexp.MustCompile(`^[A-Za-z][A-Za-z0-9+.-]{1,31}:[^ \t<>]*$`).MatchString(s)
}
func isAutolinkEmail(s string) bool {
	return regexp.MustCompile(`^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$`).MatchString(s)
}
func isRawTag(inside string) bool {
	if inside == "" {
		return false
	}
	if strings.HasPrefix(inside, "?") || strings.HasPrefix(inside, "!") {
		return true
	}
	s := inside
	if strings.HasPrefix(s, "/") {
		s = s[1:]
	}
	if s == "" || !(s[0] >= 'A' && s[0] <= 'Z' || s[0] >= 'a' && s[0] <= 'z') {
		return false
	}
	return true
}
