const davFiniteDepthBody = "<?xml version=\"1.0\" encoding=\"utf-8\" ?>\n<D:error xmlns:D=\"DAV:\">\n<D:propfind-finite-depth/>\n</D:error>\n"

type davProp struct {
	ns    string // DAV:, http://apache.org/dav/props/, urn:schemas-microsoft-com:
	local string
	value string // inner XML/text (already XML for resourcetype etc is handled specially)
	raw   bool   // value contains raw XML
}

func xmlEscape(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&apos;")
	return r.Replace(s)
