func davEtag(info os.FileInfo) string {
	var ino uint64
	if st, ok := info.Sys().(*syscall.Stat_t); ok && st != nil {
		ino = st.Ino
	}
	mtimeMicros := uint64(info.ModTime().Unix())*1000000 + uint64(info.ModTime().Nanosecond()/1000)
	if info.IsDir() {
		return fmt.Sprintf("%x-%x", ino, mtimeMicros)
	}
	return fmt.Sprintf("%x-%x-%x", ino, info.Size(), mtimeMicros)
}

// birth time via statx on Linux; fallback to modtime
type statxTimestamp struct {
	Sec  int64
	Nsec uint32
	_    int32
}
type statx struct {
	Mask           uint32
	Blksize        uint32
	Attributes     uint64
	Nlink          uint32
	UID            uint32
	GID            uint32
	Mode           uint16
	_              [1]uint16
	Ino            uint64
	Size           uint64
	Blocks         uint64
	AttributesMask uint64
	Atime          statxTimestamp
	Btime          statxTimestamp
	Ctime          statxTimestamp
	Mtime          statxTimestamp
	RdevMajor      uint32
	RdevMinor      uint32
	DevMajor       uint32
	DevMinor       uint32
	_              [14]uint64
}

func birthTime(path string, info os.FileInfo) time.Time {
	// SYS_STATX 332 on amd64
	const SYS_STATX = 332
	const AT_FDCWD = -100
	var stx statx
	p, err := syscall.BytePtrFromString(path)
	if err != nil {
		return info.ModTime()
	}
	_, _, errno := syscall.Syscall6(SYS_STATX, uintptr(AT_FDCWD+1<<64-100), uintptr(unsafe.Pointer(p)), 0, 0xFFF, uintptr(unsafe.Pointer(&stx)), 0)
	// AT_FDCWD is -100; uintptr conversion above trick may be wrong; direct:
	if errno != 0 {
		_, _, errno = syscall.Syscall6(SYS_STATX, uintptr(^uintptr(99)), uintptr(unsafe.Pointer(p)), 0, 0xFFF, uintptr(unsafe.Pointer(&stx)), 0)
	}
	if errno != 0 {
		return info.ModTime()
	}
	if stx.Mask&0x800 == 0 { // STATX_BTIME
		return info.ModTime()
	}
	if stx.Btime.Sec == 0 && stx.Btime.Nsec == 0 {
		return info.ModTime()
	}
	return time.Unix(stx.Btime.Sec, int64(stx.Btime.Nsec))
}
func accessTime(info os.FileInfo) time.Time {
	if st, ok := info.Sys().(*syscall.Stat_t); ok && st != nil {
		return time.Unix(st.Atim.Sec, st.Atim.Nsec)
	}
	return info.ModTime()
}

func davProps(fsPath string, info os.FileInfo) []davProp {
	props := []davProp{}
	bt := birthTime(fsPath, info)
	props = append(props, davProp{"DAV:", "creationdate", bt.UTC().Format("2006-01-02T15:04:05Z"), false})
	if !info.IsDir() {
		props = append(props, davProp{"DAV:", "getcontentlength", fmt.Sprintf("%d", info.Size()), false})
		props = append(props, davProp{"DAV:", "getcontenttype", mimeEssenceForName(info.Name()), false})
	} else {
		props = append(props, davProp{"DAV:", "getcontenttype", "httpd/unix-directory", false})
	}
	props = append(props, davProp{"DAV:", "getetag", davEtag(info), false})
	props = append(props, davProp{"DAV:", "getlastmodified", info.ModTime().UTC().Truncate(time.Second).Format(http.TimeFormat), false})
	props = append(props, davProp{"DAV:", "lockdiscovery", "", false})
