			}
		case xml.EndElement:
			if t.Name.Local == "prop" || t.Name.Local == "include" {
				if depth == 2 {
					inProp = false
				}
			}
			depth--
		}
	}
	if !sawRoot || req.mode == "" {
		return req, fmt.Errorf("no mode")
	}
	return req, nil
}

func (s *server) handleWebDAV(w http.ResponseWriter, r *http.Request, comps []string, fsPath string, displayPath string) {
