package main

import (
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

type server struct {
	cfg            *Config
	serveBase      string // absolute, cleaned original (not symlink-resolved)
	serveCanonical string
	serveIsFile    bool // serve path is not a directory (single file mode)
	spaIndexPath   string
	computedStyle  string
}

func (s *server) fsJoin(comps []string) string {
	if len(comps) == 0 {
		return s.serveBase
	}
	return filepath.Join(append([]string{s.serveBase}, comps...)...)
}

func computeStyle(cfg *Config) string {
	getVars := func(scheme string) string {
		needle := "body[data-theme=" + scheme + "]{"
		idx := strings.Index(styleCSS, needle)
		if idx < 0 {
			return ""
		}
		start := idx + len(needle)
		end := strings.Index(styleCSS[start:], "}")
		if end < 0 {
			return ""
		}
		return styleCSS[start : start+end]
	}
	tailIdx := strings.Index(styleCSS, "\nbody{--background:")
	if tailIdx < 0 {
		return styleCSS
	}
	prefix := styleCSS[:tailIdx+1]
	return prefix + "body{" + getVars(cfg.ColorScheme) + "}\n@media (prefers-color-scheme: dark) {\nbody{" + getVars(cfg.ColorSchemeDark) + "}}"
}

func (s *server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	start := time.Now()
	rw := newRespWriter(w, r, s)
	defer func() {
		rw.finish()
		if verboseLogging {
			dur := time.Since(start).Seconds()
			peer := r.RemoteAddr
			if host, _, err := strings.Cut(peer, ":"), 0, error(nil); err == nil && host != "" {
				_ = host
			}
			// peer IP without port
			ip := peer
			if strings.HasPrefix(peer, "[") {
				if idx := strings.Index(peer, "]"); idx > 0 {
					ip = peer[1:idx]
				}
			} else if idx := strings.LastIndex(peer, ":"); idx > 0 {
				ip = peer[:idx]
			}
			ref := r.Referer()
			if ref == "" {
				ref = "-"
			}
			ua := r.UserAgent()
			if ua == "" {
				ua = "-"
			}
			reqLine := fmt.Sprintf("%s %s %s", r.Method, r.RequestURI, r.Proto)
			logInfo(fmt.Sprintf("%s \"%s\" %d %d \"%s\" \"%s\" %.6f", ip, reqLine, rw.status, rw.bytesWritten, ref, ua, dur))
		}
	}()
	s.handle(rw, r)
}

// segmentEntry keeps raw segment text
func splitEscaped(escaped string) []string {
	if escaped == "" {
		return nil
	}
	return strings.Split(escaped, "/")
}

func percentDecodeSeg(raw string) string {
	var b strings.Builder
	for i := 0; i < len(raw); i++ {
		if raw[i] == '%' && i+2 < len(raw) {
			hi, ok1 := hexVal(raw[i+1])
			lo, ok2 := hexVal(raw[i+2])
			if ok1 && ok2 {
				b.WriteByte(hi<<4 | lo)
				i += 2
				continue
			}
		}
		b.WriteByte(raw[i])
	}
	return b.String()
}

// matchPrefix returns (matched, relRaw, relRawSegments)
func (s *server) matchPrefix(escaped string) (bool, string, []string) {
	prefixSegs := []string{}
	if s.cfg.RoutePrefix != "" {
		prefixSegs = sanitizePathStringToComponents(s.cfg.RoutePrefix)
		// Note: sanitize will pop .. in prefix, but prefix was already just trimmed slashes.
		// Re-derive raw segments without .. popping to keep literal segments:
		raw := strings.Trim(s.cfg.RoutePrefix, "/")
		if raw != "" {
			prefixSegs = strings.Split(raw, "/")
		} else {
			prefixSegs = nil
		}
	}
	segs := splitEscaped(escaped)
	// segs[0] is "" for leading slash
	idx := 0
	if len(segs) > 0 && segs[0] == "" {
		idx = 1
	}
	for _, want := range prefixSegs {
		for idx < len(segs) && segs[idx] == "" {
			idx++
		}
		if idx >= len(segs) {
			return false, "", nil
		}
		if percentDecodeSeg(segs[idx]) != want {
			return false, "", nil
		}
		idx++
	}
	relSegs := []string{}
	if idx < len(segs) {
		relSegs = segs[idx:]
	}
	var relRaw string
	if idx >= len(segs) {
		relRaw = ""
	} else {
		relRaw = "/" + strings.Join(relSegs, "/")
	}
	return true, relRaw, relSegs
}

func (s *server) handle(w http.ResponseWriter, r *http.Request) {
	escaped := r.URL.EscapedPath()
	if escaped == "" {
		escaped = "/"
	}
	matched, relRaw, relSegsRaw := s.matchPrefix(escaped)
	if !matched {
		if escaped == "/upload" {
			if !s.checkAuth(w, r) {
				return
			}
			s.renderPlainError(w, r, &appError{Status: 404, Msg: "Route /upload could not be found", Log: true})
			return
		}
		if !s.checkAuth(w, r) {
			return
		}
		s.routeNotFound(w, r, escaped)
		return
	}
	// Internal endpoints (auth-exempt)
	isStyle := relRaw == "/__miniserve_internal/style.css"
	isFav := relRaw == "/__miniserve_internal/favicon.svg"
	isAPI := relRaw == "/__miniserve_internal/api"
	if (r.Method == "GET" || r.Method == "HEAD") && (isStyle || isFav) {
		if isStyle {
			body := s.computedStyle
			w.Header().Set("Content-Type", "text/css")
			w.Header().Set("Content-Length", fmt.Sprintf("%d", len(body)))
			w.WriteHeader(200)
			_, _ = w.Write([]byte(body))
			return
		}
		body := faviconSVG
		w.Header().Set("Content-Type", "image/svg+xml")
		w.Header().Set("Content-Length", fmt.Sprintf("%d", len(body)))
		w.WriteHeader(200)
		_, _ = w.Write([]byte(body))
		return
	}
	if isAPI && r.Method == "POST" {
		s.handleAPI(w, r)
		return
	}
	// auth for everything else
	if !s.checkAuth(w, r) {
		return
	}
	// Upload / RM endpoints
	if relRaw == "/upload" && s.cfg.UploadProvided {
		if r.Method != "POST" {
			w.Header().Set("Allow", "POST")
			w.Header().Set("Content-Length", "0")
			w.WriteHeader(405)
			return
		}
		s.handleUpload(w, r)
		return
	}
	if relRaw == "/rm" && s.cfg.RMProvided {
		if r.Method != "POST" {
			w.Header().Set("Allow", "POST")
			w.Header().Set("Content-Length", "0")
			w.WriteHeader(405)
			return
		}
		s.handleRM(w, r)
		return
	}
	// WebDAV
	if s.cfg.WebDAV && (r.Method == "PROPFIND" || r.Method == "OPTIONS") {
		comps, segErr := s.resolveComponents(relSegsRaw)
		if segErr != nil {
			// For OPTIONS, DavHandler in original may still respond based on path; fall back to error page for bad segments
			s.renderHTMLError(w, r, segErr)
			return
		}
		// single-file mode: only root represents the file
		var fsPath string
		if s.serveIsFile {
			if relRaw != "" && relRaw != "/" {
				// DavHandler would see a non-existent path under the file; let it 404 via stat of joined path
				fsPath = s.fsJoin(comps)
			} else {
				fsPath = s.serveBase
			}
		} else {
			if s.cfg.NoSymlinks && s.anySymlinkComponent(comps) {
				// PROPFIND on symlink with -P: Dav side in original falls through HTML 404 when webdav disabled, but enabled?
				// Treat as not found for DAV: empty 404 for PROPFIND, OPTIONS allow only
				if r.Method == "PROPFIND" {
					// still need Depth validation first: delegate with non-existent path
					fsPath = s.fsJoin(comps) + "\x00nope"
				} else {
					fsPath = s.fsJoin(comps)
				}
			} else {
				fsPath = s.fsJoin(comps)
			}
		}
		s.handleWebDAV(w, r, comps, fsPath, escaped)
		return
	}
	if r.Method != "GET" && r.Method != "HEAD" {
		if relRaw == "/upload" && s.cfg.RoutePrefix == "" {
			s.renderPlainError(w, r, &appError{Status: 404, Msg: "Route /upload could not be found", Log: true})
			return
		}
		s.routeNotFound(w, r, escaped)
		return
	}
	// GET/HEAD file & directory handling
	comps, segErr := s.resolveComponents(relSegsRaw)
	if segErr != nil {
		s.renderHTMLError(w, r, segErr)
		return
	}
	if s.serveIsFile {
		if relRaw == "" || relRaw == "/" {
			s.serveFile(w, r, s.serveBase, filepath.Base(s.serveBase))
			return
		}
		s.routeNotFound(w, r, escaped)
		return
	}
	if s.cfg.NoSymlinks && s.anySymlinkComponent(comps) {
		s.routeNotFound(w, r, escaped)
		return
	}
	targetFS := s.fsJoin(comps)
	// NUL in any component -> not found (avoid Go open errors panicking messages)
	for _, c := range comps {
		if strings.ContainsRune(c, 0) {
			s.routeNotFound(w, r, escaped)
			return
		}
	}
	info, err := os.Stat(targetFS)
	if err != nil {
		if s.cfg.PrettyURLs {
			s.servePretty(w, r, targetFS)
			return
		}
		if s.cfg.SPA {
			s.serveFile(w, r, s.spaIndexPath, filepath.Base(s.spaIndexPath))
			return
		}
		s.routeNotFound(w, r, escaped)
		return
	}
	if info.IsDir() {
		if len(comps) == 0 && relRaw != "" && relRaw != "/" && !strings.HasSuffix(relRaw, "/") {
			loc := escaped + "/"
			if r.URL.RawQuery != "" {
				loc += "?" + r.URL.RawQuery
			}
			w.Header().Set("Location", loc)
			w.Header().Set("Content-Length", "0")
			w.WriteHeader(307)
			return
		}
		if s.cfg.Index != nil {
			indexFS := rustJoin(targetFS, *s.cfg.Index)
			if idxInfo, e := os.Stat(indexFS); e == nil && !idxInfo.IsDir() {
				s.serveFile(w, r, indexFS, filepath.Base(indexFS))
				return
			}
		}
		s.serveDirectory(w, r, targetFS, comps)
		return
	}
	// file
	name := filepath.Base(targetFS)
	if len(comps) > 0 {
		name = comps[len(comps)-1]
	}
	s.serveFile(w, r, targetFS, name)
}

func (s *server) servePretty(w http.ResponseWriter, r *http.Request, targetFS string) {
	prettyFS := targetFS + ".html"
	f, err := os.Open(prettyFS)
	if err != nil {
		body := rustOSError(err)
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		w.Header().Set("Content-Length", fmt.Sprintf("%d", len(body)))
		w.WriteHeader(404)
		if r.Method != "HEAD" {
			_, _ = w.Write([]byte(body))
		} else {
			_, _ = w.Write([]byte(body))
		}
		return
	}
	info, serr := f.Stat()
	f.Close()
	if serr != nil || info.IsDir() {
		body := "Is a directory (os error 21)"
		if serr != nil {
			body = rustOSError(serr)
		}
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		w.Header().Set("Content-Length", fmt.Sprintf("%d", len(body)))
		w.WriteHeader(404)
		_, _ = w.Write([]byte(body))
		return
	}
	s.serveFile(w, r, prettyFS, filepath.Base(prettyFS))
}

func (s *server) resolveComponents(relSegsRaw []string) ([]string, *appError) {
	var comps []string
	for _, raw := range relSegsRaw {
		if raw == "" {
			continue
		}
		decoded := percentDecodeSeg(raw)
		if strings.Contains(decoded, "/") {
			return nil, &appError{Status: 400, Msg: "segment contained invalid character ('/')"}
		}
		if decoded == ".." {
			if len(comps) > 0 {
				comps = comps[:len(comps)-1]
			}
			continue
		}
		if !s.cfg.Hidden && strings.HasPrefix(decoded, ".") {
			return nil, &appError{Status: 400, Msg: "segment started with invalid character: ('.')"}
		}
		if decoded == "." {
			continue
		}
		comps = append(comps, decoded)
	}
	return comps, nil
}

func (s *server) anySymlinkComponent(comps []string) bool {
	cur := s.serveBase
	for _, c := range comps {
		cur = filepath.Join(cur, c)
		lst, err := os.Lstat(cur)
		if err != nil {
			// If a component in the middle is a symlink to dir, Lstat on deeper path still works (follows dirs except final).
			// If it doesn't exist, deeper checks are moot.
			continue
		}
		if lst.Mode()&os.ModeSymlink != 0 {
			return true
		}
	}
	// The loop above only detects symlinks at exact cumulative paths where the final element of the cumulative path is the link.
	// Our cumulative Join does exactly that per component (Lstat doesn't follow final component), so intermediate dir symlinks are caught at their step.
	return false
}
