		os.Exit(1)
	}
	if cfg.PrintShell != nil {
		fmt.Print(completionsFor(*cfg.PrintShell))
		return
	}
	if cfg.PrintManpage {
		fmt.Print(manpageRaw)
		return
	}
	verboseLogging = cfg.Verbose
	captureUmask()
	if code := run(cfg); code != 0 {
		os.Exit(code)
	}
}

// startupError prints `Error: <text>` to stderr and returns 1; if alreadyLogged, only prints Error line
func startupError(text string) int {
	fmt.Fprintln(os.Stderr, "Error: "+text)
	return 1
}
func startupErrorLogged(msg, cause string, hasCause bool) int {
	logErrorChain(msg, cause, hasCause)
	if hasCause {
		fmt.Fprintf(os.Stderr, "Error: %s\ncaused by: %s\n", msg, cause)
	} else {
		fmt.Fprintf(os.Stderr, "Error: %s\n", msg)
	}
	return 1
}

func run(cfg *Config) int {
	// Auth file processing (before banner/path/TLS)
	if cfg.AuthFile != nil {
		data, err := os.ReadFile(*cfg.AuthFile)
		if err != nil {
			return startupError(rustOSError(err))
		}
		if !utf8Valid(data) {
			return startupError("stream did not contain valid UTF-8")
		}
		for _, line := range rustLines(string(data)) {
			entry, reason := parseAuthValue(line)
			if reason != "" {
				return startupError(reason)
			}
			cfg.Auth = append(cfg.Auth, entry)
		}
	}
	// TLS config
	var tlsConfig *tls.Config
	if cfg.TLSCert != nil && cfg.TLSKey != nil {
		tc, code := loadTLS(*cfg.TLSCert, *cfg.TLSKey)
		if code != 0 {
			return code
		}
		tlsConfig = tc
	}
	// Serve path determination
	rawPath := cfg.Path
	explicit := cfg.PathProvided
	if !explicit {
		rawPath = "."
	}
	// -P serve path symlink check (on original provided path; if not explicit, local dir)
	if cfg.NoSymlinks {
		checkPath := rawPath
		if lst, e := os.Lstat(checkPath); e == nil && lst.Mode()&os.ModeSymlink != 0 {
			// Only when explicitly provided? If current dir itself is... "." is not symlink normally
			if explicit {
				msg := fmt.Sprintf("The -P|--no-symlinks option was provided but the serve path '%s' is a symlink", cfg.Path)
				return startupErrorLogged(msg, "", false)
			}
		}
	}
	absPath, err := filepath.Abs(rawPath)
	if err != nil {
		return startupErrorLogged("Failed to resolve path to be served", rustOSError(err), true)
	}
	canonical, err := filepath.EvalSymlinks(absPath)
	if err != nil {
		// filepath.EvalSymlinks errors include path in Go message; use underlying errno to mimic Rust io error
		return startupErrorLogged("Failed to resolve path to be served", rustOSError(unwrapPathError(err)), true)
	}
	cfg.ServePath = canonical
	// index existence warning
	if cfg.Index != nil {
		idxPath := rustJoin(canonical, *cfg.Index)
		if _, e := os.Stat(idxPath); e != nil {
			if lst, le := os.Lstat(idxPath); le != nil || lst == nil {
				logWarn(fmt.Sprintf("The file '%s' provided for option --index could not be found.", *cfg.Index))
			}
		}
	}
	// Welcome line
	fmt.Fprintf(os.Stdout, "%s v0.32.0\n", colorBold("miniserve"))
	// No explicit path handling
	if !explicit {
		if isTTY(os.Stdout) {
			logWarn("miniserve has been invoked without an explicit path so it will serve the current directory after a short delay.")
			logWarn("Invoke with -h|--help to see options or invoke as `miniserve .` to hide this advice.")
			fmt.Fprint(os.Stdout, "Starting server in ")
			for i := 3; i >= 1; i-- {
				fmt.Fprintf(os.Stdout, "%d… ", i)
				os.Stdout.Sync()
				time.Sleep(1 * time.Second)
			}
			fmt.Fprintln(os.Stdout)
		} else {
			msg := "Refusing to start as no explicit serve path was set and no interactive terminal was attached"
			logError(msg)
			logError("Please set an explicit serve path like: `miniserve /my/path`")
			fmt.Fprintf(os.Stderr, "Error: %s\nPlease set an explicit serve path like: `miniserve /my/path`\n", msg)
			return 1
		}
	}
	// Determine serve base / isFile
	serveBase := absPath
	info, err := os.Stat(serveBase)
	if err != nil {
		return startupErrorLogged("Failed to resolve path to be served", rustOSError(unwrapPathError(err)), true)
	}
	serveIsFile := !info.IsDir()
	// Bind listeners
	ifaces := cfg.Interfaces
	if len(ifaces) == 0 {
		ifaces = []string{"::", "0.0.0.0"}
	}
	listeners, boundAddrs, bcode := bindListeners(ifaces, cfg.Port)
	if bcode != 0 {
		return bcode
	}
	workers := runtime.NumCPU()
	if verboseLogging {
		logInfo(fmt.Sprintf("starting %d workers", workers))
	}
	// Banner rest
	scheme := "http"
	if tlsConfig != nil {
		scheme = "https"
	}
	boundStrs := make([]string, len(boundAddrs))
	for i, a := range boundAddrs {
		boundStrs[i] = a.String()
	}
	fmt.Fprintf(os.Stdout, "Bound to %s\n", colorBoldGreen(joinComma(boundStrs)))
	fmt.Fprintf(os.Stdout, "Serving path %s\n", colorBoldYellow(canonical))
	fmt.Fprintln(os.Stdout, "Available at (non-exhaustive list):")
	for _, u := range availableURLs(boundAddrs, scheme, cfg.RoutePrefix) {
		fmt.Fprintf(os.Stdout, "    %s\n", colorBoldGreen(u))
	}
	fmt.Fprintln(os.Stdout)
	if isTTY(os.Stdout) {
		fmt.Fprintln(os.Stdout, "Quit by pressing CTRL-C")
	}
	// Build server
	srv := &server{
		cfg:            cfg,
		serveBase:      serveBase,
		serveCanonical: canonical,
		serveIsFile:    serveIsFile,
	}
	if cfg.Index != nil {
		srv.spaIndexPath = rustJoin(canonical, *cfg.Index)
	}
	srv.computedStyle = computeStyle(cfg)
	if verboseLogging {
		logInfo("Actix runtime found; starting in Actix runtime")
		for _, a := range boundAddrs {
			logInfo(fmt.Sprintf("starting service: \"actix-web-service-%s\", workers: %d, listening on: %s", a.String(), workers, a.String()))
		}
	}
	// SPA index open check (panics in original after service start log)
	if cfg.SPA {
		f, err := os.Open(srv.spaIndexPath)
		if err != nil {
			panicSPA(err)
			return 134
		}
		f.Close()
	}
	// HTTP servers per listener
	var servers []*http.Server
	errCh := make(chan error, len(listeners))
	for _, ln := range listeners {
		hs := &http.Server{
			Handler:           srv,
			ReadHeaderTimeout: 0,
		}
		if tlsConfig != nil {
			hs.TLSConfig = tlsConfig
		}
		servers = append(servers, hs)
		go func(hs *http.Server, ln net.Listener) {
			var err error
			if tlsConfig != nil {
				err = hs.ServeTLS(ln, "", "")
			} else {
				err = hs.Serve(ln)
			}
			if err != nil && err != http.ErrServerClosed {
				errCh <- err
			} else {
				errCh <- nil
			}
		}(hs, ln)
	}
	// Signals
	sigCh := make(chan os.Signal, 2)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	select {
	case sig := <-sigCh:
		if verboseLogging {
			name := "SIGTERM"
			if sig == syscall.SIGINT {
				name = "SIGINT"
			}
			logInfo(name + " received; starting graceful shutdown")
			logInfo("accept thread stopped")
			for i := 0; i < workers; i++ {
				logInfo("shutting down idle worker")
			}
		}
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		for _, hs := range servers {
			_ = hs.Shutdown(ctx)
		}
		cancel()
		return 0
	case err := <-errCh:
		if err != nil {
			// server runtime error
			logError(err.Error())
			return 1
		}
		return 0
	}
}

func utf8Valid(b []byte) bool { return strings.ContainsRune(string(b), 0) == false && isValidUTF8(string(b)) }
func isValidUTF8(s string) bool {
	// use std via bytes? avoid import cycle: simple check with range RuneError handling is lossy; use encoding
	return validUTF8String(s)
}

func rustLines(s string) []string {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, "\n")
	// Rust str::lines: final trailing newline doesn't produce last empty; \r stripped
	if len(parts) > 0 && parts[len(parts)-1] == "" && strings.HasSuffix(s, "\n") {
		parts = parts[:len(parts)-1]
	}
	for i, p := range parts {
		parts[i] = strings.TrimSuffix(p, "\r")
	}
	return parts
}

func unwrapPathError(err error) error {
	// Extract innermost errno-carrying error for rustOSError formatting
	for err != nil {
		if pe, ok := err.(*os.PathError); ok {
			err = pe.Err
			continue
		}
		if le, ok := err.(*os.LinkError); ok {
			err = le.Err
			continue
		}
		break
	}
	return err
}

func bindListeners(ifaces []string, port int) ([]net.Listener, []net.Addr, int) {
	var listeners []net.Listener
	var addrs []net.Addr
	actualPort := port
	for idx, ipStr := range ifaces {
		ip := net.ParseIP(ipStr)
		network := "tcp"
		if ip != nil {
			if ip.To4() != nil && strings.Contains(ipStr, ".") {
				network = "tcp4"
			} else {
				network = "tcp6"
			}
		}
		addr := &net.TCPAddr{IP: ip, Port: actualPort}
		lc := net.ListenConfig{}
		if network == "tcp6" {
			lc.Control = func(network, address string, c syscall.RawConn) error {
				var opErr error
				_ = c.Control(func(fd uintptr) {
					opErr = syscall.SetsockoptInt(int(fd), syscall.IPPROTO_IPV6, syscall.IPV6_V6ONLY, 1)
				})
				return opErr
			}
		}
		ln, err := lc.Listen(nil, network, addr.String())
		if err != nil {
			for _, l := range listeners {
				l.Close()
			}
			displayAddr := addr.String()
			msg := fmt.Sprintf("Failed to bind server to %s", displayAddr)
			cause := rustOSError(unwrapPathError(err))
			// Go errors may wrap errno deep in OpError; unwrapPathError only handles PathError; use extractErrno path in rustOSError on err itself if cause not errno-like
			if extractErrno(err) != 0 {
				cause = rustOSError(err)
			}
			return nil, nil, startupErrorLogged(msg, cause, true)
		}
		listeners = append(listeners, ln)
		addrs = append(addrs, ln.Addr())
		if idx == 0 && port == 0 {
			if ta, ok := ln.Addr().(*net.TCPAddr); ok {
				actualPort = ta.Port
			}
		}
	}
	return listeners, addrs, 0
}

func availableURLs(bound []net.Addr, scheme, prefix string) []string {
	seen := map[string]bool{}
	var urls []string
	add := func(hostport string) {
		u := scheme + "://" + hostport + prefix
		if !seen[u] {
			seen[u] = true
			urls = append(urls, u)
		}
	}
	// If any bound is unspecified, original enumerates local addresses sorted v4 before v6 and dedups.
	hasUnspecified := false
	for _, a := range bound { // do unspecified handling in a first pass matching observed ordering
		ta := a.(*net.TCPAddr)
		if ta.IP.IsUnspecified() {
			hasUnspecified = true
		}
	}
	if hasUnspecified {
		// collect local IPs for each unspecified family present
		families := map[bool]bool{} // true=v6
		portByFam := map[bool]int{}
		for _, a := range bound {
			ta := a.(*net.TCPAddr)
			if ta.IP.IsUnspecified() {
				is6 := ta.IP.To4() == nil
				families[is6] = true
				portByFam[is6] = ta.Port
			}
		}
		local := localIPs()
		// sort v4 first then v6, then string
		sort.Slice(local, func(i, j int) bool {
			i6 := local[i].To4() == nil
			j6 := local[j].To4() == nil
			if i6 != j6 {
				return !i6
			}
			return local[i].String() < local[j].String()
		})
		// First add URLs for unspecified families (dedup overall)
		for _, ip := range local {
			is6 := ip.To4() == nil
			if !families[is6] {
				continue
			}
			port := portByFam[is6]
			add(formatHostPort(ip, port))
		}
		// Then explicit bound addresses in given order (would conflict bind-wise usually)
		for _, a := range bound {
			ta := a.(*net.TCPAddr)
			if !ta.IP.IsUnspecified() {
				add(formatHostPort(ta.IP, ta.Port))
			}
		}
		return urls
	}
	for _, a := range bound {
		ta := a.(*net.TCPAddr)
		add(formatHostPort(ta.IP, ta.Port))
	}
	return urls
}
func formatHostPort(ip net.IP, port int) string {
	return net.JoinHostPort(ip.String(), fmt.Sprintf("%d", port))
}
func localIPs() []net.IP {
	var out []net.IP
	ifs, err := net.Interfaces()
	if err != nil {
		return []net.IP{net.ParseIP("127.0.0.1"), net.ParseIP("::1")}
	}
	for _, iface := range ifs {
		addrs, err := iface.Addrs()
		if err != nil {
			continue
		}
		for _, ad := range addrs {
			var ip net.IP
			switch v := ad.(type) {
			case *net.IPNet:
				ip = v.IP
			case *net.IPAddr:
				ip = v.IP
			}
			if ip == nil || ip.IsUnspecified() || ip.IsLinkLocalMulticast() {
				continue
			}
			// Include loopback and global/private host addresses; skip link-local unicast like fe80:: ?
			if ip.IsLinkLocalUnicast() {
				continue
			}
			out = append(out, ip)
		}
	}
	if len(out) == 0 {
		out = []net.IP{net.ParseIP("127.0.0.1"), net.ParseIP("::1")}
	}
	return out
}

func panicSPA(err error) {
	cause := unwrapPathError(err)
	errno := extractErrno(cause)
	kind := "NotFound"
	msg := errnoMessage(errno)
	switch errno {
	case syscall.ENOENT:
		kind = "NotFound"
	case syscall.EACCES:
		kind = "PermissionDenied"
	case syscall.ENOTDIR:
		kind = "NotADirectory"
	case syscall.EISDIR:
		kind = "IsADirectory"
	default:
		kind = "Other"
	}
	pid := os.Getpid()
	// thread id in original varies; use pid+2 approx like examples (main thread tid near pid) - tests likely don't parse.
	fmt.Fprintf(os.Stderr, "\nthread 'actix-rt|system:0|arbiter:0' (%d) panicked at src/main.rs:346:26:\nCan't open SPA index file.: Os { code: %d, kind: %s, message: \"%s\" }\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", pid+4, int(errno), kind, msg)
	// Abort like panic=abort
	_ = syscall.Kill(pid, syscall.SIGABRT)
	time.Sleep(100 * time.Millisecond)
	os.Exit(134)
}

func loadTLS(certFile, keyFile string) (*tls.Config, int) {
	certPEM, err := os.ReadFile(certFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Couldn't access TLS certificate \"%s\"\n\nCaused by:\n    %s\n", certFile, rustOSError(unwrapPathError(err)))
		return nil, 1
	}
	keyPEM, err := os.ReadFile(keyFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: Couldn't access TLS key \"%s\"\n\nCaused by:\n    %s\n", keyFile, rustOSError(unwrapPathError(err)))
		return nil, 1
	}
	// Parse private key first (original panics if none)
	key, found := parsePrivateKeyPEM(keyPEM)
	if !found {
		pid := os.Getpid()
		fmt.Fprintf(os.Stderr, "thread 'main' (%d) panicked at src/config.rs:271:22:\nNo private key found\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n", pid)
		_ = syscall.Kill(pid, syscall.SIGABRT)
		time.Sleep(100 * time.Millisecond)
		os.Exit(134)
	}
	// Parse certs
	var certDER [][]byte
	rest := certPEM
	for {
		var block *pem.Block
		block, rest = pem.Decode(rest)
		if block == nil {
			break
		}
		if block.Type == "CERTIFICATE" {
			certDER = append(certDER, block.Bytes)
		}
	}
	if len(certDER) == 0 {
		fmt.Fprintln(os.Stderr, "Error: peer sent no certificates")
		return nil, 1
	}
	leaf, err := x509.ParseCertificate(certDER[0])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %s\n", tlsCertParseError(err))
		return nil, 1
	}
	if !publicKeysEqual(leaf.PublicKey, publicKeyOf(key)) {
		fmt.Fprintln(os.Stderr, "Error: keys may not be consistent: KeyMismatch")
		return nil, 1
	}
	cert := tls.Certificate{Certificate: certDER, PrivateKey: key, Leaf: leaf}
	cfg := &tls.Config{
		Certificates: []tls.Certificate{cert},
		MinVersion:   tls.VersionTLS12,
		NextProtos:   []string{"h2", "http/1.1"},
	}
	return cfg, 0
}
func tlsCertParseError(err error) string {
	// best effort; Rustls errors are opaque
	return "peer sent no certificates"
}
func parsePrivateKeyPEM(data []byte) (crypto.PrivateKey, bool) {
	rest := data
	for {
		var block *pem.Block
		block, rest = pem.Decode(rest)
		if block == nil {
			return nil, false
		}
		switch block.Type {
		case "PRIVATE KEY":
			k, err := x509.ParsePKCS8PrivateKey(block.Bytes)
			if err == nil {
				return k, true
			}
			return nil, false
		case "RSA PRIVATE KEY":
			k, err := x509.ParsePKCS1PrivateKey(block.Bytes)
			if err == nil {
				return k, true
			}
			return nil, false
		case "EC PRIVATE KEY":
			k, err := x509.ParseECPrivateKey(block.Bytes)
			if err == nil {
				return k, true
			}
			return nil, false
		}
	}
}
func publicKeyOf(k crypto.PrivateKey) crypto.PublicKey {
	switch kk := k.(type) {
	case *rsa.PrivateKey:
		return &kk.PublicKey
	case *ecdsa.PrivateKey:
		return &kk.PublicKey
	case ed25519.PrivateKey:
		return kk.Public()
	default:
		if signer, ok := k.(crypto.Signer); ok {
			return signer.Public()
		}
		return nil
	}
}
func publicKeysEqual(a, b crypto.PublicKey) bool {
	if a == nil || b == nil {
		return false
	}
	switch ak := a.(type) {
	case *rsa.PublicKey:
		bk, ok := b.(*rsa.PublicKey)
		return ok && ak.N.Cmp(bk.N) == 0 && ak.E == bk.E
	case *ecdsa.PublicKey:
		bk, ok := b.(*ecdsa.PublicKey)
		return ok && ak.Curve == bk.Curve && ak.X.Cmp(bk.X) == 0 && ak.Y.Cmp(bk.Y) == 0
	case ed25519.PublicKey:
		bk, ok := b.(ed25519.PublicKey)
		return ok && reflect.DeepEqual([]byte(ak), []byte(bk))
	default:
		return reflect.DeepEqual(a, b)
	}
}

