func humanizeTime(t time.Time, now time.Time) string {
	diff := now.Sub(t)
	future := false
	if diff < 0 {
		future = true
		diff = -diff
	}
	secs := int64(diff.Seconds())
	// diff.Seconds truncates toward zero; files set to whole seconds behave as original when now has fractional seconds.
	var core string
	plural := func(n int64, one, many string) string {
		if n == 1 {
			return one
		}
		return fmt.Sprintf("%d %s", n, many)
	}
	max2 := func(n int64) int64 {
		if n < 2 {
			return 2
		}
		return n
	}
	switch {
	case secs <= 10:
		return "now"
	case secs <= 45:
		core = plural(secs, "a second", "seconds")
		// secs>=11 here so not singular in practice
		if secs != 1 {
			core = fmt.Sprintf("%d seconds", secs)
		}
	case secs <= 90:
		core = "a minute"
	case secs <= 2700:
		core = plural(max2(secs/60), "a minute", "minutes")
	case secs <= 5400:
		core = "an hour"
	case secs <= 79200:
		core = plural(max2(secs/3600), "an hour", "hours")
	case secs <= 129600:
		core = "a day"
	case secs <= 561600:
		core = plural(max2(secs/86400), "a day", "days")
	case secs <= 907200:
		core = "a week"
	case secs <= 2505600:
		core = plural(max2(secs/604800), "a week", "weeks")
	case secs <= 3888000:
		core = "a month"
	case secs <= 29808000:
		core = plural(max2(secs/2592000), "a month", "months")
	case secs <= 47260800:
		core = "a year"
	default:
		core = plural(max2(secs/31536000), "a year", "years")
	}
	if future {
		return "in " + core
	}
	return core + " ago"
}

'''
t=t[:start]+new+t[end:]
p.write_text(t)
