vals=[0b001000111110111,0b000110001100011,0b011011101001011]
# BCH format generator: data 5 bits (ec<<3|mask), generator 0x537, mask 0x5412
def fmt(ec,mask):
    data=(ec<<3)|mask
    rem=data
    for i in range(10):
        rem=(rem<<1) ^ ((rem>>9)*0x537)
    return ((data<<10)|rem) ^ 0x5412
# ec bits mapping in format: L=1,M=0,Q=3,H=2
names={0:'M',1:'L',3:'Q',2:'H'}
for v in vals:
    found=[]
    for ec in range(4):
        for mask in range(8):
            if fmt(ec,mask)==v: found.append((names[ec],mask))
            if fmt(ec,mask)==int(format(v,'015b')[::-1],2): found.append(('rev',names[ec],mask))
    print(format(v,'015b'),found)
