	case 1:
		return r%2 == 0
	case 2:
		return c%3 == 0
	case 3:
		return (r+c)%3 == 0
	case 4:
		return (r/2+c/3)%2 == 0
	case 5:
		return ((r*c)%2+(r*c)%3) == 0
	case 6:
		return (((r*c)%2+(r*c)%3)%2) == 0
	case 7:
