			col[rr] = grid[rr][r]
		}
		penalty += patternPenalty(col)
	}
	// Rule4 proportion
	dark := 0
	for r := 0; r < size; r++ {
		for c := 0; c < size; c++ {
			if grid[r][c] {
				dark++
			}
		}
	}
