func runPenalty(line []bool) int {
	pen := 0
	runLen := 1
	for i := 1; i < len(line); i++ {
		if line[i] == line[i-1] {
			runLen++
		} else {
			if runLen >= 5 {
				pen += 3 + (runLen - 5)
			}
			runLen = 1
		}
	}
	if runLen >= 5 {
		pen += 3 + (runLen - 5)
	}
	return pen
}
func patternPenalty(line []bool) int {
	pen := 0
	size := len(line)
	pat := []bool{true, false, true, true, true, false, true}
	for i := 0; i+7 <= size; i++ {
		match := true
		for j := 0; j < 7; j++ {
			if line[i+j] != pat[j] {
				match = false
