		// The above composes poly * (x + 2^i)? Need consistency with division below; use known Nayuki approach instead.
		poly = next
	}
	return poly
}
// Use Nayuki-style reed solomon: compute generator and remainder using polynomial coefficients in descending order except leading.
func rsGeneratorPoly(deg int) []byte {
	poly := make([]byte, deg)
	poly[deg-1] = 1 // start with monomial x^0 coefficient representation? We'll use documented algorithm:
	// Polynomial stored as coefficients for x^(n-1)..x^0 with implicit leading coefficient of next degree?
	// Alternative implementation via synthetic multiplication in log domain from thonky:
	result := []byte{1}
	for i := 0; i < deg; i++ {
		next := make([]byte, len(result)+1)
		for j, coef := range result {
			// multiply by x
			next[j] ^= coef
			// multiply by 2^i
			next[j+1] ^= gfMul(coef, gfExp[i])
		}
		result = next
	}
	// result length deg+1, leading coefficient 1 at index0
	return result[1:] // drop leading 1
}
func rsComputeDivisorRemainder(data []byte, ecLen int) []byte {
	divisor := rsGeneratorPoly(ecLen)
	result := make([]byte, ecLen)
	for _, b := range data {
		factor := b ^ result[0]
		copy(result, result[1:])
		result[ecLen-1] = 0
		for j := 0; j < ecLen; j++ {
			result[j] ^= gfMul(divisor[j], factor)
		}
	}
	return result
}

func qrBuildMatrix(version int, dataBits []bool, mask int) [][]bool {
	size := version*4 + 17
	grid := make([][]bool, size)
	isFunc := make([][]bool, size)
	for i := range grid {
		grid[i] = make([]bool, size)
		isFunc[i] = make([]bool, size)
	}
	setFunc := func(r, c int, dark bool) {
		if r >= 0 && r < size && c >= 0 && c < size {
			grid[r][c] = dark
			isFunc[r][c] = true
		}
	}
	// Timing first (will be overwritten by finders where overlapping)
	for i := 0; i < size; i++ {
		setFunc(6, i, i%2 == 0)
		setFunc(i, 6, i%2 == 0)
	}
	// Finders
	drawFinder := func(r0, c0 int) {
		for dr := -1; dr <= 7; dr++ {
			for dc := -1; dc <= 7; dc++ {
				r, c := r0+dr, c0+dc
				if r < 0 || r >= size || c < 0 || c >= size {
					continue
				}
				dist := max3(abs(dr-3), abs(dc-3), 0)
				// finder with separator: dr/dc -1 or 7 are separator (light)
				dark := false
				if dr >= 0 && dr <= 6 && dc >= 0 && dc <= 6 {
					dark = dist != 2 && dist != 4 // ring: distance from center chebyshev: outer 3 dark, 2 light, <=1 dark; dist computed from 3 gives 0..3; separator dist 4 handled outside range
					// chebyshev distance from center (3,3): 3=outer border dark, 2= light ring, 1/0 center dark
					cheb := abs(dr - 3)
					if abs(dc-3) > cheb {
						cheb = abs(dc - 3)
					}
					dark = cheb != 2
				}
				setFunc(r, c, dark)
			}
		}
	}
	drawFinder(0, 0)
	drawFinder(0, size-7)
	drawFinder(size-7, 0)
	// Alignments
	centers := qrTableL[version].alignCenters
	for _, cr := range centers {
		for _, cc := range centers {
			// skip overlapping finders
			if (cr == 6 && cc == 6) || (cr == 6 && cc == size-7) || (cr == size-7 && cc == 6) {
				continue
			}
			for dr := -2; dr <= 2; dr++ {
				for dc := -2; dc <= 2; dc++ {
					cheb := abs(dr)
					if abs(dc) > cheb {
						cheb = abs(dc)
					}
					setFunc(cr+dr, cc+dc, cheb != 1)
				}
			}
		}
	}
	// Reserve format bits (set later) - mark function cells around finders
	for i := 0; i < 9; i++ {
		setFunc(8, i, grid[8][i])
		setFunc(i, 8, grid[i][8])
	}
	for i := 0; i < 8; i++ {
		setFunc(8, size-1-i, grid[8][size-1-i])
		setFunc(size-1-i, 8, grid[size-1-i][8])
	}
	// Dark module
	setFunc(size-8, 8, true)
	// Version info
	if version >= 7 {
		rem := version
		for i := 0; i < 12; i++ {
			rem = (rem << 1) ^ (((rem >> 11) & 1) * 0x1f25)
		}
		bitsVal := (version << 12) | (rem & 0xfff)
		for i := 0; i < 18; i++ {
			bit := ((bitsVal >> i) & 1) == 1
			setFunc(i/3, size-11+i%3, bit)
			setFunc(size-11+i%3, i/3, bit)
		}
	}
	// Place data
	idx := 0
	upward := true
	for right := size - 1; right >= 1; right -= 2 {
		if right == 6 {
			right = 5
		}
		for vert := 0; vert < size; vert++ {
			r := vert
			if upward {
				r = size - 1 - vert
			}
			for dc := 0; dc < 2; dc++ {
				c := right - dc
				if isFunc[r][c] {
					continue
				}
				bit := false
				if idx < len(dataBits) {
					bit = dataBits[idx]
					idx++
				}
				if qrMaskBit(mask, r, c) {
					bit = !bit
				}
				grid[r][c] = bit
			}
		}
		upward = !upward
	}
	// Format bits
	formatBits := qrFormatBits(mask) // EC L = 01
	// place first copy: bits 14..0 as per spec positions listed from bit14
	coords1 := [][2]int{{8, 0}, {8, 1}, {8, 2}, {8, 3}, {8, 4}, {8, 5}, {8, 7}, {8, 8}, {7, 8}, {5, 8}, {4, 8}, {3, 8}, {2, 8}, {1, 8}, {0, 8}}
	// coords are (col,row)
	for i, cr := range coords1 {
		bit := ((formatBits >> (14 - i)) & 1) == 1
		grid[cr[1]][cr[0]] = bit
	}
	// second copy
	for i := 0; i < 8; i++ {
		bit := ((formatBits >> (14 - i)) & 1) == 1
		grid[8][size-1-i] = bit
	}
	for i := 8; i < 15; i++ {
		bit := ((formatBits >> (14 - i)) & 1) == 1
		grid[size-15+i][8] = bit
	}
	grid[size-8][8] = true
	return grid
}

func qrFormatBits(mask int) int {
	// EC level L indicator bits = 01
	data := (1 << 3) | mask
	rem := data
	for i := 0; i < 10; i++ {
		rem = (rem << 1) ^ (((rem >> 9) & 1) * 0x537)
	}
	return ((data << 10) | (rem & 0x3ff)) ^ 0x5412
}
func qrMaskBit(mask, r, c int) bool {
	switch mask {
	case 0:
		return (r+c)%2 == 0
	case 1:
		return r%2 == 0
	case 2:
		return c%3 == 0
	case 3:
		return (r+c)%3 == 0
	case 4:
		return (r/2+c/3)%2 == 0
	case 5:
		return ((r*c)%2+(r*c)%3) == 0
	case 6:
		return (((r*c)%2+(r*c)%3)%2) == 0
	case 7:
		return (((r+c)%2+(r*c)%3)%2) == 0
	}
	return false
}
func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}
func max3(a, b, c int) int {
	m := a
	if b > m {
		m = b
	}
	if c > m {
		m = c
	}
	return m
}

func qrPenalty(grid [][]bool) int {
	size := len(grid)
	penalty := 0
	// Rule1 rows and cols runs
	for r := 0; r < size; r++ {
		penalty += runPenalty(grid[r])
		col := make([]bool, size)
		for rr := 0; rr < size; rr++ {
			col[rr] = grid[rr][r]
		}
		penalty += runPenalty(col)
	}
	// Rule2 2x2 blocks
	for r := 0; r < size-1; r++ {
		for c := 0; c < size-1; c++ {
			if grid[r][c] == grid[r][c+1] && grid[r][c] == grid[r+1][c] && grid[r][c] == grid[r+1][c+1] {
				penalty += 3
			}
		}
	}
	// Rule3 patterns 1011101 with 4 light modules on either side
	for r := 0; r < size; r++ {
		penalty += patternPenalty(grid[r])
		col := make([]bool, size)
		for rr := 0; rr < size; rr++ {
			col[rr] = grid[rr][r]
		}
		penalty += patternPenalty(col)
	}
	// Rule4 proportion
	dark := 0
	for r := 0; r < size; r++ {
		for c := 0; c < size; c++ {
			if grid[r][c] {
				dark++
			}
		}
	}
	// Nayuki-style: find steps of 5% away from 50%
	k := 0
	// Compute (abs(dark*20 - total*10) + total -1)/total -1? Use standard formula:
	total := size * size
	// number of 5% steps below/above 50 (integer)
	// deviation = |dark*100/total - 50| /5, floored using exact rational logic like QR spec examples
	// Use: k = floor( abs(dark*20 - total*10) / total )
	num := dark*20 - total*10
	if num < 0 {
		num = -num
	}
	k = (num + total - 1) / total // ceil? This matches Nayuki getPenaltyScore rule4 approximation variants may differ; adjust after tests
	penalty += k * 10
	return penalty
}
func runPenalty(line []bool) int {
	pen := 0
	runLen := 1
	for i := 1; i < len(line); i++ {
		if line[i] == line[i-1] {
			runLen++
		} else {
			if runLen >= 5 {
				pen += 3 + (runLen - 5)
			}
			runLen = 1
		}
	}
	if runLen >= 5 {
		pen += 3 + (runLen - 5)
	}
	return pen
}
func patternPenalty(line []bool) int {
	pen := 0
	size := len(line)
	pat := []bool{true, false, true, true, true, false, true}
	for i := 0; i+7 <= size; i++ {
		match := true
		for j := 0; j < 7; j++ {
			if line[i+j] != pat[j] {
				match = false
				break
			}
		}
		if !match {
			continue
		}
		before := i >= 4 && !line[i-1] && !line[i-2] && !line[i-3] && !line[i-4]
		after := i+11 <= size && !line[i+7] && !line[i+8] && !line[i+9] && !line[i+10]
		if before || after {
			pen += 40
		}
	}
	return pen
}
