	bw := &bitWriter{}
	// WBITS: encode window size 22 -> first bit 1, next 3 bits value 5 (17+5)
	bw.writeBits(1, 1)
	bw.writeBits(5, 3)
	if len(data) == 0 {
		bw.writeBits(1, 1) // ISLAST
		bw.writeBits(1, 1) // ISLASTEMPTY
		return bw.bytes()
	}
	const chunk = 65536
	for offset := 0; offset < len(data); {
		n := chunk
		if offset+n > len(data) {
			n = len(data) - offset
		}
		chunkData := data[offset : offset+n]
		// Non-final uncompressed meta-block (a final meta-block cannot be uncompressed;
		// the stream is terminated with an empty final block below, like the Rust brotli encoder).
		bw.writeBits(0, 1)             // ISLAST = 0
		bw.writeBits(0, 2)             // MNIBBLES = 4 nibbles
		bw.writeBits(uint32(n-1), 16)  // MLEN-1
		bw.writeBits(1, 1)             // ISUNCOMPRESSED
		bw.alignToByte()
		bw.buf.Write(chunkData)
		offset += n
	}
	// Empty final meta-block (stream is byte-aligned here)
	bw.writeBits(1, 1)
	bw.writeBits(1, 1)
	return bw.bytes()
}
'''
