func parseEntity(runes []rune, start int) (string, int, bool) {
	// find semicolon within 34 chars
	end := -1
	for i := start + 1; i < len(runes) && i < start+35; i++ {
		if runes[i] == ';' {
			end = i
			break
		}
		if runes[i] == '&' || runes[i] == ' ' || runes[i] == '\n' || runes[i] == '<' {
			break
		}
	}
	if end < 0 {
		return "", start, false
	}
	ent := string(runes[start : end+1])
	dec := stdhtml.UnescapeString(ent)
	if dec == ent {
		return "", start, false
	}
	return dec, end + 1, true
}

'''
