		if c == '*' || c == '_' {
			// count delimiter run
			j := i
			for j < len(runes) && runes[j] == c {
				j++
			}
			runLen := j - i
			// Underscore intraword: literal
			if c == '_' && i > 0 && j < len(runes) && isAlnumRune(runes[i-1]) && isAlnumRune(runes[j]) {
				out.WriteString(htmlEscape(string(runes[i:j])))
				i = j
				continue
			}
			// Triple delimiter: ***text*** or ___text___
			if runLen >= 3 {
				if closing := findClosingRun(runes, j, c, 3); closing >= 0 {
					inner := string(runes[i+3 : closing])
					if strings.TrimSpace(inner) != "" {
						out.WriteString("<em><strong>" + renderInline(inner) + "</strong></em>")
						i = closing + 3
						continue
					}
				}
			}
			// Strong (2)
			if runLen >= 2 {
				if closing := findClosingRun(runes, i+2, c, 2); closing >= 0 {
					inner := string(runes[i+2 : closing])
					if strings.TrimSpace(inner) != "" {
						// If opening run had extra delimiters beyond 2 (e.g. left from triple handling) they're consumed above.
						out.WriteString("<strong>" + renderInline(inner) + "</strong>")
						i = closing + 2
						continue
					}
				}
			}
			// Emphasis (1): find a closing run of odd length (1 or 3...) preferring the last single of a run sequence that closes nesting.
