# Add helper funcs after findClosingDelim
helpers=r'''
func isAlnumRune(r rune) bool {
	return r >= '0' && r <= '9' || r >= 'A' && r <= 'Z' || r >= 'a' && r <= 'z' || r > 127
}
func findClosingRun(runes []rune, start int, delim rune, need int) int {
	for k := start; k < len(runes); k++ {
		if runes[k] == '`' {
			k++
			for k < len(runes) && runes[k] != '`' {
				k++
			}
			continue
		}
		if runes[k] == delim {
			m := k
			for m < len(runes) && runes[m] == delim {
				m++
			}
			if m-k >= need {
				// For triple closing, use the last 3 of the run? Caller consumes 3 from start of run; to keep inner clean when runLen>3 prefer returning m-need
				if need == 3 && m-k > 3 {
					return m - 3
				}
				return k
			}
			k = m - 1
		}
	}
	return -1
}
func findEmClosing(runes []rune, start int, delim rune) (int, int) {
	for k := start; k < len(runes); k++ {
		if runes[k] == '`' {
			k++
			for k < len(runes) && runes[k] != '`' {
				k++
			}
			continue
		}
		if runes[k] != delim {
			continue
		}
		m := k
		for m < len(runes) && runes[m] == delim {
			m++
		}
		runLen := m - k
		// Underscore intraword closers are not valid if surrounded by alnum on both sides of run
		if delim == '_' && k > 0 && m < len(runes) && isAlnumRune(runes[k-1]) && isAlnumRune(runes[m]) {
			k = m - 1
			continue
		}
		if runLen == 2 {
			// strong delimiter: skip as closer for single em (it will be handled inside recursive render)
			k = m - 1
			continue
		}
		if runLen >= 3 {
			// consume one delimiter for em (the last one in the run would be more correct if strong inside; return position of last)
			return m - 1, 1
		}
		return k, 1
	}
	return -1, 0
}
'''
t=t.replace("func isASCIIPunct(r rune) bool {",helpers+"func isASCIIPunct(r rune) bool {",1)
p.write_text(t)
