{"command":"cat > tartransform.go <<'GO'
package main

import (
	"fmt"
	"io"
	"strconv"
	"strings"
)

// tarRustWriter rewrites Go archive/tar output to match Rust tar crate header conventions:
// - checksum field as 7 octal digits + NUL
// - non-root directory names without a trailing slash
type tarRustWriter struct {
	w             io.Writer
	buf           []byte
	remainingData int64
	seenEntry     bool
	err           error
}

func newTarRustWriter(w io.Writer) *tarRustWriter { return &tarRustWriter{w: w} }

func (t *tarRustWriter) Write(p []byte) (int, error) {
	if t.err != nil {
		return 0, t.err
	}
	t.buf = append(t.buf, p...)
	if err := t.process(false); err != nil {
		t.err = err
		return 0, err
	}
	return len(p), nil
}
func (t *tarRustWriter) Flush() error {
	if err := t.process(true); err != nil {
		return err
	}
	if f, ok := t.w.(interface{ Flush() error }); ok {
		return f.Flush()
	}
	return nil
}
func (t *tarRustWriter) process(final bool) error {
	for {
		if t.remainingData > 0 {
			if len(t.buf) == 0 {
				return nil
			}
			n := int64(len(t.buf))
			if n > t.remainingData {
				n = t.remainingData
			}
			if _, err := t.w.Write(t.buf[:n]); err != nil {
				return err
			}
			t.buf = append([]byte{}, t.buf[n:]...)
			t.remainingData -= n
			continue
		}
		if len(t.buf) < 512 {
			if final && len(t.buf) > 0 {
				if _, err := t.w.Write(t.buf); err != nil {
					return err
				}
				t.buf = nil
			}
			return nil
		}
		header := make([]byte, 512)
		copy(header, t.buf[:512])
		t.buf = append([]byte{}, t.buf[512:]...)
		// all zero block: pass through
		allZero := true
		for _, b := range header {
			if b != 0 {
				allZero = false
				break
			}
		}
		if allZero {
			if _, err := t.w.Write(header); err != nil {
				return err
			}
			continue
		}
		size := parseTarSize(header[124:136])
		typeflag := header[156]
		isMeta := typeflag == 'L' || typeflag == 'K' || typeflag == 'x' || typeflag == 'g'
		if !isMeta {
			if typeflag == '5' && t.seenEntry {
				// strip trailing slash in name field if present
				nameField := header[0:100]
				end := 0
				for end < 100 && nameField[end] != 0 {
					end++
				}
				if end > 0 && nameField[end-1] == '/' {
					header[end-1] = 0
				}
			}
			t.seenEntry = true
		}
		// recompute checksum and format as 7 octal digits + NUL
		for i := 148; i < 156; i++ {
			header[i] = ' '
		}
		sum := 0
		for _, b := range header {
			sum += int(b)
		}
		chk := fmt.Sprintf("%07o\x00", sum)
		copy(header[148:156], chk)
		if _, err := t.w.Write(header); err != nil {
			return err
		}
		if size > 0 {
			t.remainingData = ((size + 511) / 512) * 512
		}
	}
}
func parseTarSize(field []byte) int64 {
	if len(field) > 0 && field[0]&0x80 != 0 {
		// base-256
		var n int64
		for i, b := range field {
			if i == 0 {
				b &^= 0x80
			}
			n = (n << 8) | int64(b)
		}
		return n
	}
	s := strings.Trim(string(field), "\x00 ")
	if s == "" {
		return 0
	}
	n, _ := strconv.ParseInt(s, 8, 64)
	return n
}
