	hist[0] = cur
}
func finderCount(hist []int) int {
	n := hist[1]
	core := n > 0 && hist[2] == n && hist[3] == n*3 && hist[4] == n && hist[5] == n
	count := 0
	if core && hist[0] >= n*4 && hist[6] >= n {
		count++
	}
	if core && hist[6] >= n*4 && hist[0] >= n {
		count++
	}
	return count
}
func finderTerminate(isDark bool, cur int, hist []int, size int) int {
	if isDark {
		finderAddHistory(cur, hist, size)
		cur = 0
	}
	cur += size
	finderAddHistory(cur, hist, size)
	return finderCount(hist)
}
func penaltyLineNayuki(line []bool, size int) int {
	result := 0
	runColor := false
	runX := 0
	hist := make([]int, 7)
	for x := 0; x < size; x++ {
		if line[x] == runColor {
			runX++
			if runX == 5 {
				result += 3
			} else if runX > 5 {
				result++
			}
		} else {
			finderAddHistory(runX, hist, size)
			if !runColor {
				result += finderCount(hist) * 40
			}
			runColor = line[x]
			runX = 1
		}
	}
	result += finderTerminate(runColor, runX, hist, size) * 40
	return result
}
func qrPenaltyNayuki(grid [][]bool) int {
	size := len(grid)
	result := 0
	for r := 0; r < size; r++ {
		result += penaltyLineNayuki(grid[r], size)
		col := make([]bool, size)
		for rr := 0; rr < size; rr++ {
			col[rr] = grid[rr][r]
		}
		result += penaltyLineNayuki(col, size)
	}
	for r := 0; r < size-1; r++ {
		for c := 0; c < size-1; c++ {
			if grid[r][c] == grid[r][c+1] && grid[r][c] == grid[r+1][c] && grid[r][c] == grid[r+1][c+1] {
				result += 3
			}
		}
	}
	dark := 0
	for r := 0; r < size; r++ {
		for c := 0; c < size; c++ {
			if grid[r][c] {
				dark++
			}
		}
	}
	total := size * size
	num := dark*20 - total*10
	if num < 0 {
		num = -num
	}
	// ceil(num/total)-1 as in Nayuki integer formulation ((num + total -1)/total) gives ceil for num>0, 0 for num=0
	k := 0
	if num == 0 {
		k = -1
	} else {
		k = (num+total-1)/total - 1
	}
	result += k * 10
	return result
}
