package main

import "testing"

func penaltyArase(grid [][]bool) int {
	size := len(grid)
	lost := 0
	// LEVEL1 adjacency
	for r := 0; r < size; r++ {
		for c := 0; c < size; c++ {
			same := 0
			dark := grid[r][c]
			for dr := -1; dr <= 1; dr++ {
				for dc := -1; dc <= 1; dc++ {
					if dr == 0 && dc == 0 {
						continue
					}
					rr, cc := r+dr, c+dc
					if rr < 0 || rr >= size || cc < 0 || cc >= size {
						continue
					}
					if grid[rr][cc] == dark {
						same++
					}
				}
			}
			if same > 5 {
				lost += 3 + same - 5
			}
		}
	}
	// LEVEL2 2x2
	for r := 0; r < size-1; r++ {
		for c := 0; c < size-1; c++ {
			if grid[r][c] == grid[r][c+1] && grid[r][c] == grid[r+1][c] && grid[r][c] == grid[r+1][c+1] {
				lost += 3
			}
		}
	}
	// LEVEL3 via existing patternPenalty (with edge-inclusive logic)
	for r := 0; r < size; r++ {
		lost += patternPenalty(grid[r])
		col := make([]bool, size)
		for rr := 0; rr < size; rr++ {
			col[rr] = grid[rr][r]
		}
		lost += patternPenalty(col)
	}
	// LEVEL4 dark ratio floor
	dark := 0
	for r := 0; r < size; r++ {
		for c := 0; c < size; c++ {
			if grid[r][c] {
				dark++
			}
		}
	}
	total := size * size
	ratio := 100*dark/total - 50
	if dark*100%total != 0 {
		// use float ratio
	}
	fRatio := absf(float64(dark)*100.0/float64(total) - 50.0)
	lost += int(fRatio/5.0) * 10
	_ = ratio
	return lost
}
func absf(x float64) float64 { if x < 0 { return -x }; return x }

func TestArasePenaltyChoices(t *testing.T) {
	samples := []string{"http://a/", "http://127.0.0.1:56335/", "http://example.com/subdir/", "http://x/sp%20ace/", "http://127.0.0.1:12345/subdir/", "http://EXAMPLE.COM/", "http://verylonghostname.example.org/subdir/nested/", "http://127.0.0.1:39925/", "http://forward.example:9999/"}
	for _, s := range samples {
		data := []byte(s)
		_, size, _ := qrEncode(data)
		version := (size - 17) / 4
		bits := qrFinalBits(data, version)
		best, bestP := -1, 1<<60
		for mask := 0; mask < 8; mask++ {
			g := qrBuildMatrix(version, bits, mask)
			p := penaltyArase(g)
			t.Logf("%s mask %d arase=%d current=%d", s, mask, p, qrPenalty(g))
			if p < bestP { bestP = p; best = mask }
		}
		t.Logf("ARASE CHOICE %s -> %d", s, best)
	}
}
GO
go test -run TestArasePenaltyChoices -v 2>&1 | grep "ARASE CHOICE""}

