	_ = araseL1
	l2 := 0
	for r := 0; r < size-1; r++ { for c := 0; c < size-1; c++ { if grid[r][c]==grid[r][c+1] && grid[r][c]==grid[r+1][c] && grid[r][c]==grid[r+1][c+1] { l2 += 3 } } }
