	case 3: return isoL1 + l2 + l3rows + l4floor                 // ISO L1 + L3 rows only
	case 4: return araseL1 + l2 + l3rows + l3cols + l4floor + runPenalty2(grid)
	case 5: return araseL1 + l3rows + l3cols + l4floor           // no L2
	case 6: return isoL1 + l3rows + l3cols + l4floor             // ISO no L2
	case 7: return araseL1 + l2*2 + l3rows + l3cols + l4floor
	}
	return 0
}
