assert start!=-1 and end!=-1
new=r'''func qrPenalty(grid [][]bool) int {
	size := len(grid)
	penalty := 0
	// Rule 1 (Arase adjacency): modules with >5 same-colored neighbors (of 8)
	for r := 0; r < size; r++ {
		for c := 0; c < size; c++ {
			same := 0
			dark := grid[r][c]
			for dr := -1; dr <= 1; dr++ {
				for dc := -1; dc <= 1; dc++ {
					if dr == 0 && dc == 0 {
						continue
					}
					rr, cc := r+dr, c+dc
					if rr < 0 || rr >= size || cc < 0 || cc >= size {
						continue
					}
					if grid[rr][cc] == dark {
						same++
					}
				}
			}
			if same > 5 {
				penalty += 3 + same - 5
			}
		}
	}
	// Rule 2: 2x2 blocks of the same color
	for r := 0; r < size-1; r++ {
		for c := 0; c < size-1; c++ {
			if grid[r][c] == grid[r][c+1] && grid[r][c] == grid[r+1][c] && grid[r][c] == grid[r+1][c+1] {
				penalty += 3
			}
		}
	}
	// Rule 3: finder-like patterns in rows/columns
	for r := 0; r < size; r++ {
		penalty += patternPenalty(grid[r])
		col := make([]bool, size)
		for rr := 0; rr < size; rr++ {
			col[rr] = grid[rr][r]
		}
		penalty += patternPenalty(col)
	}
	// Rule 4: dark/light balance, 10 points per 5% step away from 50%
	dark := 0
	for r := 0; r < size; r++ {
		for c := 0; c < size; c++ {
			if grid[r][c] {
				dark++
			}
		}
	}
	total := size * size
	ratio := float64(dark) * 100.0 / float64(total)
	dev := ratio - 50.0
	if dev < 0 {
		dev = -dev
	}
	penalty += int(dev/5.0) * 10
	return penalty
}
'''
t=t[:start]+new+t[end:]
p.write_text(t)
